function historianConfiguredTags() {
  const tags = Array.isArray(state.historianConfig?.historian_tags)
    ? state.historianConfig.historian_tags
    : (Array.isArray(state.historianTags) ? state.historianTags : []);
  return tags
    .filter((t) => String(t?.connection_id || '').trim() && String(t?.tag_name || '').trim())
    .slice()
    .sort((a, b) => `${a.connection_id}:${a.tag_name}`.localeCompare(`${b.connection_id}:${b.tag_name}`, undefined, { sensitivity: 'base', numeric: true }));
}

function renderHistorianQueryTagSelect() {
  if (!els.historianQueryConfigured) return;
  const current = String(els.historianQueryConfigured.value || '');
  const tags = historianConfiguredTags();
  els.historianQueryConfigured.textContent = '';
  const empty = document.createElement('option');
  empty.value = '';
  empty.textContent = 'Select configured tag...';
  els.historianQueryConfigured.appendChild(empty);
  tags.forEach((t) => {
    const cid = String(t.connection_id || '').trim();
    const tag = String(t.tag_name || '').trim();
    const opt = document.createElement('option');
    opt.value = `${cid}:${tag}`;
    opt.textContent = `${displayConnectionName(cid)}:${tag}`;
    els.historianQueryConfigured.appendChild(opt);
  });
  if (current && Array.from(els.historianQueryConfigured.options).some((o) => o.value === current)) {
    els.historianQueryConfigured.value = current;
  }
}

function renderHistorianTags() {
  if (!els.historianTagsTbody) return;
  els.historianTagsTbody.textContent = '';
  const tags = historianConfiguredTags();
  renderHistorianQueryTagSelect();
  if (!tags.length) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 5;
    td.className = 'muted';
    td.textContent = 'No historized tags. Enable Historize in Workspace tag properties.';
    tr.appendChild(td);
    els.historianTagsTbody.appendChild(tr);
    return;
  }
  tags.forEach((t) => {
    const tr = document.createElement('tr');
    const mk = (text, mono = false) => {
      const td = document.createElement('td');
      if (mono) td.classList.add('mono');
      td.textContent = String(text ?? '');
      return td;
    };
    const cid = String(t.connection_id || '').trim();
    const tagName = String(t.tag_name || '').trim();
    const intervalMs = Math.max(1000, Math.trunc(Number(t.interval_ms || 60000) || 60000));
    const intervalSec = Math.round(intervalMs / 1000);
    tr.appendChild(mk(displayConnectionName(cid), true));
    tr.appendChild(mk(t.tag_name || '', true));
    tr.appendChild(mk(Boolean(t.enabled ?? true) ? 'Yes' : 'No'));
    tr.appendChild(mk(`${intervalSec} sec`));
    tr.appendChild(mk(t.mode || 'periodic'));
    tr.addEventListener('dblclick', () => {
      if (els.historianQueryConnection) els.historianQueryConnection.value = cid;
      if (els.historianQueryTag) els.historianQueryTag.value = tagName;
      runHistorianQuery().catch((err) => historianSetStatus(`Query failed: ${err.message || err}`));
    });
    els.historianTagsTbody.appendChild(tr);
  });
}

function normalizeHistorianConfig(cfg) {
  const root = (cfg && typeof cfg === 'object' && !Array.isArray(cfg)) ? { ...cfg } : {};
  const tags = Array.isArray(root.historian_tags) ? root.historian_tags : [];
  const seen = new Set();
  root.historian_tags = tags.map((t) => ({
    connection_id: String(t?.connection_id || '').trim(),
    tag_name: String(t?.tag_name || t?.name || '').trim(),
    enabled: Boolean(t?.enabled ?? true),
    interval_ms: Math.max(1000, Math.trunc(Number(t?.interval_ms || 60000) || 60000)),
    mode: String(t?.mode || 'periodic').trim() || 'periodic',
    include_bad_quality: Boolean(t?.include_bad_quality ?? false)
  })).filter((t) => {
    if (!t.connection_id || !t.tag_name) return false;
    const key = `${t.connection_id}:${t.tag_name}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  if (!root.postgres || typeof root.postgres !== 'object' || Array.isArray(root.postgres)) root.postgres = {};
  return root;
}

function normalizeTagHistorianSettings(tag) {
  const raw = (tag?.historian && typeof tag.historian === 'object' && !Array.isArray(tag.historian))
    ? tag.historian
    : {};
  const enabled = Boolean(raw.enabled ?? tag?.historian_enabled ?? false);
  const mode = String(raw.mode || tag?.historian_mode || 'periodic').trim().toLowerCase() || 'periodic';
  const intervalRaw = raw.interval_ms ?? tag?.historian_interval_ms ?? 60000;
  const interval_ms = Math.max(1000, Math.trunc(Number(intervalRaw || 60000) || 60000));
  return {
    enabled,
    mode: mode === 'periodic' ? 'periodic' : 'periodic',
    interval_ms,
    include_bad_quality: Boolean(raw.include_bad_quality ?? tag?.historian_include_bad_quality ?? false)
  };
}

function historianTagRulesFromWorkspaceTags(tags) {
  const seen = new Set();
  return (Array.isArray(tags) ? tags : []).map((tag) => {
    const cid = String(tag?.connection_id || '').trim();
    const name = String(tag?.name || '').trim();
    const h = normalizeTagHistorianSettings(tag);
    if (!cid || !name || !h.enabled) return null;
    const key = `${cid}:${name}`;
    if (seen.has(key)) return null;
    seen.add(key);
    return {
      connection_id: cid,
      tag_name: name,
      enabled: true,
      interval_ms: h.interval_ms,
      mode: h.mode,
      include_bad_quality: h.include_bad_quality
    };
  }).filter(Boolean);
}

async function saveHistorianConfigFromWorkspaceTags(tags) {
  const rules = historianTagRulesFromWorkspaceTags(tags);
  const current = state.historianConfig
    ? normalizeHistorianConfig(state.historianConfig)
    : normalizeHistorianConfig((await apiGet('/api/historian/config').catch(() => ({ config: {} })))?.config || {});
  current.historian_tags = rules;
  const resp = await apiPostJson('/api/historian/config', { config: current });
  if (!resp?.ok) throw new Error(String(resp?.error || 'Historian config save failed'));
  state.historianConfig = normalizeHistorianConfig(resp.config || current);
  state.historianConfigDirty = false;
  return rules.length;
}

function addHistorianTagFromSpec(spec) {
  const parts = loggerTagSpecParts(spec);
  if (!parts.connection_id || !parts.tag_name) return;
  if (!state.historianConfig) state.historianConfig = normalizeHistorianConfig({});
  if (!Array.isArray(state.historianConfig.historian_tags)) state.historianConfig.historian_tags = [];
  const exists = state.historianConfig.historian_tags.some((t) => String(t.connection_id || '') === parts.connection_id && String(t.tag_name || '') === parts.tag_name);
  if (exists) {
    historianSetStatus('Tag is already configured.');
    return;
  }
  state.historianConfig.historian_tags.push({
    connection_id: parts.connection_id,
    tag_name: parts.tag_name,
    enabled: true,
    interval_ms: 60000,
    mode: 'periodic',
    include_bad_quality: false
  });
  state.historianConfigDirty = true;
  renderHistorianTags();
  historianSetStatus('Config changed.');
}

function renderHistorianSummary() {
  if (!els.historianSummaryKv) return;
  const s = state.historianSummary || null;
  if (!s) {
    els.historianSummaryKv.innerHTML = '<div><b>Summary</b><span>No query yet</span></div>';
    return;
  }
  const count = Number(s.count || 0);
  const valueOrEmpty = (v) => (v == null ? '' : v);
  const rows = [
    ['Tag', `${s.connection_id || ''}:${s.tag_name || ''}`],
    ['Range', `${fmtTime(s.from_ms)} - ${fmtTime(s.to_ms)}`],
    ['Samples', count > 0 ? count : 'No samples yet'],
    ['Last', valueOrEmpty(s.last)],
    ['Min', valueOrEmpty(s.min)],
    ['Max', valueOrEmpty(s.max)],
    ['Avg', valueOrEmpty(s.avg)],
    ['TWA', valueOrEmpty(s.twa)]
  ];
  els.historianSummaryKv.innerHTML = rows.map(([k, v]) => `<div><b>${escapeHtml(k)}</b><span>${escapeHtml(String(v ?? ''))}</span></div>`).join('');
}

function historianRangeQueryParams(rangeValue) {
  const range = String(rangeValue || '1h').trim() || '1h';
  const params = {};
  const now = new Date();
  const startOfDay = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate(), 0, 0, 0, 0);
  const startOfMonth = (d) => new Date(d.getFullYear(), d.getMonth(), 1, 0, 0, 0, 0);
  if (range === 'current_day') {
    params.from_ms = String(startOfDay(now).getTime());
    params.to_ms = String(now.getTime());
  } else if (range === 'previous_day') {
    const today = startOfDay(now);
    const prev = new Date(today.getTime() - 24 * 60 * 60 * 1000);
    params.from_ms = String(prev.getTime());
    params.to_ms = String(today.getTime());
  } else if (range === 'current_month') {
    params.from_ms = String(startOfMonth(now).getTime());
    params.to_ms = String(now.getTime());
  } else if (range === 'previous_month') {
    const thisMonth = startOfMonth(now);
    const prevMonth = new Date(thisMonth.getFullYear(), thisMonth.getMonth() - 1, 1, 0, 0, 0, 0);
    params.from_ms = String(prevMonth.getTime());
    params.to_ms = String(thisMonth.getTime());
  } else {
    params.range = range;
  }
  return params;
}

function renderHistorianPoints() {
  if (!els.historianPointsTbody) return;
  els.historianPointsTbody.textContent = '';
  const bucketMode = String(state.historianQueryBucket || 'auto') !== 'raw';
  if (els.historianPointsTitle) els.historianPointsTitle.textContent = bucketMode ? 'Bucketed Points' : 'Raw Points';
  if (els.historianPointsHeadRow) {
    const headers = bucketMode
      ? ['Bucket', 'Count', 'Min', 'Max', 'Avg']
      : ['Timestamp', 'Value', 'Quality'];
    els.historianPointsHeadRow.innerHTML = headers.map((h) => `<th>${escapeHtml(h)}</th>`).join('');
  }
  const rows = bucketMode
    ? (Array.isArray(state.historianBuckets) ? state.historianBuckets : [])
    : (Array.isArray(state.historianPoints) ? state.historianPoints : []);
  if (!rows.length) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = bucketMode ? 5 : 3;
    td.className = 'small';
    td.textContent = state.historianSummary ? 'No points for this query.' : 'Run a query to view points.';
    tr.appendChild(td);
    els.historianPointsTbody.appendChild(tr);
    return;
  }
  rows.forEach((p) => {
    const tr = document.createElement('tr');
    const mk = (text, mono = false) => {
      const td = document.createElement('td');
      if (mono) td.classList.add('mono');
      td.textContent = String(text ?? '');
      return td;
    };
    if (bucketMode) {
      tr.appendChild(mk(`${fmtTime(p.bucket_start_ms)} - ${fmtTime(p.bucket_end_ms)}`, true));
      tr.appendChild(mk(p.count ?? '', true));
      tr.appendChild(mk(p.min ?? '', true));
      tr.appendChild(mk(p.max ?? '', true));
      tr.appendChild(mk(p.avg ?? '', true));
    } else {
      tr.appendChild(mk(fmtTime(p.ts_ms), true));
      tr.appendChild(mk(p.value, true));
      tr.appendChild(mk(p.quality ?? ''));
    }
    els.historianPointsTbody.appendChild(tr);
  });
}

async function refreshHistorianTab() {
  historianSetStatus('Loading...');
  const [health, tags, config] = await Promise.all([
    apiGet('/api/historian/runtime/status').catch((err) => ({ ok: false, error: String(err.message || err) })),
    apiGet('/api/historian/tags').catch((err) => ({ ok: false, error: String(err.message || err), tags: [] })),
    apiGet('/api/historian/config').catch((err) => ({ ok: false, error: String(err.message || err), config: null }))
  ]);
  state.historianRuntime = health?.ok ? health : { historian: null, error: health?.error || 'Historian unavailable' };
  state.historianTags = Array.isArray(tags?.tags) ? tags.tags : [];
  if (config?.ok) {
    state.historianConfig = normalizeHistorianConfig(config.config || {});
    state.historianConfigDirty = false;
  }
  renderHistorianHealth();
  renderHistorianTags();
  historianSetStatus(health?.ok ? 'Loaded' : `Unavailable: ${health?.error || 'failed'}`);
}

async function refreshHistorianRuntimeStatus() {
  if (state.historianHealthInFlight) return state.historianRuntime;
  state.historianHealthInFlight = true;
  try {
    const health = await apiGet('/api/historian/runtime/status');
    state.historianRuntime = health?.ok ? health : { historian: null, error: health?.error || 'Historian unavailable' };
    renderHistorianHealth();
    return health;
  } catch (err) {
    state.historianRuntime = { historian: null, error: String(err.message || err || 'Historian unavailable') };
    renderHistorianHealth();
    return state.historianRuntime;
  } finally {
    state.historianHealthInFlight = false;
  }
}

async function saveHistorianConfig() {
  if (!state.historianConfig) state.historianConfig = normalizeHistorianConfig({});
  historianSetStatus('Saving config...');
  const cfg = normalizeHistorianConfig(state.historianConfig);
  const resp = await apiPostJson('/api/historian/config', { config: cfg });
  if (!resp?.ok) throw new Error(String(resp?.error || 'Save failed'));
  state.historianConfig = normalizeHistorianConfig(resp.config || cfg);
  state.historianConfigDirty = false;
  renderHistorianTags();
  historianSetStatus('Saved. Restart historian to apply changes.');
}

async function restartHistorianService() {
  historianSetStatus('Applying historian config...');
  const resp = await apiPostJson('/api/historian/reload', {});
  if (!resp?.ok) throw new Error(String(resp?.error || 'Apply failed'));
  const warning = resp?.warning ? ` ${resp.warning}` : '';
  historianSetStatus(`Applied.${warning}`);
  window.setTimeout(() => refreshHistorianTab().catch((err) => historianSetStatus(`Refresh failed: ${err.message || err}`)), 500);
}

async function runHistorianQuery() {
  const cid = String(els.historianQueryConnection?.value || '').trim();
  const tag = String(els.historianQueryTag?.value || '').trim();
  const range = String(els.historianQueryRange?.value || '1h').trim() || '1h';
  const bucket = String(els.historianQueryBucket?.value || 'auto').trim() || 'auto';
  const limit = Math.max(1, Math.min(100000, Math.trunc(Number(els.historianQueryLimit?.value || 1000) || 1000)));
  if (!cid || !tag) throw new Error('Connection and tag are required.');
  historianSetStatus('Querying...');
  const qs = new URLSearchParams({ connection_id: cid, tag_name: tag, limit: String(limit) });
  const rangeParams = historianRangeQueryParams(range);
  Object.entries(rangeParams).forEach(([k, v]) => qs.set(k, String(v)));
  if (bucket) qs.set('bucket', bucket);
  const [summary, query] = await Promise.all([
    apiGet(`/api/historian/summary?${qs.toString()}`),
    apiGet(`/api/historian/query?${qs.toString()}`)
  ]);
  state.historianSummary = summary?.ok ? summary : null;
  state.historianQueryBucket = bucket;
  state.historianPoints = Array.isArray(query?.points) ? query.points : [];
  state.historianBuckets = Array.isArray(query?.buckets) ? query.buckets : [];
  renderHistorianSummary();
  renderHistorianPoints();
  const rowCount = bucket === 'raw' ? state.historianPoints.length : state.historianBuckets.length;
  historianSetStatus(`Query complete: ${rowCount} ${bucket === 'raw' ? 'point' : 'bucket'}(s)`);
}

function wireHistorianUi() {
  els.historianRefreshBtn?.addEventListener('click', () => refreshHistorianTab().catch((err) => historianSetStatus(`Refresh failed: ${err.message || err}`)));
  els.historianAddTagBtn?.addEventListener('click', () => openLoggerTagPickerModal({ mode: 'historian_add' }));
  els.historianSaveConfigBtn?.addEventListener('click', () => saveHistorianConfig().catch((err) => historianSetStatus(`Save failed: ${err.message || err}`)));
  els.historianRestartBtn?.addEventListener('click', () => restartHistorianService().catch((err) => historianSetStatus(`Restart failed: ${err.message || err}`)));
  els.historianRunQueryBtn?.addEventListener('click', () => runHistorianQuery().catch((err) => historianSetStatus(`Query failed: ${err.message || err}`)));
  els.historianQueryConfigured?.addEventListener('change', () => {
    const parts = loggerTagSpecParts(String(els.historianQueryConfigured?.value || ''));
    if (parts.connection_id && parts.tag_name) {
      if (els.historianQueryConnection) els.historianQueryConnection.value = parts.connection_id;
      if (els.historianQueryTag) els.historianQueryTag.value = parts.tag_name;
    }
  });
  els.historianQueryBucket?.addEventListener('change', () => {
    state.historianQueryBucket = String(els.historianQueryBucket?.value || 'auto') || 'auto';
    renderHistorianPoints();
  });
  renderHistorianHealth();
  renderHistorianSummary();
  renderHistorianPoints();
}

function loggerModalSetStatus(msg) {
  if (els.loggerDbModalStatus) els.loggerDbModalStatus.textContent = String(msg || '');
}

function buildLoggerTreeRoots() {
  const dbs = Array.isArray(state.reporterDatabases) ? state.reporterDatabases : [];
  const reports = Array.isArray(state.reporterReports) ? state.reporterReports : [];
  const checks = Array.isArray(state.reporterDataChecks) ? state.reporterDataChecks : [];
  const syncJobs = Array.isArray(state.reporterSyncJobs) ? state.reporterSyncJobs : [];

  const dbRoot = {
    id: 'logger:databases',
    type: 'logger_root_db',
    label: 'Databases',
    children: dbs
      .slice()
      .sort((a, b) => String(a?.name || a?.id || '').localeCompare(String(b?.name || b?.id || ''), undefined, { sensitivity: 'base' }))
      .map((d) => ({
        id: `logger:db:${String(d?.id || '').trim()}`,
        type: 'logger_db',
        label: String(d?.name || d?.id || '').trim() || '(unnamed)',
        meta: { id: String(d?.id || '').trim() }
      }))
  };

  const reportsRoot = {
    id: 'logger:reports',
    type: 'logger_root_reports',
    label: 'Logger',
    children: reports
      .slice()
      .sort((a, b) => String(a?.name || a?.id || '').localeCompare(String(b?.name || b?.id || ''), undefined, { sensitivity: 'base' }))
      .map((r) => ({
        id: `logger:report:${String(r?.id || '').trim()}`,
        type: 'logger_report',
        label: String(r?.name || r?.id || '').trim() || '(unnamed)',
        meta: { id: String(r?.id || '').trim() }
      }))
  };

  const checksRoot = {
    id: 'logger:data_checks',
    type: 'logger_root_data_checks',
    label: 'Data Checks',
    children: checks
      .slice()
      .sort((a, b) => String(a?.name || a?.id || '').localeCompare(String(b?.name || b?.id || ''), undefined, { sensitivity: 'base' }))
      .map((c) => ({
        id: `logger:data_check:${String(c?.id || '').trim()}`,
        type: 'logger_data_check',
        label: String(c?.name || c?.id || '').trim() || '(unnamed)',
        meta: { id: String(c?.id || '').trim() }
      }))
  };

  const syncRoot = {
    id: 'logger:sync_jobs', type: 'logger_root_sync', label: 'Database Sync',
    children: syncJobs.slice().sort((a, b) => String(a?.name || a?.id || '').localeCompare(String(b?.name || b?.id || ''), undefined, { sensitivity: 'base' }))
      .map((job) => ({ id: `logger:sync:${String(job?.id || '').trim()}`, type: 'logger_sync', label: String(job?.name || job?.id || '').trim(), meta: { id: String(job?.id || '').trim() } }))
  };

  return [dbRoot, reportsRoot, syncRoot, checksRoot];
}

function renderLoggerTreeNode(node, container) {
  const canExpand = node.type === 'logger_root_db' || node.type === 'logger_root_reports' || node.type === 'logger_root_data_checks' || node.type === 'logger_root_sync';
  const expanded = Boolean(state._loggerExpanded) ? state._loggerExpanded.has(node.id) : true;

  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'tree-item';
  btn.classList.toggle('is-active', state.loggerSelectedNodeId === node.id);

  const twisty = document.createElement('span');
  twisty.className = 'twisty';
  twisty.classList.toggle('is-empty', !canExpand);
  twisty.textContent = canExpand ? (expanded ? '−' : '+') : '';
  if (canExpand) {
    twisty.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (!state._loggerExpanded) state._loggerExpanded = new Set();
      if (state._loggerExpanded.has(node.id)) state._loggerExpanded.delete(node.id);
      else state._loggerExpanded.add(node.id);
      renderLoggerTree();
    });
  }

  const label = document.createElement('span');
  label.className = 'label';
  label.textContent = node.label;

  const meta = document.createElement('span');
  meta.className = 'meta';
  if (node.type === 'logger_root_db') meta.textContent = `${(node.children || []).length} db(s)`;
  if (node.type === 'logger_root_reports') meta.textContent = `${(node.children || []).length} job(s)`;
  if (node.type === 'logger_root_data_checks') meta.textContent = `${(node.children || []).length} check(s)`;
  if (node.type === 'logger_root_sync') meta.textContent = `${(node.children || []).length} job(s)`;

  btn.appendChild(twisty);
  btn.appendChild(label);
  btn.appendChild(meta);

  btn.addEventListener('click', () => {
    state.loggerSelectedNodeId = node.id;
    renderLoggerTree();
    renderLoggerDetails();
  });

  btn.addEventListener('contextmenu', (e) => {
    e.preventDefault();
    e.stopPropagation();

    state.loggerSelectedNodeId = node.id;
    renderLoggerTree();
    renderLoggerDetails();

    const items = [];
    if (node.type === 'logger_root_db') {
      items.push({ label: 'Add Database…', onClick: () => startNewDatabase() });
      items.push({ label: 'Refresh', onClick: () => refreshReporterAll().catch(() => {}) });
    }
    if (node.type === 'logger_root_reports') {
      items.push({ label: 'Add Log Job…', onClick: () => startNewReport() });
      items.push({ label: 'Refresh', onClick: () => refreshReporterAll().catch(() => {}) });
    }
    if (node.type === 'logger_root_data_checks') {
      items.push({ label: 'Add Data Check…', onClick: () => startNewDataCheck() });
      items.push({ label: 'Refresh', onClick: () => refreshReporterAll().catch(() => {}) });
    }
    if (node.type === 'logger_root_sync') {
      items.push({ label: 'Add Sync Job…', onClick: () => openLoggerSyncModal() });
      items.push({ label: 'Refresh', onClick: () => refreshReporterAll().catch(() => {}) });
    }
    if (node.type === 'logger_sync') {
      const id = String(node.meta?.id || '').trim();
      items.push({ label: 'Dry Run', onClick: () => testReporterSync(id) });
      items.push({ label: 'Run Now', onClick: () => runReporterSync(id) });
      items.push({ label: 'Historical Backfill…', onClick: () => openLoggerBackfillModal(id) });
      items.push({ label: 'Properties…', onClick: () => openLoggerSyncModal(id) });
      items.push({ label: 'Delete…', onClick: () => deleteReporterSync(id) });
    }
	    if (node.type === 'logger_db') {
	      const id = String(node.meta?.id || '').trim();
	      items.push({ label: 'Test Connection', onClick: () => testReporterDatabase(id) });
	      items.push({ label: 'Properties…', onClick: () => openLoggerDbModal({ mode: 'edit', id }) });
	      items.push({ label: 'Duplicate…', onClick: () => duplicateReporterDatabase(id) });
	      items.push({ label: 'Delete Database…', onClick: () => deleteReporterDatabase(id) });
	      items.push({ label: 'Refresh', onClick: () => refreshReporterAll().catch(() => {}) });
	    }
    if (node.type === 'logger_report') {
      const id = String(node.meta?.id || '').trim();
      items.push({ label: 'Validate', onClick: () => validateReporterReport(id) });
      items.push({ label: 'Run Now', onClick: () => runReporterReportNow(id) });
      items.push({ label: 'Download Tag CSV', onClick: () => downloadLoggerTagCsvForReport(findReportById(id)) });
      items.push({ label: 'Properties…', onClick: () => openLoggerReportModal({ mode: 'edit', id }) });
      items.push({ label: 'Duplicate…', onClick: () => duplicateReporterReport(id) });
      items.push({ label: 'Delete Log Job…', onClick: () => deleteReporterReport(id) });
      items.push({ label: 'Refresh', onClick: () => refreshReporterAll().catch(() => {}) });
    }
    if (node.type === 'logger_data_check') {
      const id = String(node.meta?.id || '').trim();
      items.push({ label: 'Test Query', onClick: () => testReporterDataCheck(id) });
      items.push({ label: 'Run Live Check', onClick: () => runReporterDataCheckNow(id) });
      items.push({ label: 'Properties…', onClick: () => openLoggerDataCheckModal({ mode: 'edit', id }) });
      items.push({ label: 'Duplicate…', onClick: () => duplicateReporterDataCheck(id) });
      items.push({ label: 'Delete Data Check…', onClick: () => deleteReporterDataCheck(id) });
      items.push({ label: 'Refresh', onClick: () => refreshReporterAll().catch(() => {}) });
    }
    if (items.length) showContextMenu(e.clientX, e.clientY, items);
  });

  container.appendChild(btn);

  if (canExpand && expanded) {
    const children = Array.isArray(node.children) ? node.children : [];
    if (children.length) {
      const div = document.createElement('div');
      div.className = 'tree-children';
      children.forEach((c) => renderLoggerTreeNode(c, div));
      container.appendChild(div);
    }
  }
}

function renderLoggerTree() {
  if (!els.loggerTreeView) return;
  els.loggerTreeView.textContent = '';
  const roots = buildLoggerTreeRoots();
  if (!state._loggerExpanded) state._loggerExpanded = new Set(['logger:databases', 'logger:reports', 'logger:sync_jobs', 'logger:data_checks']);
  roots.forEach((r) => renderLoggerTreeNode(r, els.loggerTreeView));
  if (els.loggerTreeNote) {
    const dbCount = Array.isArray(roots[0]?.children) ? roots[0].children.length : 0;
    const reportCount = Array.isArray(roots[1]?.children) ? roots[1].children.length : 0;
    const syncCount = Array.isArray(roots[2]?.children) ? roots[2].children.length : 0;
    const checkCount = Array.isArray(roots[3]?.children) ? roots[3].children.length : 0;
    els.loggerTreeNote.textContent = `Databases: ${dbCount} · Logger jobs: ${reportCount} · Sync jobs: ${syncCount} · Data checks: ${checkCount}`;
  }
  if (!state.loggerSelectedNodeId) state.loggerSelectedNodeId = 'logger:databases';
}

