  const o = state.cfg?.opcbridge || {};
  const scheme = String(o.scheme || 'http').trim() || 'http';
  const host = String(o.host || '127.0.0.1').trim() || '127.0.0.1';
  const port = Number(o.port || 8080) || 8080;
  return `${scheme}://${host}:${port}`;
