async function testReporterDataCheck(id) {
  const cid = String(id || '').trim();
  if (!cid) return;
  loggerSetStatus(`Testing data check '${cid}'…`);
  if (els.loggerDataCheckModal?.style?.display !== 'none' && els.loggerDataCheckStatus) {
    els.loggerDataCheckStatus.textContent = `Testing '${cid}'…`;
  }
  try {
    const resp = await apiPostJson('/api/logger/data-checks/test', { id: cid });
    const result = resp?.reporter_test?.json || resp;
    if (!resp?.ok) throw new Error(String(resp?.error || result?.error || 'Failed'));
    const value = String(result?.value ?? '');
    const latency = Number(result?.latency_ms || 0);
    const alarm = Boolean(result?.alarm);
    const detail = alarm
      ? `would alarm${result?.error ? `: ${result.error}` : ''}`
      : 'would be OK';
    const msg = `Test '${cid}' complete: value=${value || '(blank)'} ${detail} (${latency}ms). Live alarm state was not changed.`;
    loggerSetStatus(msg);
    if (els.loggerDataCheckModal?.style?.display !== 'none' && els.loggerDataCheckStatus) {
      els.loggerDataCheckStatus.textContent = msg;
    }
  } catch (err) {
    const msg = `Test failed: ${err.message || err}`;
    loggerSetStatus(msg);
    if (els.loggerDataCheckModal?.style?.display !== 'none' && els.loggerDataCheckStatus) {
      els.loggerDataCheckStatus.textContent = msg;
    }
  }
}

async function validateReporterReport(id) {
  const rid = String(id || '').trim();
  if (!rid) return;
  loggerSetStatus(`Validating log job '${rid}'…`);
  const result = {
    ok: false,
    id: rid,
    checked_at_ms: Date.now(),
    matched_count: 0,
    missing: [],
    errors: [],
    warnings: []
  };

  try {
    const report = findReportById(rid);
    if (!report) throw new Error(`Log job not found: ${rid}`);

    const dbId = String(report.database_id || '').trim();
    const db = findDatabaseById(dbId);
    if (!dbId) result.errors.push('Database is not selected.');
    else if (!db) result.errors.push(`Database not found: ${dbId}`);

    const table = String(report.table || '').trim();
    if (!table) result.errors.push('Table is required.');
    else if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(table)) result.errors.push('Table name should contain only letters, numbers, and underscores, and must not start with a number.');

    const mode = String(report.mode || 'scheduled').trim() || 'scheduled';
    if (mode !== 'scheduled') result.errors.push(`Unsupported log job mode: ${mode}`);
    const onCalendar = String(report?.schedule?.on_calendar || '').trim();
    if (!onCalendar) result.errors.push('Schedule is required.');
    else if (!reporterScheduleSupported(onCalendar)) result.errors.push(`Unsupported schedule: ${onCalendar}`);

    const selection = normalizeReporterTagSelection(report.tags);
    if (!selection.all && selection.entries.length < 1) result.errors.push('Tag selection is empty.');

    if (dbId && db) {
      try {
        const dbTest = await apiPostJson('/api/logger/databases/test', { id: dbId }, {
          timeoutMs: reporterDatabaseTestTimeoutMs(db)
        });
        result.database_test = dbTest?.reporter_test?.json || dbTest;
        if (!dbTest?.ok) result.errors.push(`Database test failed: ${dbTest?.error || result.database_test?.error || 'unknown error'}`);
      } catch (err) {
        result.errors.push(`Database test failed: ${err.message || err}`);
      }
    }

    if (selection.all) {
      const tagsResp = await apiGet('/api/opcbridge/tags', { timeoutMs: 30000 });
      const liveTags = Array.isArray(tagsResp?.tags) ? tagsResp.tags.filter((t) => !t.system) : [];
      result.matched_count = liveTags.length;
      if (result.matched_count < 1) result.errors.push('No live user tags matched ALL.');
    } else if (selection.entries.length) {
      const tagsResp = await apiGet('/api/opcbridge/tags', { timeoutMs: 30000 });
      const liveTags = Array.isArray(tagsResp?.tags) ? tagsResp.tags : [];
      const exact = new Set(liveTags.map((t) => `${String(t.connection_id || '')}\u001f${String(t.name || '')}`));
      const matched = new Set();
      selection.entries.forEach((entry) => {
        const name = String(entry.name || '');
        const hasGlob = name.includes('*') || name.includes('?');
        if (hasGlob) {
          let count = 0;
          liveTags.forEach((t) => {
            if (String(t.connection_id || '') === entry.connection_id && reporterGlobMatch(name, String(t.name || ''))) {
              matched.add(`${String(t.connection_id || '')}\u001f${String(t.name || '')}`);
              count++;
            }
          });
          if (count < 1) result.missing.push(`${entry.connection_id}:${name}`);
        } else {
          const key = `${entry.connection_id}\u001f${name}`;
          if (exact.has(key)) matched.add(key);
          else result.missing.push(`${entry.connection_id}:${name}`);
        }
      });
      result.matched_count = matched.size;
      if (result.matched_count < 1) result.errors.push('No selected tags matched live OPCBridge tags.');
      if (result.missing.length) result.warnings.push(`${result.missing.length} selected tag(s) did not match live tags.`);
    }

    result.ok = result.errors.length === 0;
    result.message = result.ok
      ? `OK. Matched ${result.matched_count} tag(s).`
      : result.errors.join(' ');
    state.reporterValidationById.set(rid, result);
    renderLoggerReportDetails();
    loggerSetStatus(`Validation ${result.ok ? 'OK' : 'failed'}: ${result.message}`);
  } catch (err) {
    result.errors.push(String(err.message || err));
    result.message = result.errors.join(' ');
    state.reporterValidationById.set(rid, result);
    renderLoggerReportDetails();
    loggerSetStatus(`Validation failed: ${err.message || err}`);
  }
}

async function runReporterReportNow(id) {
  const rid = String(id || '').trim();
  if (!rid) return;
  const before = reporterRuntimeStatusById().get(rid) || null;
  const beforeRuns = Number(before?.runs_total || 0);
  loggerSetStatus(`Starting log job '${rid}'…`);
  try {
    const resp = await apiPostJson('/api/logger/reports/run', { id: rid });
    if (!resp?.ok) throw new Error(String(resp?.error || resp?.reporter_run?.json?.error || 'Failed'));
    loggerSetStatus(`Log job '${rid}' started.`);
    await refreshReporterRuntimeStatus();
    watchReporterReportRun(rid, beforeRuns).catch(() => {});
  } catch (err) {
    loggerSetStatus(`Run failed: ${err.message || err}`);
  }
}

async function refreshReporterRuntimeStatus() {
  const runtime = await apiGet('/api/logger/runtime/status');
  state.reporterRuntime = runtime?.ok ? runtime : null;
  updateReporterDatabaseStatusMap(runtime);
  updateReporterDataCheckStatusMap(runtime);
  if (state.loggerSelectedNodeId === 'logger:reports' || String(state.loggerSelectedNodeId || '').startsWith('logger:report:')) {
    renderLoggerReportsTable();
    if (state.loggerReportPanelTab === 'details') renderLoggerReportDetails();
  } else if (state.loggerSelectedNodeId === 'logger:data_checks' || String(state.loggerSelectedNodeId || '').startsWith('logger:data_check:')) {
    renderLoggerDataChecksTable();
  } else if (state.loggerSelectedNodeId === 'logger:sync_jobs' || String(state.loggerSelectedNodeId || '').startsWith('logger:sync:')) {
    renderLoggerSyncTable();
  } else if (state.loggerSelectedNodeId === 'logger:databases' || String(state.loggerSelectedNodeId || '').startsWith('logger:db:')) {
    renderLoggerTable();
  }
  return runtime;
}

async function watchReporterReportRun(id, beforeRuns) {
  const rid = String(id || '').trim();
  if (!rid) return;
  if (state.loggerRunWatchIds.has(rid)) return;
  state.loggerRunWatchIds.add(rid);
  const started = Date.now();
  try {
    while (Date.now() - started < 120000) {
      const runtime = await refreshReporterRuntimeStatus();
      const statuses = Array.isArray(runtime?.reporter?.statuses) ? runtime.reporter.statuses : [];
      const st = statuses.find((s) => String(s?.id || '').trim() === rid) || null;
      const runs = Number(st?.runs_total || 0);
      if (st?.running) {
        loggerSetStatus(`Log job '${rid}' running…`);
      } else if (runs > beforeRuns) {
        if (st?.last_error) loggerSetStatus(`Log job '${rid}' finished with error.`);
        else loggerSetStatus(`Log job '${rid}' finished. Inserted ${Number(st?.last_inserted || 0)} row(s).`);
        return;
      }
      await new Promise((resolve) => window.setTimeout(resolve, 1000));
    }
    loggerSetStatus(`Log job '${rid}' still pending. Refresh for latest status.`);
  } finally {
    state.loggerRunWatchIds.delete(rid);
  }
}

async function refreshReporterAll() {
  loggerSetStatus('Loading…');
  const out = { ok: true };

  try {
    const cfg = await apiGet('/api/logger/config');
    if (cfg?.ok) state.reporterConfig = cfg.config || null;
    out.config = cfg;
  } catch (err) {
    out.ok = false;
    out.config = { ok: false, error: String(err.message || err) };
    state.reporterConfig = null;
  }

  try {
    const caps = await apiGet('/api/logger/capabilities');
    if (caps?.ok) state.reporterCapabilities = caps.capabilities || null;
    out.capabilities = caps;
  } catch (err) {
    out.ok = false;
    out.capabilities = { ok: false, error: String(err.message || err) };
    state.reporterCapabilities = null;
  }

  try {
    const db = await apiGet('/api/logger/databases');
    if (!db?.ok) throw new Error(String(db?.error || 'Failed'));
    state.reporterDatabases = Array.isArray(db?.databases) ? db.databases : [];
    out.databases = db;
  } catch (err) {
    out.ok = false;
    out.databases = { ok: false, error: String(err.message || err) };
    state.reporterDatabases = [];
  }

  try {
    const rep = await apiGet('/api/logger/reports');
    if (!rep?.ok) throw new Error(String(rep?.error || 'Failed'));
    state.reporterReports = Array.isArray(rep?.reports) ? rep.reports : [];
    out.reports = rep;
  } catch (err) {
    out.ok = false;
    out.reports = { ok: false, error: String(err.message || err) };
    state.reporterReports = [];
  }

  try {
    const checks = await apiGet('/api/logger/data-checks');
    if (!checks?.ok) throw new Error(String(checks?.error || 'Failed'));
    state.reporterDataChecks = Array.isArray(checks?.data_checks) ? checks.data_checks : [];
    out.data_checks = checks;
  } catch (err) {
    out.ok = false;
    out.data_checks = { ok: false, error: String(err.message || err) };
    state.reporterDataChecks = [];
  }

  try {
    const sync = await apiGet('/api/logger/sync-jobs');
    if (!sync?.ok) throw new Error(String(sync?.error || 'Failed'));
    state.reporterSyncJobs = Array.isArray(sync?.sync_jobs) ? sync.sync_jobs : [];
    out.sync_jobs = sync;
  } catch (err) {
    out.ok = false; state.reporterSyncJobs = []; out.sync_jobs = { ok: false, error: String(err.message || err) };
  }

  try {
    const runtime = await refreshReporterRuntimeStatus();
    out.runtime = runtime;
  } catch (err) {
    state.reporterRuntime = null;
    out.runtime = { ok: false, error: String(err.message || err) };
  }

  if (els.loggerJson) els.loggerJson.textContent = JSON.stringify(out, null, 2);
  if (!state.loggerSelectedNodeId) state.loggerSelectedNodeId = 'logger:databases';
  renderLoggerTree();
  renderLoggerDetails();
  loggerSetStatus(out.ok ? 'Ready.' : 'Partial failure (see Raw JSON).');
}

function loggerSyncOptions(select, values, selected = '') {
  if (!select) return;
  select.innerHTML = ['<option value=""></option>'].concat(values.map((value) => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`)).join('');
  select.value = selected;
}

function loggerSyncDatabaseOptions(select, databases, selected = '') {
  if (!select) return;
  select.innerHTML = ['<option value=""></option>'].concat((databases || []).map((database) => {
    const id = String(database?.id || '').trim();
    const label = String(database?.name || '').trim() || 'Unnamed connection';
    return `<option value="${escapeHtml(id)}">${escapeHtml(label)}</option>`;
  })).join('');
  select.value = selected;
}

function renderLoggerSyncTagPanels() {
  const selected = state.loggerSyncSelectedTags instanceof Set ? state.loggerSyncSelectedTags : new Set();
  const setA = new Set(state.loggerSyncTagsA || []), setB = new Set(state.loggerSyncTagsB || []);
  const bidirectional = els.loggerSyncDirection?.value === 'bidirectional';
  const available = bidirectional
    ? Array.from(new Set([...(state.loggerSyncTagsA || []), ...(state.loggerSyncTagsB || [])]))
    : [...(state.loggerSyncTagsA || [])];
  available.sort((a, b) => String(a).localeCompare(String(b), undefined, { sensitivity: 'base' }));
  const filter = String(els.loggerSyncTagFilter?.value || '').trim().toLowerCase();
  const filtered = available.filter((tag) => !filter || String(tag).toLowerCase().includes(filter));
  if (els.loggerSyncTagListHeading) els.loggerSyncTagListHeading.textContent = bidirectional ? 'Combined Database A and B tags' : 'Database A tags';
  if (els.loggerSyncTagList) {
    els.loggerSyncTagList.textContent = '';
    const fragment = document.createDocumentFragment();
    filtered.forEach((tag) => {
      const label = document.createElement('label'); label.className = 'sync-tag-option';
      const checkbox = document.createElement('input'); checkbox.type = 'checkbox'; checkbox.checked = selected.has(tag); checkbox.dataset.tag = tag;
      checkbox.addEventListener('change', () => {
        if (checkbox.checked) selected.add(tag); else selected.delete(tag);
        state.loggerSyncSelectedTags = selected;
        if (els.loggerSyncTagSelectionSummary) els.loggerSyncTagSelectionSummary.textContent = `${available.filter((value) => selected.has(value)).length} selected`;
      });
      const textNode = document.createElement('span'); textNode.textContent = tag;
      label.appendChild(checkbox); label.appendChild(textNode);
      if (bidirectional && setA.has(tag) !== setB.has(tag)) {
        const meta = document.createElement('span'); meta.className = 'small'; meta.style.marginLeft = 'auto'; meta.textContent = setA.has(tag) ? 'A only' : 'B only'; label.appendChild(meta);
      }
      fragment.appendChild(label);
    });
    if (!filtered.length) { const empty = document.createElement('div'); empty.className = 'small sync-tag-empty'; empty.textContent = available.length ? 'No tags match this filter.' : 'Load available tags to populate this list.'; fragment.appendChild(empty); }
    els.loggerSyncTagList.appendChild(fragment);
  }
  if (els.loggerSyncTagCount) els.loggerSyncTagCount.textContent = `${available.length} available · ${filtered.length} shown`;
  if (els.loggerSyncTagSelectionSummary) els.loggerSyncTagSelectionSummary.textContent = `${available.filter((tag) => selected.has(tag)).length} selected`;
}

async function loadLoggerSyncTags() {
  const request = (database_id, table, column) => apiPostJson('/api/logger/databases/distinct', { database_id, table, column }, { timeoutMs: 300000 });
  if (!els.loggerSyncSourceDatabase.value || !els.loggerSyncSourceTable.value || !els.loggerSyncSourceItem.value ||
      !els.loggerSyncDestinationDatabase.value || !els.loggerSyncDestinationTable.value || !els.loggerSyncDestinationItem.value) {
    throw new Error('Select both databases, tables, and tag columns first.');
  }
  if (els.loggerSyncStatus) els.loggerSyncStatus.textContent = 'Loading tags from Database A and Database B…';
  const [a, b] = await Promise.all([
    request(els.loggerSyncSourceDatabase.value, els.loggerSyncSourceTable.value, els.loggerSyncSourceItem.value),
    request(els.loggerSyncDestinationDatabase.value, els.loggerSyncDestinationTable.value, els.loggerSyncDestinationItem.value)
  ]);
  if (!a?.ok) throw new Error(`Database A: ${a?.error || 'tag discovery failed'}`);
  if (!b?.ok) throw new Error(`Database B: ${b?.error || 'tag discovery failed'}`);
  state.loggerSyncTagsA = (a.values || []).map(String);
  state.loggerSyncTagsB = (b.values || []).map(String);
  renderLoggerSyncTagPanels();
  if (els.loggerSyncStatus) els.loggerSyncStatus.textContent = `Loaded ${state.loggerSyncTagsA.length} Database A tag(s) and ${state.loggerSyncTagsB.length} Database B tag(s).`;
}

function clearLoggerSyncTags(side = '') {
  if (!side || side === 'source') state.loggerSyncTagsA = [];
  if (!side || side === 'destination') state.loggerSyncTagsB = [];
  renderLoggerSyncTagPanels();
}

function selectFilteredLoggerSyncTags() {
  const bidirectional = els.loggerSyncDirection?.value === 'bidirectional';
  const values = bidirectional ? Array.from(new Set([...state.loggerSyncTagsA, ...state.loggerSyncTagsB])) : state.loggerSyncTagsA;
  const filter = String(els.loggerSyncTagFilter?.value || '').trim().toLowerCase();
  (values || []).filter((tag) => !filter || String(tag).toLowerCase().includes(filter))
    .forEach((tag) => state.loggerSyncSelectedTags.add(tag));
  els.loggerSyncTagList?.querySelectorAll('input[type="checkbox"]').forEach((input) => { input.checked = true; });
  if (els.loggerSyncTagSelectionSummary) els.loggerSyncTagSelectionSummary.textContent = `${(values || []).filter((tag) => state.loggerSyncSelectedTags.has(tag)).length} selected`;
}

async function loadLoggerSyncSchema(side, databaseId, selectedTable = '', selectedTime = '', selectedItem = '') {
  const prefix = side === 'source' ? 'Source' : 'Destination';
  const tableSelect = els[`loggerSync${prefix}Table`];
  const timeSelect = els[`loggerSync${prefix}Time`];
  const itemSelect = els[`loggerSync${prefix}Item`];
  if (!databaseId) { loggerSyncOptions(tableSelect, []); loggerSyncOptions(timeSelect, []); loggerSyncOptions(itemSelect, []); return; }
  if (els.loggerSyncStatus) els.loggerSyncStatus.textContent = `Loading ${side} schema…`;
  const response = await apiGet(`/api/logger/databases/schema?database=${encodeURIComponent(databaseId)}`, { timeoutMs: 180000 });
  if (!response?.ok) throw new Error(response?.error || `Could not load ${side} schema.`);
  state.loggerSyncSchemas[side] = Array.isArray(response.tables) ? response.tables : [];
  loggerSyncOptions(tableSelect, state.loggerSyncSchemas[side].map((table) => String(table?.name || '')).filter(Boolean), selectedTable);
  updateLoggerSyncColumns(side, selectedTable, selectedTime, selectedItem);
  if (els.loggerSyncStatus) els.loggerSyncStatus.textContent = '';
}

function updateLoggerSyncColumns(side, tableName, selectedTime = '', selectedItem = '') {
  const prefix = side === 'source' ? 'Source' : 'Destination';
  const table = (state.loggerSyncSchemas[side] || []).find((entry) => String(entry?.name || '') === String(tableName || ''));
  const columns = (table?.columns || []).map((column) => String(column?.name || '')).filter(Boolean);
  if (!selectedTime) selectedTime = columns.find((name) => /(^|_)(datetime|timestamp|recorded_at|date_time|time_stamp)($|_)/i.test(name)) || columns.find((name) => /(date|time)/i.test(name)) || '';
  if (!selectedItem) selectedItem = columns.find((name) => /(^|_)(tag_name|tag|item_name|item|point_name|name)($|_)/i.test(name)) || '';
  loggerSyncOptions(els[`loggerSync${prefix}Time`], columns, selectedTime);
  loggerSyncOptions(els[`loggerSync${prefix}Item`], columns, selectedItem);
}

function suggestLoggerSyncMappings(showStatus = true) {
  const sourceTable = (state.loggerSyncSchemas.source || []).find((table) => String(table?.name || '') === els.loggerSyncSourceTable.value);
  const destinationTable = (state.loggerSyncSchemas.destination || []).find((table) => String(table?.name || '') === els.loggerSyncDestinationTable.value);
  const destinationExcluded = new Set([els.loggerSyncDestinationTime.value, els.loggerSyncDestinationItem.value]);
  const destinationColumns = new Set((destinationTable?.columns || [])
    .filter((column) => !/auto_increment|generated/i.test(String(column?.extra || '')))
    .map((column) => String(column?.name || ''))
    .filter((name) => !destinationExcluded.has(name)));
  const excluded = new Set([els.loggerSyncSourceTime.value, els.loggerSyncSourceItem.value]);
  const matches = (sourceTable?.columns || [])
    .filter((column) => !/auto_increment|generated/i.test(String(column?.extra || '')))
    .map((column) => String(column?.name || ''))
    .filter((name) => name && !excluded.has(name) && destinationColumns.has(name));
  els.loggerSyncMappings.value = matches.map((name) => `${name} = ${name}`).join('\n');
  if (showStatus) els.loggerSyncStatus.textContent = matches.length ? `Suggested ${matches.length} same-name mapping(s).` : 'No same-name value columns were found.';
}

function cleanLoggerSyncMappingText() {
  const sourceExcluded = new Set([els.loggerSyncSourceTime.value, els.loggerSyncSourceItem.value]);
  const destinationExcluded = new Set([els.loggerSyncDestinationTime.value, els.loggerSyncDestinationItem.value]);
  const lines = String(els.loggerSyncMappings?.value || '').split(/\r?\n/).filter((line) => {
    const parts = line.split('=').map((value) => value.trim());
    return parts.length >= 2 && parts[0] && parts[1] && !sourceExcluded.has(parts[0]) && !destinationExcluded.has(parts[1]);
  });
  if (els.loggerSyncMappings) els.loggerSyncMappings.value = lines.join('\n');
}

async function openLoggerSyncModal(id = '') {
  const job = (state.reporterSyncJobs || []).find((candidate) => String(candidate?.id || '') === String(id || '')) || {};
  state.loggerSyncEditingId = String(id || '');
  if (els.loggerSyncModal) els.loggerSyncModal.style.display = 'block';
  const syncDatabases = (state.reporterDatabases || []).filter((db) => ['mysql', 'odbc'].includes(String(db?.type || 'mysql')));
  loggerSyncDatabaseOptions(els.loggerSyncSourceDatabase, syncDatabases, String(job.source_database_id || ''));
  loggerSyncDatabaseOptions(els.loggerSyncDestinationDatabase, syncDatabases, String(job.destination_database_id || ''));
  els.loggerSyncName.value = String(job.name || '');
  els.loggerSyncEnabled.checked = Boolean(job.enabled); els.loggerSyncSchedule.value = String(job.schedule?.on_calendar || '*-*-* 01:00:00');
  els.loggerSyncDirection.value = String(job.direction || 'one_way');
  const configuredInterval = Number(job.match_interval_minutes ?? 60);
  els.loggerSyncMatchInterval.value = String([0, 1, 60, 1440].includes(configuredInterval) ? configuredInterval : 1);
  els.loggerSyncAllTags.checked = job.all_tags !== false;
  els.loggerSyncSelectedTagsWrap.style.display = els.loggerSyncAllTags.checked ? 'none' : '';
  els.loggerSyncLookback.value = String(job.lookback_days || 7);
  state.loggerSyncSelectedTags = new Set((job.tags || []).map(String));
  state.loggerSyncTagsA = []; state.loggerSyncTagsB = [];
  if (els.loggerSyncTagFilter) els.loggerSyncTagFilter.value = '';
  renderLoggerSyncTagPanels();
  els.loggerSyncMappings.value = (job.mappings || []).map((m) => `${m.source} = ${m.destination}`).join('\n');
  try {
    await Promise.all([
      loadLoggerSyncSchema('source', job.source_database_id, job.source_table, job.source_time_column, job.source_item_column),
      loadLoggerSyncSchema('destination', job.destination_database_id, job.destination_table, job.destination_time_column, job.destination_item_column)
    ]);
    cleanLoggerSyncMappingText();
    if (!job.mappings?.length && job.source_table && job.destination_table) suggestLoggerSyncMappings(false);
  } catch (err) { els.loggerSyncStatus.textContent = `Schema load failed: ${err.message || err}`; }
}

function closeLoggerSyncModal() { if (els.loggerSyncModal) els.loggerSyncModal.style.display = 'none'; }

function loggerSyncFromUi() {
  const specialSourceColumns = new Set([els.loggerSyncSourceTime.value, els.loggerSyncSourceItem.value]);
  const specialDestinationColumns = new Set([els.loggerSyncDestinationTime.value, els.loggerSyncDestinationItem.value]);
  const mappings = String(els.loggerSyncMappings?.value || '').split(/\r?\n/).map((line) => line.split('=').map((v) => v.trim()))
    .filter((parts) => parts.length >= 2 && parts[0] && parts[1] && !specialSourceColumns.has(parts[0]) && !specialDestinationColumns.has(parts[1]))
    .map((parts) => ({ source: parts[0], destination: parts[1] }));
  const availableTags = new Set(els.loggerSyncDirection.value === 'bidirectional'
    ? [...state.loggerSyncTagsA, ...state.loggerSyncTagsB]
    : state.loggerSyncTagsA);
  return { name: String(els.loggerSyncName.value || '').trim(), enabled: els.loggerSyncEnabled.checked,
    schedule: { on_calendar: String(els.loggerSyncSchedule.value || '').trim() }, lookback_days: Number(els.loggerSyncLookback.value || 7),
    direction: els.loggerSyncDirection.value, match_interval_minutes: Number(els.loggerSyncMatchInterval.value || 0), all_tags: els.loggerSyncAllTags.checked,
    source_database_id: els.loggerSyncSourceDatabase.value, source_table: els.loggerSyncSourceTable.value,
    source_time_column: els.loggerSyncSourceTime.value, source_item_column: els.loggerSyncSourceItem.value,
    destination_database_id: els.loggerSyncDestinationDatabase.value, destination_table: els.loggerSyncDestinationTable.value,
    destination_time_column: els.loggerSyncDestinationTime.value, destination_item_column: els.loggerSyncDestinationItem.value,
    tags: Array.from(state.loggerSyncSelectedTags || []).map(String).filter((tag) => tag && (!availableTags.size || availableTags.has(tag))).sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' })), mappings };
}

async function saveReporterSync() {
  try {
    els.loggerSyncStatus.textContent = 'Saving…';
    if (!String(els.loggerSyncMappings?.value || '').trim()) suggestLoggerSyncMappings(false);
    const job = loggerSyncFromUi();
    if (!job.source_time_column || !job.source_item_column || !job.destination_time_column || !job.destination_item_column) {
      throw new Error('OPCBridge could not identify the date/time or tag columns. Select them under Advanced column settings.');
    }
    if (!job.all_tags && !job.tags.length) throw new Error('Select at least one tag, or choose All tags.');
    if (!job.mappings.length) throw new Error('No matching value columns were found. Configure value mappings under Advanced column settings.');
    const response = await apiPostJson('/api/logger/sync-jobs', { sync_job: job, original_id: state.loggerSyncEditingId });
    if (!response?.ok) throw new Error(response?.error || 'Save failed.');
    const savedId = String(response?.sync_job?.id || state.loggerSyncEditingId || '').trim();
    await refreshReporterAll(); closeLoggerSyncModal(); state.loggerSelectedNodeId = savedId ? `logger:sync:${savedId}` : 'logger:sync_jobs'; renderLoggerTree(); renderLoggerDetails(); loggerSetStatus('Database sync job saved.');
  } catch (err) { els.loggerSyncStatus.textContent = `Save failed: ${err.message || err}`; }
}

async function testReporterSync(id) {
  const job = (state.reporterSyncJobs || []).find((candidate) => String(candidate?.id || '') === String(id)) || {};
  state.loggerSyncReview = { id, result: null, loading: true };
  if (els.loggerSyncReviewTitle) els.loggerSyncReviewTitle.textContent = `Database Sync Review — ${job.name || 'Sync job'}`;
  if (els.loggerSyncReviewModal) els.loggerSyncReviewModal.style.display = 'block';
  if (els.loggerSyncReviewGroups) {
    els.loggerSyncReviewGroups.innerHTML = '<div class="status status-degraded" role="status">Evaluating database records…</div><div class="hint" style="margin-top:8px;">Large data sets and slower database connections may take several minutes.</div>';
    els.loggerSyncReviewGroups.setAttribute('aria-busy', 'true');
  }
  if (els.loggerSyncReviewSummary) els.loggerSyncReviewSummary.textContent = '';
  if (els.loggerSyncReviewStatus) els.loggerSyncReviewStatus.textContent = 'Dry run is in progress. No records will be changed.';
  [els.loggerSyncExpandAllBtn, els.loggerSyncCollapseAllBtn, els.loggerSyncReviewFilter,
    els.loggerSyncReviewSearch, els.loggerSyncReviewRunBtn].forEach((control) => { if (control) control.disabled = true; });
  try {
    const response = await apiPostJson('/api/logger/sync-jobs/test', { id }, { timeoutMs: 300000 });
    const result = response?.reporter_result?.json || response;
    if (!response?.ok) throw new Error(response?.error || result?.error || 'Dry run failed.');
    state.loggerSyncReview = { id, result, loading: false };
    if (els.loggerSyncReviewGroups) els.loggerSyncReviewGroups.setAttribute('aria-busy', 'false');
    [els.loggerSyncExpandAllBtn, els.loggerSyncCollapseAllBtn, els.loggerSyncReviewFilter,
      els.loggerSyncReviewSearch].forEach((control) => { if (control) control.disabled = false; });
    renderLoggerSyncReview();
    const message = `Compared ${result.selected} record periods: ${result.a_to_b || 0} A→B, ${result.b_to_a || 0} B→A, ${result.conflicts || 0} conflicts.`;
    loggerSetStatus(message); if (els.loggerSyncStatus) els.loggerSyncStatus.textContent = message;
  } catch (err) {
    const message = `Dry run failed: ${err.message || err}`;
    state.loggerSyncReview = { id, result: null, loading: false, error: message };
    if (els.loggerSyncReviewGroups) {
      els.loggerSyncReviewGroups.setAttribute('aria-busy', 'false');
      els.loggerSyncReviewGroups.innerHTML = `<div class="status status-error" role="alert">${escapeHtml(message)}</div>`;
    }
    if (els.loggerSyncReviewStatus) els.loggerSyncReviewStatus.textContent = 'No records were changed.';
    if (els.loggerSyncReviewSummary) els.loggerSyncReviewSummary.textContent = '';
    [els.loggerSyncExpandAllBtn, els.loggerSyncCollapseAllBtn, els.loggerSyncReviewFilter,
      els.loggerSyncReviewSearch, els.loggerSyncReviewRunBtn].forEach((control) => { if (control) control.disabled = true; });
    loggerSetStatus(message);
  }
}

function renderLoggerSyncReview() {
  if (!els.loggerSyncReviewGroups) return;
  const review = state.loggerSyncReview || {};
  const result = review.result || {};
  const job = (state.reporterSyncJobs || []).find((candidate) => String(candidate?.id || '') === String(review.id || '')) || {};
  const filter = String(els.loggerSyncReviewFilter?.value || 'differences');
  const search = String(els.loggerSyncReviewSearch?.value || '').trim().toLowerCase();
  const mappings = Array.isArray(job.mappings) ? job.mappings : [];
  const mappedValues = (values) => {
    const raw = Array.isArray(values) ? values : [];
    if (!mappings.length) return [];
    const aligned = raw.slice(-mappings.length);
    while (aligned.length < mappings.length) aligned.unshift(null);
    return aligned;
  };
  const rows = Array.isArray(result.rows) ? result.rows : [];
  const visible = rows.filter((row) => {
    if (search && !String(row?.tag || '').toLowerCase().includes(search)) return false;
    if (filter === 'all') return true;
    if (filter === 'missing') return row.status === 'a_to_b' || row.status === 'b_to_a';
    if (filter === 'conflict') return row.status === 'conflict';
    return row.status !== 'matching' && row.status !== 'b_only';
  });
  const groups = new Map();
  visible.forEach((row) => { const tag = String(row?.tag || '(unnamed)'); if (!groups.has(tag)) groups.set(tag, []); groups.get(tag).push(row); });
  els.loggerSyncReviewGroups.textContent = '';
  if (els.loggerSyncReviewSummary) els.loggerSyncReviewSummary.textContent = `A→B ${result.a_to_b || 0} · B→A ${result.b_to_a || 0} · Matching ${result.matching || 0} · Conflicts ${result.conflicts || 0}`;
  if (els.loggerSyncReviewRunBtn) els.loggerSyncReviewRunBtn.disabled = (Number(result.a_to_b || 0) + Number(result.b_to_a || 0)) < 1;
  Array.from(groups.entries()).sort((a, b) => a[0].localeCompare(b[0], undefined, { sensitivity: 'base' })).forEach(([tag, tagRows]) => {
    const counts = { missing: 0, conflict: 0, matching: 0 };
    tagRows.forEach((row) => { if (row.status === 'conflict') counts.conflict++; else if (row.status === 'matching') counts.matching++; else if (row.status === 'a_to_b' || row.status === 'b_to_a') counts.missing++; });
    const details = document.createElement('details'); details.className = 'details'; details.style.marginBottom = '8px'; details.open = counts.missing > 0 || counts.conflict > 0;
    const summary = document.createElement('summary'); summary.textContent = `${tag} — ${counts.missing} missing · ${counts.conflict} conflict${counts.conflict === 1 ? '' : 's'} · ${counts.matching} matching`; details.appendChild(summary);
    const wrap = document.createElement('div'); wrap.className = 'table-wrap'; wrap.style.marginTop = '8px';
    const table = document.createElement('table'); table.className = 'table';
    const thead = document.createElement('thead'); const head = document.createElement('tr');
    ['Period', 'Database A time', ...mappings.map((m) => `A: ${m.source}`), 'Status', 'Database B time', ...mappings.map((m) => `B: ${m.destination}`)].forEach((label) => { const th = document.createElement('th'); th.textContent = label; head.appendChild(th); });
    thead.appendChild(head); table.appendChild(thead); const tbody = document.createElement('tbody');
    tagRows.forEach((row) => {
      const tr = document.createElement('tr');
      if (row.status === 'conflict') tr.style.background = 'rgba(220, 53, 69, 0.18)';
      else if (row.status === 'a_to_b' || row.status === 'b_to_a') tr.style.background = 'rgba(255, 193, 7, 0.16)';
      const statusLabels = { a_to_b: 'A → B', b_to_a: 'B → A', matching: 'Matching', conflict: 'Conflict', b_only: 'B only (one-way)' };
      const values = [row.bucket, row.a_timestamp || '—', ...mappedValues(row.a_values).map((v) => v ?? '—'), statusLabels[row.status] || row.status, row.b_timestamp || '—', ...mappedValues(row.b_values).map((v) => v ?? '—')];
      values.forEach((value) => { const td = document.createElement('td'); td.textContent = String(value ?? ''); tr.appendChild(td); }); tbody.appendChild(tr);
    });
    table.appendChild(tbody); wrap.appendChild(table); details.appendChild(wrap); els.loggerSyncReviewGroups.appendChild(details);
  });
  if (!groups.size) { const empty = document.createElement('div'); empty.className = 'hint'; empty.textContent = 'No records match the current filter.'; els.loggerSyncReviewGroups.appendChild(empty); }
  if (els.loggerSyncReviewStatus) els.loggerSyncReviewStatus.textContent = result.rows_truncated ? 'The detailed view is limited to 10,000 rows. Reduce the lookback period to review all rows.' : `${visible.length} row(s) shown.`;
}

async function runReporterSync(id) {
  const job = (state.reporterSyncJobs || []).find((candidate) => String(candidate?.id || '') === String(id)) || {};
  const response = await apiPostJson('/api/logger/sync-jobs/run', { id });
  if (!response?.ok) { loggerSetStatus(`Run failed: ${response?.error || 'unknown error'}`); return; }
  loggerSetStatus(`Database sync '${job.name || 'job'}' started.`); window.setTimeout(() => refreshReporterRuntimeStatus().catch(() => {}), 1000);
}

async function deleteReporterSync(id) {
  const job = (state.reporterSyncJobs || []).find((candidate) => String(candidate?.id || '') === String(id)) || {};
  if (!window.confirm(`Delete database sync job '${job.name || 'this job'}'?`)) return;
  const response = await apiPostJson('/api/logger/sync-jobs/delete', { id });
  if (!response?.ok) { loggerSetStatus(`Delete failed: ${response?.error || 'unknown error'}`); return; }
  state.loggerSelectedNodeId = 'logger:sync_jobs'; await refreshReporterAll();
}

function loggerLocalDateTime(date) {
  const pad = (value) => String(value).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function loggerBackfillTasks() {
  return Array.isArray(state.reporterRuntime?.reporter?.backfills) ? state.reporterRuntime.reporter.backfills : [];
}

function loggerBackfillPercent(task) {
  const parseTime = (value) => new Date(String(value || '').replace(' ', 'T')).getTime();
  const start = parseTime(task?.start_time), end = parseTime(task?.end_time), cursor = parseTime(task?.cursor_time);
  return Number.isFinite(start) && Number.isFinite(end) && end > start && Number.isFinite(cursor)
    ? Math.max(0, Math.min(100, Math.round(((cursor - start) / (end - start)) * 100))) : 0;
}

async function openLoggerBackfillModal(jobId) {
  const job = (state.reporterSyncJobs || []).find((candidate) => String(candidate?.id || '') === String(jobId || '')) || {};
  state.loggerBackfillJobId = String(jobId || '');
  state.loggerBackfillTaskId = '';
  if (els.loggerBackfillTitle) els.loggerBackfillTitle.textContent = `Historical Backfill — ${job.name || 'Sync job'}`;
  if (els.loggerBackfillModal) els.loggerBackfillModal.style.display = 'block';
  if (els.loggerBackfillSetup) els.loggerBackfillSetup.style.display = 'none';
  if (els.loggerBackfillProgress) els.loggerBackfillProgress.style.display = 'none';
  if (els.loggerBackfillStatus) els.loggerBackfillStatus.textContent = 'Checking Logger for an existing backfill…';
  try { await refreshReporterRuntimeStatus(); }
  catch (err) {
    if (els.loggerBackfillStatus) els.loggerBackfillStatus.textContent = `Could not check backfill status: ${err.message || err}`;
    return;
  }
  const running = loggerBackfillTasks().filter((task) => task.sync_job_id === state.loggerBackfillJobId && task.status === 'running').sort((a, b) => Number(b.created_ms || 0) - Number(a.created_ms || 0))[0];
  if (running) {
    state.loggerBackfillTaskId = String(running.id || '');
    renderLoggerBackfillProgress(running);
    scheduleLoggerBackfillPoll();
  } else {
    if (els.loggerBackfillSetup) els.loggerBackfillSetup.style.display = '';
    if (els.loggerBackfillProgress) els.loggerBackfillProgress.style.display = 'none';
    const latest = loggerBackfillTasks().filter((task) => task.sync_job_id === state.loggerBackfillJobId).sort((a, b) => Number(b.created_ms || 0) - Number(a.created_ms || 0))[0];
    if (els.loggerBackfillStatus) els.loggerBackfillStatus.textContent = latest
      ? `Previous backfill status: ${latest.status || 'unknown'}${latest.last_error ? ` — ${latest.last_error}` : ''}` : '';
    if (els.loggerBackfillStart) els.loggerBackfillStart.value = '';
    if (els.loggerBackfillEnd) els.loggerBackfillEnd.value = '';
  }
}

function closeLoggerBackfillModal() {
  if (state.loggerBackfillPollTimer) window.clearTimeout(state.loggerBackfillPollTimer);
  state.loggerBackfillPollTimer = 0;
  if (els.loggerBackfillModal) els.loggerBackfillModal.style.display = 'none';
}

function renderLoggerBackfillProgress(task) {
  if (!task) return;
  if (els.loggerBackfillSetup) els.loggerBackfillSetup.style.display = 'none';
  if (els.loggerBackfillProgress) els.loggerBackfillProgress.style.display = '';
  const percent = loggerBackfillPercent(task);
  const rows = [
    ['Status', task.status || ''], ['Progress', `${percent}%`], ['Completed through', task.cursor_time || ''],
    ['Range', `${task.start_time || ''} → ${task.end_time || ''}`], ['Chunks completed', task.chunks_completed || 0],
    ['A → B', task.a_to_b || 0], ['B → A', task.b_to_a || 0], ['Inserted', task.inserted || 0],
    ['Skipped', task.skipped || 0], ['Failed', task.failed || 0]
  ];
  if (els.loggerBackfillKv) {
    els.loggerBackfillKv.innerHTML = rows.map(([key, value]) => `<div class="k">${escapeHtml(String(key))}</div><div class="v mono">${escapeHtml(String(value))}</div>`).join('');
  }
  if (els.loggerBackfillCancelBtn) els.loggerBackfillCancelBtn.disabled = task.status !== 'running';
  if (els.loggerBackfillStatus) els.loggerBackfillStatus.textContent = task.last_error ? `Error: ${task.last_error}` : (task.status === 'complete' ? 'Historical backfill completed.' : task.status === 'cancelled' ? 'Historical backfill cancelled.' : 'Progress is saved after every chunk.');
}

function scheduleLoggerBackfillPoll() {
  if (state.loggerBackfillPollTimer) window.clearTimeout(state.loggerBackfillPollTimer);
  state.loggerBackfillPollTimer = window.setTimeout(async () => {
    state.loggerBackfillPollTimer = 0;
    if (els.loggerBackfillModal?.style?.display === 'none') return;
    try {
      await refreshReporterRuntimeStatus();
    } catch {
      if (els.loggerBackfillStatus) {
        els.loggerBackfillStatus.textContent = 'Progress temporarily unavailable. The backfill continues in Logger; log in again to reconnect.';
      }
      scheduleLoggerBackfillPoll();
      return;
    }
    const task = loggerBackfillTasks().find((candidate) => String(candidate?.id || '') === state.loggerBackfillTaskId);
    if (task) renderLoggerBackfillProgress(task);
    if (task?.status === 'running') scheduleLoggerBackfillPoll();
    else if (!task && els.loggerBackfillStatus) {
      els.loggerBackfillStatus.textContent = 'Backfill status is not currently available. Close and reopen this window to reconnect.';
    }
  }, 2000);
}

async function startLoggerBackfill() {
  try {
    const startDate = String(els.loggerBackfillStart?.value || '').trim();
    const endDate = String(els.loggerBackfillEnd?.value || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate)) throw new Error('Start date is required.');
    const start = `${startDate} 00:00:00`;
    let end = loggerLocalDateTime(new Date());
    if (endDate) {
      const date = new Date(`${endDate}T00:00:00`);
      if (!Number.isFinite(date.getTime())) throw new Error('End date is invalid.');
      date.setDate(date.getDate() + 1);
      end = loggerLocalDateTime(date);
    }
    els.loggerBackfillStatus.textContent = 'Starting historical backfill…';
    const response = await apiPostJson('/api/logger/sync-jobs/backfill', { id: state.loggerBackfillJobId, start_time: start, end_time: end }, { timeoutMs: 30000 });
    if (!response?.ok) throw new Error(response?.error || 'Backfill could not be started.');
    state.loggerBackfillTaskId = String(response?.backfill?.id || '');
    await refreshReporterRuntimeStatus();
    const task = loggerBackfillTasks().find((candidate) => String(candidate?.id || '') === state.loggerBackfillTaskId) || response.backfill;
    renderLoggerBackfillProgress(task); scheduleLoggerBackfillPoll();
  } catch (err) { els.loggerBackfillStatus.textContent = `Start failed: ${err.message || err}`; }
}

async function cancelLoggerBackfill() {
  if (!state.loggerBackfillTaskId || !window.confirm('Cancel this historical backfill after its current chunk finishes?')) return;
  const response = await apiPostJson('/api/logger/sync-jobs/backfill/cancel', { id: state.loggerBackfillTaskId });
  if (!response?.ok) { els.loggerBackfillStatus.textContent = `Cancel failed: ${response?.error || 'unknown error'}`; return; }
  els.loggerBackfillStatus.textContent = 'Cancellation requested. The current chunk will finish first.';
  scheduleLoggerBackfillPoll();
}

