function selectedPublishedReport() {
  const id = String(els.publishedReportSelect?.value || '').trim();
  return state.publishedReports.find((report) => String(report?.id || '') === id) || null;
}

function localIsoDate(date = new Date()) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function configurePublishedReportPeriod(report) {
  const period = String(report?.period || 'month');
  const custom = period === 'custom';
  if (els.publishedReportSinglePeriod) els.publishedReportSinglePeriod.style.display = custom ? 'none' : '';
  if (els.publishedReportCustomPeriod) els.publishedReportCustomPeriod.style.display = custom ? '' : 'none';
  const now = new Date();
  if (custom) {
    if (els.publishedReportStartDate && !els.publishedReportStartDate.value) {
      els.publishedReportStartDate.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`;
    }
    if (els.publishedReportEndDate && !els.publishedReportEndDate.value) {
      els.publishedReportEndDate.value = localIsoDate(now);
    }
    return;
  }
  if (!els.publishedReportMonth) return;
  const labels = { daily: 'Report date', weekly: 'Week containing', month: 'Report month', yearly: 'Report year' };
  const units = { daily: 'day', weekly: 'week', month: 'month', yearly: 'year' };
  els.publishedReportPeriodLabel.textContent = labels[period] || labels.month;
  els.publishedReportMonth.type = ['daily', 'weekly'].includes(period) ? 'date' : (period === 'yearly' ? 'number' : 'month');
  els.publishedReportMonth.removeAttribute('min');
  els.publishedReportMonth.removeAttribute('max');
  if (['daily', 'weekly'].includes(period) && !/^\d{4}-\d{2}-\d{2}$/.test(els.publishedReportMonth.value)) {
    els.publishedReportMonth.value = localIsoDate(now);
  } else if (period === 'yearly') {
    els.publishedReportMonth.min = '2000';
    els.publishedReportMonth.max = '2100';
    if (!/^\d{4}$/.test(els.publishedReportMonth.value)) els.publishedReportMonth.value = String(now.getFullYear());
  } else if (period === 'month' && !/^\d{4}-\d{2}$/.test(els.publishedReportMonth.value)) {
    els.publishedReportMonth.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  }
  const unit = units[period] || 'month';
  [els.publishedReportPreviousBtn, els.publishedReportNextBtn].forEach((button, index) => {
    if (!button) return;
    const label = `${index === 0 ? 'Previous' : 'Next'} ${unit}`;
    button.title = label;
    button.setAttribute('aria-label', label);
  });
}

function publishedReportRangePayload() {
  const report = selectedPublishedReport();
  const period = String(report?.period || 'month');
  if (period === 'custom') {
    const start_date = String(els.publishedReportStartDate?.value || '');
    const end_date = String(els.publishedReportEndDate?.value || '');
    return /^\d{4}-\d{2}-\d{2}$/.test(start_date) && /^\d{4}-\d{2}-\d{2}$/.test(end_date)
      ? { start_date, end_date } : null;
  }
  const value = String(els.publishedReportMonth?.value || '').trim();
  const valid = ['daily', 'weekly'].includes(period) ? /^\d{4}-\d{2}-\d{2}$/.test(value)
    : period === 'yearly' ? /^\d{4}$/.test(value)
      : /^\d{4}-\d{2}$/.test(value);
  return valid ? { period_value: value } : null;
}

function shiftPublishedReportPeriod(direction) {
  const period = String(selectedPublishedReport()?.period || 'month');
  const value = String(els.publishedReportMonth?.value || '').trim();
  let next = '';
  if (['daily', 'weekly'].includes(period) && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
    const date = new Date(`${value}T12:00:00`);
    date.setDate(date.getDate() + direction * (period === 'weekly' ? 7 : 1));
    next = localIsoDate(date);
  } else if (period === 'yearly' && /^\d{4}$/.test(value)) {
    next = String(Number(value) + direction);
  } else if (period === 'month' && /^(\d{4})-(\d{2})$/.test(value)) {
    const match = value.match(/^(\d{4})-(\d{2})$/);
    const date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1 + direction, 1));
    next = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
  }
  if (!next) return;
  els.publishedReportMonth.value = next;
  previewPublishedReport().catch(() => {});
}

function shiftPublishedCustomRange(direction) {
  const start = new Date(`${els.publishedReportStartDate?.value || ''}T12:00:00`);
  const end = new Date(`${els.publishedReportEndDate?.value || ''}T12:00:00`);
  if (!Number.isFinite(start.getTime()) || !Number.isFinite(end.getTime()) || end < start) return;
  const days = Math.round((end - start) / 86400000) + 1;
  start.setDate(start.getDate() + direction * days);
  end.setDate(end.getDate() + direction * days);
  els.publishedReportStartDate.value = localIsoDate(start);
  els.publishedReportEndDate.value = localIsoDate(end);
  previewPublishedReport().catch(() => {});
}

function renderPublishedReportSelection() {
  if (!els.publishedReportSelect || !els.publishedReportFormat) return;
  const previousId = String(els.publishedReportSelect.value || '').trim();
  els.publishedReportSelect.textContent = '';
  if (!state.publishedReports.length) {
    const option = document.createElement('option');
    option.value = '';
    option.textContent = 'No reports available';
    els.publishedReportSelect.appendChild(option);
  }
  state.publishedReports.forEach((report) => {
    const option = document.createElement('option');
    option.value = String(report.id || '');
    option.textContent = `${report.published === false ? '[Draft] ' : ''}${report.name || report.id || ''}`;
    els.publishedReportSelect.appendChild(option);
  });
  if (state.publishedReports.some((report) => String(report.id || '') === previousId)) {
    els.publishedReportSelect.value = previousId;
  }

  const report = selectedPublishedReport();
  configurePublishedReportPeriod(report);
  els.publishedReportFormat.textContent = '';
  (Array.isArray(report?.formats) ? report.formats : []).forEach((format) => {
    const option = document.createElement('option');
    option.value = String(format);
    option.textContent = format === 'xlsx' ? 'Excel Workbook (.xlsx)'
      : (format === 'ods' ? 'OpenDocument Spreadsheet (.ods)' : 'CSV (.csv)');
    els.publishedReportFormat.appendChild(option);
  });
  if (els.publishedReportDescription) {
    els.publishedReportDescription.textContent = report?.description || '';
  }
  if (els.publishedReportTitle) {
    els.publishedReportTitle.textContent = report?.name || '';
  }
  if (els.publishedReportEmpty) {
    els.publishedReportEmpty.style.display = report ? 'none' : '';
  }
  if (els.publishedReportPreviewWrap && !report) {
    els.publishedReportPreviewWrap.style.display = 'none';
  }
  const permissions = reportPermissions(report);
  if (els.publishedReportDownloadBtn) {
    els.publishedReportDownloadBtn.disabled = !report || report.published === false || !permissions.download;
  }
  if (els.publishedReportPreviousBtn) els.publishedReportPreviousBtn.disabled = !report;
  if (els.publishedReportNextBtn) els.publishedReportNextBtn.disabled = !report;
  if (els.publishedReportCustomPreviousBtn) els.publishedReportCustomPreviousBtn.disabled = !report;
  if (els.publishedReportCustomNextBtn) els.publishedReportCustomNextBtn.disabled = !report;
  const canCreate = canCreateReports();
  if (els.publishedReportEmpty && !report) {
    els.publishedReportEmpty.textContent = canCreate
      ? 'No reports are available. Select New Report to create the first one.'
      : 'No reports are available through your groups.';
  }
  if (els.reportBuilderEditBtn) {
    els.reportBuilderEditBtn.style.display = report && permissions.edit ? '' : 'none';
    els.reportBuilderEditBtn.disabled = !report || !permissions.edit;
  }
  if (els.reportBuilderNewBtn) els.reportBuilderNewBtn.style.display = canCreate ? '' : 'none';
  if (els.reportBuilderManageDataSourcesBtn) {
    els.reportBuilderManageDataSourcesBtn.style.display = hasPerm('reports.administer') ? '' : 'none';
  }
}

async function refreshPublishedReports(loadPreview = true) {
  if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = 'Loading…';
  try {
    const [response, editableResponse] = await Promise.all([
      apiGet('/api/reports'),
      canCreateReports()
        ? apiGet('/api/reports/admin').catch(() => ({ reports: [] }))
        : Promise.resolve({ reports: [] })
    ]);
    const reportsById = new Map();
    (Array.isArray(response?.reports) ? response.reports : []).forEach((report) => {
      const id = String(report?.id || '').trim();
      if (id) reportsById.set(id, report);
    });
    (Array.isArray(editableResponse?.reports) ? editableResponse.reports : []).forEach((report) => {
      const id = String(report?.id || '').trim();
      if (id && !reportsById.has(id)) reportsById.set(id, report);
    });
    state.publishedReports = Array.from(reportsById.values()).sort((left, right) => {
      const leftName = String(left?.name || left?.id || '');
      const rightName = String(right?.name || right?.id || '');
      const byName = leftName.localeCompare(rightName, undefined, { sensitivity: 'base', numeric: true });
      return byName || String(left?.id || '').localeCompare(String(right?.id || ''), undefined, { sensitivity: 'base', numeric: true });
    });
    renderPublishedReportSelection();
    if (els.publishedReportsStatus) {
      els.publishedReportsStatus.textContent = state.publishedReports.length
        ? `${state.publishedReports.length} report(s) available`
        : 'No reports are available.';
    }
    if (loadPreview && selectedPublishedReport()) await previewPublishedReport();
  } catch (err) {
    state.publishedReports = [];
    renderPublishedReportSelection();
    if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = String(err.message || err);
  }
}

function renderPublishedReportPreview(preview) {
  if (!els.publishedReportPreviewHead || !els.publishedReportPreviewBody || !els.publishedReportPreviewWrap) return;
  els.publishedReportPreviewHead.textContent = '';
  els.publishedReportPreviewBody.textContent = '';
  els.publishedReportPreviewBody.parentElement?.querySelectorAll('colgroup').forEach((item) => item.remove());
  const layout = preview.layout && typeof preview.layout === 'object' ? preview.layout : {};
  const tableRow = Math.max(1, Math.trunc(Number(layout.table_start_row || 5)));
  const headerRows = layout.include_header_row === false ? 0 : 1;
  const tableColumn = spreadsheetColumnIndex(layout.table_start_column || 'A') || 1;
  const columns = Array.isArray(preview.columns) ? preview.columns : [];
  const placements = columns.map((column, index) => spreadsheetColumnIndex(column.sheet_column) || tableColumn + index + 1);
  const cells = new Map();
  const put = (row, column, text, className = '') => {
    if (row > 0 && column > 0) cells.set(`${row}:${column}`, {
      ...(cells.get(`${row}:${column}`) || {}), text, className
    });
  };
  const templatePreview = preview.template_preview && typeof preview.template_preview === 'object'
    ? preview.template_preview : null;
  els.publishedReportPreviewBody.parentElement?.classList.toggle('has-template-preview', Boolean(templatePreview));
  const previewClass = (fallback) => templatePreview ? 'layout-template-value' : fallback;
  (templatePreview?.cells || []).forEach((cell) => {
    if (Number(cell?.row) > 0 && Number(cell?.column) > 0) {
      cells.set(`${Number(cell.row)}:${Number(cell.column)}`, {
        text: String(cell.value || ''), className: 'layout-template', style: cell.style || {}
      });
    }
  });
  const placedRanges = (preview.placed_cells || []).map((item) => spreadsheetRangeParts(item?.target)).filter(Boolean);
  (preview.placed_cells || []).forEach((item) => {
    const target = spreadsheetRangeParts(item?.target)?.start;
    let value = item?.value ?? '';
    if (item?.type === 'formula' && typeof value === 'number') {
      const precision = Math.max(0, Math.min(10, Math.trunc(Number(item.precision ?? 2))));
      value = value.toLocaleString(undefined, { minimumFractionDigits: precision, maximumFractionDigits: precision });
    }
    if (target) put(target.row, target.column, String(value), previewClass(item?.type === 'system' ? 'layout-description' : 'layout-fixed'));
  });
  const periodHeading = ['hour', 'raw'].includes(String(preview.group_by || '')) ||
    String(preview.group_by || '').startsWith('minute:')
    ? 'Time' : (preview.group_by === 'month' ? 'Month' : 'Date');
  if (headerRows) {
    put(tableRow, tableColumn, periodHeading, previewClass('layout-heading'));
    columns.forEach((column, index) => put(tableRow, placements[index], String(column.heading || ''), previewClass('layout-heading')));
  }
  (preview.rows || []).forEach((row, rowIndex) => {
    const outputRow = tableRow + headerRows + rowIndex;
    put(outputRow, tableColumn, String(row.date || ''), previewClass('layout-data'));
    (row.values || []).forEach((value, index) => {
      const precision = columns[index]?.precision ?? 2;
      const text = value === null || value === undefined ? '—' : Number(value).toLocaleString(undefined, {
        minimumFractionDigits: precision,
        maximumFractionDigits: precision
      });
      put(outputRow, placements[index], text, previewClass('layout-data'));
    });
  });
  const summaryStart = String(layout.summary_placement || 'after_data') === 'fixed'
    ? Math.max(1, Math.trunc(Number(layout.summary_start_row || 40)))
    : tableRow + headerRows + (preview.rows || []).length + Math.max(0, Math.trunc(Number(layout.summary_gap_rows || 0)));
  (preview.summary_rows || []).forEach((row, summaryIndex) => {
    const outputRow = summaryStart + summaryIndex;
    put(outputRow, tableColumn, String(row.label || ''), previewClass('layout-summary'));
    (row.values || []).forEach((value, index) => {
      if (value === null || value === undefined) return;
      const precision = row.precisions?.[index] ?? columns[index]?.precision ?? 2;
      put(outputRow, placements[index], Number(value).toLocaleString(undefined, {
        minimumFractionDigits: precision,
        maximumFractionDigits: precision
      }), previewClass('layout-summary'));
    });
  });
  const used = [...cells.keys()].map((key) => key.split(':').map(Number));
  const maxRow = Math.min(500, Math.max(tableRow, Number(templatePreview?.max_row || 0),
    ...used.map(([row]) => row), ...placedRanges.map((range) => range.end.row)));
  const maxColumn = Math.min(100, Math.max(tableColumn, Number(templatePreview?.max_column || 0),
    ...placements, ...used.map(([, column]) => column), ...placedRanges.map((range) => range.end.column)));
  const colgroup = document.createElement('colgroup');
  for (let column = 1; column <= maxColumn; column++) {
    const col = document.createElement('col');
    const width = Number(templatePreview?.column_widths?.[String(column)] || 0);
    if (width > 0) col.style.width = `${Math.max(40, Math.min(420, width * 7))}px`;
    colgroup.appendChild(col);
  }
  els.publishedReportPreviewBody.parentElement?.prepend(colgroup);
  const mergeAnchors = new Map(); const mergedCells = new Set();
  const merges = [...(templatePreview?.merges || []), ...placedRanges.filter((range) => range.range.includes(':')).map((range) => ({
    start_row: range.start.row, start_column: range.start.column, end_row: range.end.row, end_column: range.end.column
  }))];
  merges.forEach((mergeRange) => {
    const startRow = Number(mergeRange.start_row); const startColumn = Number(mergeRange.start_column);
    const endRow = Math.min(maxRow, Number(mergeRange.end_row)); const endColumn = Math.min(maxColumn, Number(mergeRange.end_column));
    if (startRow < 1 || startColumn < 1 || endRow < startRow || endColumn < startColumn) return;
    mergeAnchors.set(`${startRow}:${startColumn}`, { rowspan: endRow - startRow + 1, colspan: endColumn - startColumn + 1 });
    for (let mergeRow = startRow; mergeRow <= endRow; mergeRow++) for (let mergeColumn = startColumn; mergeColumn <= endColumn; mergeColumn++) {
      if (mergeRow !== startRow || mergeColumn !== startColumn) mergedCells.add(`${mergeRow}:${mergeColumn}`);
    }
  });
  for (let row = 1; row <= maxRow; row++) {
    const tr = document.createElement('tr');
    const height = Number(templatePreview?.row_heights?.[String(row)] || 0);
    if (height > 0) tr.style.height = `${Math.max(20, Math.min(240, height * 1.33))}px`;
    for (let column = 1; column <= maxColumn; column++) {
      if (mergedCells.has(`${row}:${column}`)) continue;
      const td = document.createElement('td');
      const merge = mergeAnchors.get(`${row}:${column}`);
      if (merge) { td.rowSpan = merge.rowspan; td.colSpan = merge.colspan; }
      const content = cells.get(`${row}:${column}`);
      if (content) {
        td.textContent = content.text;
        if (content.className) td.classList.add(content.className);
        const style = content.style || {};
        if (style.bold) td.style.fontWeight = '700';
        if (style.italic) td.style.fontStyle = 'italic';
        if (Number(style.size) > 0) td.style.fontSize = `${Math.min(36, Number(style.size))}px`;
        if (/^[A-Fa-f0-9]{8}$/.test(String(style.color || ''))) td.style.color = `#${String(style.color).slice(2)}`;
        if (/^[A-Fa-f0-9]{8}$/.test(String(style.fill || ''))) td.style.backgroundColor = `#${String(style.fill).slice(2)}`;
        if (['left', 'center', 'right'].includes(style.horizontal)) td.style.textAlign = style.horizontal;
        if (['top', 'center', 'bottom'].includes(style.vertical)) td.style.verticalAlign = style.vertical === 'center' ? 'middle' : style.vertical;
        if (style.wrap) td.style.whiteSpace = 'normal';
      }
      tr.appendChild(td);
    }
    els.publishedReportPreviewBody.appendChild(tr);
  }
  els.publishedReportPreviewWrap.style.display = '';
}

async function previewPublishedReport() {
  const report = selectedPublishedReport();
  const range = publishedReportRangePayload();
  if (!report || !range) return;
  if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = 'Loading report…';
  try {
    const preview = await apiPostJson('/api/reports/preview', { id: report.id, ...range }, { timeoutMs: 120000 });
    renderPublishedReportPreview(preview);
    if (els.publishedReportsStatus) {
      els.publishedReportsStatus.textContent = preview.template_preview_error
        ? `Report ready, but the spreadsheet template preview is unavailable: ${preview.template_preview_error}`
        : preview.truncated
        ? `Report preview reached the ${Number(preview.row_limit || 250000).toLocaleString()}-row limit; narrow the date range to inspect all samples.`
        : (report.published === false
            ? 'Draft preview — publish this report to enable downloads.'
            : 'Report ready.');
    }
  } catch (err) {
    if (els.publishedReportPreviewWrap) els.publishedReportPreviewWrap.style.display = 'none';
    if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = String(err.message || err);
  }
}

async function downloadPublishedReport() {
  const report = selectedPublishedReport();
  const range = publishedReportRangePayload();
  const format = String(els.publishedReportFormat?.value || '').trim();
  if (!report || !range || !format) {
    if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = 'Select a report period and download format.';
    return;
  }
  const query = new URLSearchParams({ id: report.id, format, ...range });
  if (els.publishedReportDownloadBtn) els.publishedReportDownloadBtn.disabled = true;
  if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = 'Generating…';
  try {
    const response = await fetch(`/api/reports/download?${query.toString()}`, {
      method: 'GET',
      credentials: 'same-origin',
      cache: 'no-store'
    });
    if (!response.ok) {
      let message = `Download failed (${response.status})`;
      try {
        const body = await response.json();
        message = String(body?.error || message);
      } catch {
        // Keep the HTTP status message.
      }
      throw new Error(message);
    }
    const blob = await response.blob();
    const disposition = String(response.headers.get('content-disposition') || '');
    const match = disposition.match(/filename="([^"]+)"/i);
    const rangeName = range.period_value || `${range.start_date}-to-${range.end_date}`;
    const filename = match?.[1] || `${report.id}-${rangeName}.${format}`;
    const objectUrl = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = objectUrl;
    anchor.download = filename;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(objectUrl);
    if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = `Downloaded ${filename}`;
  } catch (err) {
    if (els.publishedReportsStatus) els.publishedReportsStatus.textContent = String(err.message || err);
  } finally {
    const selected = selectedPublishedReport();
    if (els.publishedReportDownloadBtn) {
      els.publishedReportDownloadBtn.disabled = !selected || selected.published === false;
    }
  }
}

function wirePublishedReportsUi() {
  if (els.publishedReportMonth && !els.publishedReportMonth.value) {
    const now = new Date();
    els.publishedReportMonth.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  }
  if (els.publishedReportSelect) {
    els.publishedReportSelect.addEventListener('change', () => {
      renderPublishedReportSelection();
      previewPublishedReport().catch(() => {});
    });
  }
  if (els.publishedReportMonth) {
    els.publishedReportMonth.addEventListener('change', () => previewPublishedReport().catch(() => {}));
  }
  [els.publishedReportStartDate, els.publishedReportEndDate].forEach((input) => {
    if (input) input.addEventListener('change', () => previewPublishedReport().catch(() => {}));
  });
  if (els.publishedReportPreviousBtn) {
    els.publishedReportPreviousBtn.addEventListener('click', () => shiftPublishedReportPeriod(-1));
  }
  if (els.publishedReportNextBtn) {
    els.publishedReportNextBtn.addEventListener('click', () => shiftPublishedReportPeriod(1));
  }
  if (els.publishedReportCustomPreviousBtn) {
    els.publishedReportCustomPreviousBtn.addEventListener('click', () => shiftPublishedCustomRange(-1));
  }
  if (els.publishedReportCustomNextBtn) {
    els.publishedReportCustomNextBtn.addEventListener('click', () => shiftPublishedCustomRange(1));
  }
  if (els.publishedReportsRefreshBtn) {
    els.publishedReportsRefreshBtn.addEventListener('click', () => refreshPublishedReports());
  }
  if (els.publishedReportDownloadBtn) {
    els.publishedReportDownloadBtn.addEventListener('click', () => downloadPublishedReport());
  }
}

function reportBuilderSetStatus(message) {
  if (els.reportBuilderStatus) els.reportBuilderStatus.textContent = String(message || '');
}

function showReportsLanding() {
  if (els.reportsDownloadCard) els.reportsDownloadCard.style.display = '';
  if (els.reportBuilderCard) els.reportBuilderCard.style.display = 'none';
  document.body.classList.remove('reports-builder-active');
}

function showReportBuilder(report) {
  const permissions = reportPermissions(report);
  if (report && !permissions.edit) return;
  if (!report && !canCreateReports()) return;
  loadReportBuilderDefinition(report || null);
  setReportBuilderTab('report');
  if (els.reportsDownloadCard) els.reportsDownloadCard.style.display = 'none';
  if (els.reportBuilderCard) els.reportBuilderCard.style.display = '';
  document.body.classList.add('reports-builder-active');
  if (els.reportBuilderTitle) {
    els.reportBuilderTitle.textContent = report ? `Edit ${report.name || 'Report'}` : 'New Report';
  }
  if (els.reportBuilderDuplicateBtn) {
    els.reportBuilderDuplicateBtn.style.display = report && permissions.manage ? '' : 'none';
    els.reportBuilderDuplicateBtn.disabled = !report || !permissions.manage;
  }
  if (els.reportBuilderDeleteBtn) {
    els.reportBuilderDeleteBtn.style.display = report && permissions.manage ? '' : 'none';
    els.reportBuilderDeleteBtn.disabled = !report || !permissions.manage;
  }
  if (els.reportBuilderAccessSection) {
    els.reportBuilderAccessSection.style.display = (!report || permissions.manage) ? '' : 'none';
  }
  if (els.reportBuilderPublished) {
    els.reportBuilderPublished.disabled = Boolean(report) && !permissions.manage;
    els.reportBuilderPublished.title = els.reportBuilderPublished.disabled
      ? 'Manage access is required to publish or unpublish this report.'
      : '';
  }
  if (els.reportBuilderHmiEnabled) {
    els.reportBuilderHmiEnabled.disabled = Boolean(report) && !permissions.manage;
    els.reportBuilderHmiEnabled.title = els.reportBuilderHmiEnabled.disabled
      ? 'Manage access is required to allow or prevent HMI display.' : '';
  }
  const canManageTemplate = !report || permissions.manage;
  if (els.reportBuilderTemplateFile) els.reportBuilderTemplateFile.disabled = !canManageTemplate;
  if (els.reportBuilderTemplateUploadBtn) els.reportBuilderTemplateUploadBtn.disabled = !canManageTemplate;
  if (els.reportBuilderTemplateRemoveBtn) els.reportBuilderTemplateRemoveBtn.disabled = !canManageTemplate;
  if (els.reportBuilderPreviewWrap) els.reportBuilderPreviewWrap.style.display = 'none';
  reportBuilderSetStatus('');
}

function browserTimezone() {
  try {
    return String(Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC');
  } catch {
    return 'UTC';
  }
}

function reportBuilderTimezones() {
  try {
    if (typeof Intl.supportedValuesOf === 'function') {
      return Intl.supportedValuesOf('timeZone');
    }
  } catch {
    // Use the compatibility list below.
  }
  return [
    'UTC',
    'America/Anchorage', 'America/Chicago', 'America/Denver',
    'America/Los_Angeles', 'America/New_York', 'America/Phoenix',
    'America/Puerto_Rico', 'Pacific/Honolulu'
  ];
}

function populateReportBuilderTimezones(selectedValue = '') {
  if (!els.reportBuilderTimezone) return;
  const selected = String(selectedValue || browserTimezone() || 'UTC');
  const zones = Array.from(new Set(['UTC', ...reportBuilderTimezones(), selected])).sort();
  els.reportBuilderTimezone.textContent = '';
  zones.forEach((timezone) => {
    const option = document.createElement('option');
    option.value = timezone;
    option.textContent = timezone.replaceAll('_', ' ');
    els.reportBuilderTimezone.appendChild(option);
  });
  els.reportBuilderTimezone.value = selected;
}

function reportBuilderSourceSetStatus(message) {
  if (els.reportBuilderSourceStatus) els.reportBuilderSourceStatus.textContent = String(message || '');
}

function reportBuilderSelectedTable() {
  return state.reportBuilderSchema.find((table) => table.name === els.reportBuilderTable?.value) || null;
}

function fillSelect(select, values, selected = '') {
  if (!select) return;
  select.textContent = '';
  values.forEach((value) => {
    const option = document.createElement('option');
    option.value = String(value.value ?? value);
    option.textContent = String(value.label ?? value.value ?? value);
    select.appendChild(option);
  });
  if (Array.from(select.options).some((option) => option.value === selected)) select.value = selected;
}

function renderReportBuilderDatabaseSources(selected = '') {
  fillSelect(els.reportBuilderDatabase, state.reportBuilderDatabases.map((database) => ({
    value: database.id,
    label: `${database.name || database.id} (${database.type || 'mysql'})`
  })), selected);
}

function renderReportBuilderDataSources(selected = '') {
  if (!els.reportBuilderDataSource) return;
  const currentReport = state.reportBuilderReports.find((report) => report.id === state.reportBuilderOriginalId);
  const legacyManual = Boolean(state.reportBuilderOriginalId) && !String(currentReport?.data_source?.source_id || '');
  const allowManual = hasPerm('reports.administer') || legacyManual;
  const profiles = state.reportBuilderDataSources.map((source) => ({ value: source.id, label: source.name }));
  const options = [
    ...profiles,
    ...(allowManual ? [{ value: '', label: 'Advanced/manual database mapping' }] : [])
  ];
  const desired = selected || (legacyManual ? '' : String(profiles[0]?.value || ''));
  fillSelect(els.reportBuilderDataSource, options, desired);
}

function selectedReportDataSource() {
  const id = String(els.reportBuilderDataSource?.value || '');
  return state.reportBuilderDataSources.find((source) => String(source.id || '') === id) || null;
}

function applyReportDataSource(source) {
  if (!source) return;
  if (els.reportBuilderDatabase) els.reportBuilderDatabase.value = String(source.database_id || '');
  if (els.reportBuilderLayout) els.reportBuilderLayout.value = source.layout || 'wide';
  fillSelect(els.reportBuilderTable, [{ value: source.table, label: source.table }], source.table);
  fillSelect(els.reportBuilderTimeColumn, [{ value: source.time_column, label: source.time_column }], source.time_column);
  fillSelect(els.reportBuilderCategoryColumn, source.category_column
    ? [{ value: source.category_column, label: source.category_column }] : [], source.category_column || '');
  const fields = (source.value_fields || []).map((field) => ({ value: field.column, label: field.label }));
  const defaultField = (source.value_fields || []).find((field) => field.default) || source.value_fields?.[0];
  fillSelect(els.reportBuilderValueColumn, fields, defaultField?.column || '');
  fillSelect(els.reportBuilderDatabaseField, fields, defaultField?.column || '');
  reportBuilderSourceSetStatus(source.description || `Using predefined source ${source.name}`);
  renderReportBuilderSourceUi();
}

function reportDataSourceSetStatus(message) {
  if (els.reportDataSourceStatus) els.reportDataSourceStatus.textContent = String(message || '');
}

function renderReportDataSourceExisting(selected = '') {
  fillSelect(els.reportDataSourceExisting, [
    { value: '', label: 'New data source' },
    ...state.reportBuilderDataSources.map((source) => ({ value: source.id, label: source.name }))
  ], selected);
  if (els.reportDataSourceDeleteBtn) els.reportDataSourceDeleteBtn.disabled = !selected;
}

function renderReportDataSourceValueFields(columns, selectedFields = []) {
  if (!els.reportDataSourceValueFields) return;
  const selected = new Map((selectedFields || []).map((field) => [String(field.column), field]));
  state.reportDataSourceFields = columns.map((column, index) => {
    const saved = selected.get(String(column.name));
    return { column: String(column.name), selected: Boolean(saved), label: String(saved?.label || column.name),
      type: String(saved?.type || (/char|text|enum|json/i.test(String(column.data_type || '')) ? 'text' : 'numeric')),
      default: Boolean(saved?.default || (!selectedFields.length && index === 0)) };
  });
  els.reportDataSourceValueFields.textContent = '';
  state.reportDataSourceFields.forEach((field) => {
    const tr = document.createElement('tr');
    const availableCell = document.createElement('td'); availableCell.style.textAlign = 'center';
    const available = document.createElement('input'); available.type = 'checkbox'; available.checked = field.selected;
    available.addEventListener('change', () => { field.selected = available.checked; }); availableCell.appendChild(available);
    const columnCell = document.createElement('td'); columnCell.textContent = field.column;
    const labelCell = document.createElement('td'); const label = document.createElement('input'); label.value = field.label;
    label.addEventListener('input', () => { field.label = label.value; }); labelCell.appendChild(label);
    const typeCell = document.createElement('td'); const type = document.createElement('select');
    fillSelect(type, [{ value: 'numeric', label: 'Numeric' }, { value: 'text', label: 'Text' }], field.type);
    type.addEventListener('change', () => { field.type = type.value; }); typeCell.appendChild(type);
    const defaultCell = document.createElement('td'); defaultCell.style.textAlign = 'center';
    const defaultInput = document.createElement('input'); defaultInput.type = 'radio'; defaultInput.name = 'reportDataSourceDefaultField';
    defaultInput.checked = field.default; defaultInput.addEventListener('change', () => {
      state.reportDataSourceFields.forEach((candidate) => { candidate.default = candidate === field; });
    }); defaultCell.appendChild(defaultInput);
    tr.append(availableCell, columnCell, labelCell, typeCell, defaultCell);
    els.reportDataSourceValueFields.appendChild(tr);
  });
}

function renderReportDataSourceSchema(selection = {}) {
  const table = state.reportDataSourceSchema.find((item) => item.name === els.reportDataSourceTable?.value) || null;
  const columns = Array.isArray(table?.columns) ? table.columns : [];
  const choices = columns.map((column) => ({ value: column.name, label: `${column.name} (${column.data_type})` }));
  fillSelect(els.reportDataSourceTimeColumn, choices, selection.time_column || '');
  fillSelect(els.reportDataSourceCategoryColumn, choices, selection.category_column || '');
  renderReportDataSourceValueFields(columns, selection.value_fields || []);
}

async function loadReportDataSourceSchema(selection = {}) {
  const databaseId = String(els.reportDataSourceDatabase?.value || '');
  state.reportDataSourceSchema = [];
  if (!databaseId) return;
  reportDataSourceSetStatus('Loading tables and columns…');
  try {
    const database = state.reportBuilderDatabases.find((item) => item.id === databaseId) || {};
    const response = await apiGet(`/api/reports/admin/schema?database=${encodeURIComponent(databaseId)}`,
      { timeoutMs: reporterDatabaseDiscoveryTimeoutMs(database) });
    state.reportDataSourceSchema = Array.isArray(response?.tables) ? response.tables : [];
    fillSelect(els.reportDataSourceTable, state.reportDataSourceSchema.map((table) => ({
      value: table.name, label: `${table.name}${table.type === 'VIEW' ? ' (view)' : ''}`
    })), selection.table || '');
    renderReportDataSourceSchema(selection);
    reportDataSourceSetStatus(`${state.reportDataSourceSchema.length} table(s) available`);
  } catch (err) { reportDataSourceSetStatus(err.message || err); }
}

function loadReportDataSourceEditor(source = null) {
  const value = source || {};
  state.reportDataSourceOriginalId = String(value.id || '');
  if (els.reportDataSourceName) els.reportDataSourceName.value = String(value.name || '');
  if (els.reportDataSourceDescription) els.reportDataSourceDescription.value = String(value.description || '');
  fillSelect(els.reportDataSourceDatabase, state.reportBuilderDatabases.map((database) => ({
    value: database.id, label: `${database.name || database.id} (${database.type || 'mysql'})`
  })), String(value.database_id || ''));
  if (els.reportDataSourceLayout) els.reportDataSourceLayout.value = String(value.layout || 'category');
  if (els.reportDataSourceCategoryLabel) els.reportDataSourceCategoryLabel.style.display = String(value.layout || 'category') === 'category' ? '' : 'none';
  loadReportDataSourceSchema(value).catch(() => {});
}

async function openReportDataSourceModal() {
  if (!hasPerm('reports.administer') || !els.reportDataSourceModal) return;
  els.reportDataSourceModal.style.display = 'flex';
  reportDataSourceSetStatus('Loading database connections…');
  try {
    const [databaseResponse, sourceResponse] = await Promise.all([
      apiGet('/api/reports/admin/sources'),
      apiGet('/api/reports/data-sources')
    ]);
    state.reportBuilderDatabases = Array.isArray(databaseResponse?.databases) ? databaseResponse.databases : [];
    state.reportBuilderDataSources = Array.isArray(sourceResponse?.sources) ? sourceResponse.sources : [];
    renderReportDataSourceExisting('');
    loadReportDataSourceEditor(null);
    reportDataSourceSetStatus(state.reportBuilderDatabases.length
      ? `${state.reportBuilderDatabases.length} database connection(s) available`
      : 'No Logger database connections are configured.');
  } catch (err) {
    renderReportDataSourceExisting('');
    loadReportDataSourceEditor(null);
    reportDataSourceSetStatus(err.message || err);
  }
}

async function saveReportDataSource() {
  const valueFields = state.reportDataSourceFields.filter((field) => field.selected).map((field) => ({
    column: field.column, label: String(field.label || field.column).trim(), type: field.type,
    default: Boolean(field.default)
  }));
  reportDataSourceSetStatus('Saving…');
  try {
    const response = await apiPostJson('/api/reports/data-sources', {
      original_id: state.reportDataSourceOriginalId,
      source: { name: String(els.reportDataSourceName?.value || '').trim(),
        description: String(els.reportDataSourceDescription?.value || '').trim(),
        database_id: String(els.reportDataSourceDatabase?.value || ''), table: String(els.reportDataSourceTable?.value || ''),
        layout: String(els.reportDataSourceLayout?.value || 'category'),
        time_column: String(els.reportDataSourceTimeColumn?.value || ''),
        category_column: String(els.reportDataSourceCategoryColumn?.value || ''), value_fields: valueFields }
    });
    await refreshReportBuilder();
    renderReportDataSourceExisting(response.source.id);
    loadReportDataSourceEditor(response.source);
    renderReportBuilderDataSources(els.reportBuilderDataSource?.value || '');
    reportDataSourceSetStatus(`Saved ${response.source.name}`);
  } catch (err) { reportDataSourceSetStatus(err.message || err); }
}

function renderReportBuilderSchemaSelections(selection = {}) {
  const table = reportBuilderSelectedTable();
  const columns = Array.isArray(table?.columns) ? table.columns : [];
  const choices = columns.map((column) => ({
    value: column.name,
    label: `${column.name} (${column.data_type})`
  }));
  fillSelect(els.reportBuilderTimeColumn, choices, selection.time_column || '');
  fillSelect(els.reportBuilderDatabaseField, choices, selection.field || '');
  fillSelect(els.reportBuilderValueColumn, choices, selection.value_column || '');
  fillSelect(els.reportBuilderCategoryColumn, choices, selection.category_column || '');
}

function syncReportBuilderCategorySelections() {
  Array.from(els.reportBuilderCategoryValues?.options || []).forEach((option) => {
    if (option.selected) state.reportBuilderSelectedCategoryItems.add(option.value);
    else state.reportBuilderSelectedCategoryItems.delete(option.value);
  });
}

function reportBuilderCategoryMatches(value, filter) {
  const text = String(value || '').toLowerCase();
  const alternatives = String(filter || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!alternatives.length) return true;
  return alternatives.some((alternative) => {
    const required = alternative.split('+').map((term) => term.trim()).filter(Boolean);
    return required.length > 0 && required.every((term) => text.includes(term));
  });
}

function updateReportBuilderCategoryCount(visibleCount) {
  if (!els.reportBuilderCategoryFilterCount) return;
  const selected = state.reportBuilderSelectedCategoryItems.size;
  els.reportBuilderCategoryFilterCount.textContent =
    `${visibleCount.toLocaleString()} of ${state.reportBuilderCategoryItems.length.toLocaleString()} item(s)` +
    (selected ? `; ${selected.toLocaleString()} selected` : '');
}

function renderReportBuilderCategoryItems(preserveVisibleSelections = true) {
  if (!els.reportBuilderCategoryValues) return;
  if (preserveVisibleSelections) syncReportBuilderCategorySelections();
  const filter = String(els.reportBuilderCategoryFilter?.value || '');
  const visible = state.reportBuilderCategoryItems.filter((value) =>
    reportBuilderCategoryMatches(value, filter));
  els.reportBuilderCategoryValues.textContent = '';
  visible.forEach((value) => {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    option.selected = state.reportBuilderSelectedCategoryItems.has(value);
    els.reportBuilderCategoryValues.appendChild(option);
  });
  updateReportBuilderCategoryCount(visible.length);
}

function renderReportBuilderSourceUi() {
  const databaseMode = String(els.reportBuilderSourceType?.value || 'historian') === 'database';
  const predefined = databaseMode && Boolean(selectedReportDataSource());
  const legacyManual = Boolean(state.reportBuilderOriginalId) &&
    !String((state.reportBuilderReports.find((report) => report.id === state.reportBuilderOriginalId)?.data_source?.source_id) || '');
  const manualMode = databaseMode && !predefined && (hasPerm('reports.administer') || legacyManual);
  const categoryMode = databaseMode && String(els.reportBuilderLayout?.value || 'wide') === 'category';
  [
    els.reportBuilderDataSourceLabel, els.reportBuilderAggregationLabel
  ].forEach((element) => { if (element) element.style.display = databaseMode ? '' : 'none'; });
  if (els.reportBuilderDatabaseLabel) els.reportBuilderDatabaseLabel.style.display = manualMode ? '' : 'none';
  if (els.reportBuilderDatabaseActions) {
    els.reportBuilderDatabaseActions.style.display = databaseMode && (predefined || manualMode) ? '' : 'none';
  }
  [els.reportBuilderTableLabel, els.reportBuilderLayoutLabel, els.reportBuilderTimeColumnLabel].forEach((element) => {
    if (element) element.style.display = manualMode ? '' : 'none';
  });
  if (els.reportBuilderHistorianActions) els.reportBuilderHistorianActions.style.display = databaseMode ? 'none' : '';
  if (els.reportBuilderValueColumnLabel) els.reportBuilderValueColumnLabel.style.display = categoryMode ? '' : 'none';
  if (els.reportBuilderCategoryColumnLabel) els.reportBuilderCategoryColumnLabel.style.display = categoryMode && manualMode ? '' : 'none';
  if (els.reportBuilderLoadCategoriesBtn) els.reportBuilderLoadCategoriesBtn.style.display = categoryMode ? '' : 'none';
  if (els.reportBuilderDatabaseField) els.reportBuilderDatabaseField.style.display = categoryMode ? 'none' : '';
  if (els.reportBuilderAddDatabaseFieldBtn) els.reportBuilderAddDatabaseFieldBtn.style.display = categoryMode ? 'none' : '';
  if (els.reportBuilderCategoryPicker && !categoryMode) els.reportBuilderCategoryPicker.style.display = 'none';
  if (els.reportBuilderPreviewBtn) {
    els.reportBuilderPreviewBtn.disabled = false;
    els.reportBuilderPreviewBtn.title = '';
  }
  if (els.reportBuilderPublished) {
    const current = state.reportBuilderReports.find((report) => report.id === state.reportBuilderOriginalId) || null;
    const canManage = !state.reportBuilderOriginalId || reportPermissions(current).manage;
    els.reportBuilderPublished.disabled = !canManage;
    els.reportBuilderPublished.title = canManage
      ? ''
      : 'Manage access is required to publish or unpublish this report.';
  }
  if (els.reportBuilderHmiEnabled) {
    const current = state.reportBuilderReports.find((report) => report.id === state.reportBuilderOriginalId) || null;
    const canManage = !state.reportBuilderOriginalId || reportPermissions(current).manage;
    els.reportBuilderHmiEnabled.disabled = !canManage;
    els.reportBuilderHmiEnabled.title = canManage ? '' : 'Manage access is required to allow or prevent HMI display.';
  }
}

async function loadReportBuilderDatabaseSchema(selection = {}) {
  const databaseId = String(els.reportBuilderDatabase?.value || '').trim();
  const requestSeq = ++state.reportBuilderSchemaRequestSeq;
  state.reportBuilderSchema = [];
  fillSelect(els.reportBuilderTable, []);
  renderReportBuilderSchemaSelections();
  if (els.reportBuilderCategoryPicker) els.reportBuilderCategoryPicker.style.display = 'none';
  if (!databaseId) {
    reportBuilderSourceSetStatus('Select a database connection.');
    return;
  }
  reportBuilderSourceSetStatus('Loading tables and columns…');
  try {
    const database = state.reportBuilderDatabases.find(
      (candidate) => String(candidate?.id || '') === databaseId
    ) || {};
    const response = await apiGet(
      `/api/reports/admin/schema?database=${encodeURIComponent(databaseId)}`,
      { timeoutMs: reporterDatabaseDiscoveryTimeoutMs(database) }
    );
    if (requestSeq !== state.reportBuilderSchemaRequestSeq ||
        databaseId !== String(els.reportBuilderDatabase?.value || '').trim()) {
      return;
    }
    state.reportBuilderSchema = Array.isArray(response?.tables) ? response.tables : [];
    fillSelect(els.reportBuilderTable, state.reportBuilderSchema.map((table) => ({
      value: table.name,
      label: `${table.name}${table.type === 'VIEW' ? ' (view)' : ''}`
    })), selection.table || '');
    renderReportBuilderSchemaSelections(selection);
    reportBuilderSourceSetStatus(`${state.reportBuilderSchema.length} table(s) available from ${databaseId}`);
  } catch (err) {
    if (requestSeq !== state.reportBuilderSchemaRequestSeq) return;
    reportBuilderSourceSetStatus(err.message || err);
  }
}

function reportBuilderDataSourceDefinition() {
  if (String(els.reportBuilderSourceType?.value || 'historian') !== 'database') {
    return { type: 'historian' };
  }
  return {
    type: 'database',
    source_id: String(els.reportBuilderDataSource?.value || '').trim(),
    database_id: String(els.reportBuilderDatabase?.value || '').trim(),
    table: String(els.reportBuilderTable?.value || '').trim(),
    layout: String(els.reportBuilderLayout?.value || 'wide'),
    time_column: String(els.reportBuilderTimeColumn?.value || '').trim(),
    category_column: String(els.reportBuilderCategoryColumn?.value || '').trim(),
    value_column: String(els.reportBuilderValueColumn?.value || '').trim()
  };
}

function reportGroups() {
  const groups = Array.isArray(state.opcbridgeAuthStatus?.groups) ? state.opcbridgeAuthStatus.groups : [];
  return groups.filter((group) => String(group?.id || '').trim() && String(group.id) !== 'admin');
}

function renderReportBuilderAccess() {
  if (!els.reportBuilderAccess) return;
  els.reportBuilderAccess.textContent = '';
  const byGroup = new Map(state.reportBuilderAccess.map((grant) => [String(grant.group_id), grant]));
  const current = state.reportBuilderReports.find((report) => report.id === state.reportBuilderOriginalId) || null;
  const canManage = !state.reportBuilderOriginalId || reportPermissions(current).manage;
  reportGroups().forEach((group) => {
    const groupId = String(group.id);
    const grant = byGroup.get(groupId) || {
      group_id: groupId, view: false, download: false, edit: false, manage: false
    };
    if (!byGroup.has(groupId)) state.reportBuilderAccess.push(grant);
    const tr = document.createElement('tr');
    const name = document.createElement('td');
    name.textContent = String(group.label || group.name || groupId);
    tr.appendChild(name);
    ['view', 'download', 'edit', 'manage'].forEach((action) => {
      const td = document.createElement('td');
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = Boolean(grant[action]);
      checkbox.disabled = !canManage;
      checkbox.addEventListener('change', () => {
        grant[action] = checkbox.checked;
        if (checkbox.checked && ['download', 'edit', 'manage'].includes(action)) grant.view = true;
        if (checkbox.checked && action === 'manage') {
          grant.download = true;
          grant.edit = true;
        }
        renderReportBuilderAccess();
      });
      td.appendChild(checkbox);
      tr.appendChild(td);
    });
    els.reportBuilderAccess.appendChild(tr);
  });
}

function reportBuilderCurrentDefinition() {
  const formats = [];
  if (els.reportBuilderXlsx?.checked) formats.push('xlsx');
  if (els.reportBuilderOds?.checked) formats.push('ods');
  if (els.reportBuilderCsv?.checked) formats.push('csv');
  return {
    id: String(els.reportBuilderId?.value || '').trim(),
    name: String(els.reportBuilderName?.value || '').trim(),
    description: String(els.reportBuilderDescription?.value || '').trim(),
    timezone: String(els.reportBuilderTimezone?.value || 'UTC').trim(),
    period: String(els.reportBuilderPeriod?.value || 'month'),
    hmi_enabled: Boolean(els.reportBuilderHmiEnabled?.checked),
    week_start: String(els.reportBuilderWeekStart?.value || 'sunday'),
    interval_minutes: Math.trunc(Number(els.reportBuilderInterval?.value || 60) || 60),
    group_by: String(els.reportBuilderGroupBy?.value || 'day'),
    data_source: reportBuilderDataSourceDefinition(),
    access: state.reportBuilderAccess
      .filter((grant) => grant.view || grant.download || grant.edit || grant.manage)
      .map((grant) => ({ ...grant })),
    published: Boolean(els.reportBuilderPublished?.checked),
    formats,
    columns: state.reportBuilderColumns.map((column) => ({ ...column })),
    layout: {
      worksheet: String(els.reportBuilderLayoutWorksheet?.value || 'Report').trim() || 'Report',
      table_start_row: Math.max(1, Math.min(10000, Math.trunc(Number(els.reportBuilderLayoutTableRow?.value || 5)))),
      table_start_column: normalizeSpreadsheetColumn(els.reportBuilderLayoutTableColumn?.value || 'A') || 'A',
      include_header_row: Boolean(els.reportBuilderLayoutIncludeHeader?.checked),
      summary_gap_rows: Math.max(0, Math.min(100, Math.trunc(Number(els.reportBuilderLayoutSummaryGap?.value || 0)))),
      summary_placement: String(els.reportBuilderLayoutSummaryPlacement?.value || 'after_data'),
      summary_start_row: Math.max(1, Math.min(10000, Math.trunc(Number(els.reportBuilderLayoutSummaryRow?.value || 40)))),
      placed_cells: state.reportBuilderLayoutPlacedCells.map((item) => ({
        target: normalizeSpreadsheetRange(item.target),
        type: ['system', 'text', 'formula'].includes(item.type) ? item.type : 'text',
        value: String(item.value || ''),
        text: String(item.text || '').slice(0, 2000),
        expression: String(item.expression || '').slice(0, 4000),
        precision: item.precision === null || item.precision === undefined || item.precision === ''
          ? null : Math.max(0, Math.min(10, Math.trunc(Number(item.precision)))),
        date_format: String(item.date_format || '').slice(0, 100)
      }))
    },
    template: state.reportBuilderTemplate ? {
      ...state.reportBuilderTemplate,
      enabled: Boolean(els.reportBuilderTemplateEnabled?.checked)
    } : null,
    summaries: state.reportBuilderSummaries.map((summary) => ({
      label: String(summary.label || '').trim(),
      calculations: state.reportBuilderColumns.map((_, index) =>
        String(summary.calculations?.[index] || 'none')),
      formulas: state.reportBuilderColumns.map((_, index) =>
        String(summary.formulas?.[index] || '').trim()),
      precisions: state.reportBuilderColumns.map((_, index) => {
        const value = summary.precisions?.[index];
        return value === null || value === undefined || value === '' ? null : Math.max(0, Math.min(10, Math.trunc(Number(value))));
      })
    }))
  };
}

function newReportColumnId(label = 'column') {
  const used = new Set(state.reportBuilderColumns.map((column) => String(column.id || '')));
  return opaqueObjectId('column', used);
}

function normalizeSpreadsheetColumn(value) {
  const column = String(value || '').trim().toUpperCase();
  if (!/^[A-Z]{1,3}$/.test(column)) return '';
  const index = [...column].reduce((total, character) => total * 26 + character.charCodeAt(0) - 64, 0);
  return index <= 16384 ? column : '';
}

function spreadsheetColumnIndex(value) {
  const column = normalizeSpreadsheetColumn(value);
  if (!column) return 0;
  return [...column].reduce((total, character) => total * 26 + character.charCodeAt(0) - 64, 0);
}

function spreadsheetColumnLabel(index) {
  let value = Math.max(1, Math.trunc(Number(index) || 1));
  let label = '';
  while (value > 0) {
    value -= 1;
    label = String.fromCharCode(65 + (value % 26)) + label;
    value = Math.floor(value / 26);
  }
  return label;
}

function normalizeSpreadsheetCell(value) {
  const match = String(value || '').trim().toUpperCase().match(/^([A-Z]{1,3})([1-9][0-9]{0,6})$/);
  return match && normalizeSpreadsheetColumn(match[1]) && Number(match[2]) <= 1048576 ? `${match[1]}${match[2]}` : '';
}

function normalizeSpreadsheetRange(value) {
  const raw = String(value || '').trim().toUpperCase();
  const [startRaw, endRaw = startRaw] = raw.split(':');
  if (raw.split(':').length > 2) return '';
  const start = normalizeSpreadsheetCell(startRaw);
  const end = normalizeSpreadsheetCell(endRaw);
  if (!start || !end) return '';
  const a = spreadsheetCellParts(start);
  const b = spreadsheetCellParts(end);
  if (!a || !b || a.row > b.row || a.column > b.column || a.column > 16384 || b.column > 16384) return '';
  return start === end ? start : `${start}:${end}`;
}

function spreadsheetRangeParts(value) {
  const range = normalizeSpreadsheetRange(value);
  if (!range) return null;
  const [startRaw, endRaw = startRaw] = range.split(':');
  return { range, start: spreadsheetCellParts(startRaw), end: spreadsheetCellParts(endRaw) };
}

function migrateLayoutPlacedCells(layout = {}, useDefaults = false) {
  if (Array.isArray(layout.placed_cells)) return layout.placed_cells.map((item) => ({ ...item }));
  const cells = [];
  const addSystem = (target, value, dateFormat = '') => {
    if (normalizeSpreadsheetRange(target)) cells.push({ target, type: 'system', value, date_format: dateFormat });
  };
  if (Object.prototype.hasOwnProperty.call(layout, 'title_cell') || !Object.keys(layout).length || useDefaults) {
    addSystem(layout.title_cell ?? 'A1', 'report_name');
    addSystem(layout.description_cell ?? 'A2', 'report_description');
  }
  const mode = String(layout.date_display || 'combined');
  if (!Object.keys(layout).length || useDefaults || mode === 'combined') addSystem(layout.period_cell || 'A3', 'period_label');
  else if (mode === 'separate') {
    addSystem(layout.start_date_cell || 'A3', 'start_date', 'mm/dd/yyyy');
    addSystem(layout.end_date_cell || 'B3', 'end_date', 'mm/dd/yyyy');
  }
  (Array.isArray(layout.fields) ? layout.fields : []).forEach((field) => {
    if (normalizeSpreadsheetRange(field?.cell) && String(field?.text || '').trim()) {
      cells.push({ target: field.cell, type: 'text', text: String(field.text), date_format: '' });
    }
  });
  return cells;
}

function spreadsheetCellParts(value) {
  const cell = normalizeSpreadsheetCell(value);
  const match = cell.match(/^([A-Z]+)(\d+)$/);
  return match ? { column: spreadsheetColumnIndex(match[1]), row: Number(match[2]) } : null;
}

function setReportBuilderTab(name) {
  state.reportBuilderActiveTab = name;
  document.querySelectorAll('[data-report-builder-panel]').forEach((panel) => {
    panel.hidden = panel.dataset.reportBuilderPanel !== name;
  });
  els.reportBuilderTabs?.querySelectorAll('[data-report-builder-tab]').forEach((button) => {
    const active = button.dataset.reportBuilderTab === name;
    button.classList.toggle('active', active);
    button.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  if (name === 'layout') renderReportBuilderLayout();
}

function reportBuilderLayoutColumnIndex(column, visibleIndex) {
  const explicit = spreadsheetColumnIndex(column.sheet_column);
  if (explicit) return explicit;
  return spreadsheetColumnIndex(els.reportBuilderLayoutTableColumn?.value || 'A') + visibleIndex + 1;
}

function renderReportBuilderTemplateControls() {
  const template = state.reportBuilderTemplate;
  const hasTemplate = Boolean(template?.stored_id);
  if (els.reportBuilderTemplateEnabled) {
    els.reportBuilderTemplateEnabled.disabled = !hasTemplate;
    els.reportBuilderTemplateEnabled.checked = hasTemplate && template.enabled === true;
  }
  if (els.reportBuilderTemplateInfo) {
    els.reportBuilderTemplateInfo.textContent = hasTemplate
      ? `${String(template.filename || 'template.xlsx')} · ${Number(template.size || 0).toLocaleString()} bytes${template.uploaded_at ? ` · uploaded ${new Date(template.uploaded_at).toLocaleString()}` : ''}`
      : 'No template uploaded.';
  }
  if (els.reportBuilderTemplateDownloadBtn) els.reportBuilderTemplateDownloadBtn.style.display = hasTemplate ? '' : 'none';
  if (els.reportBuilderTemplateRemoveBtn) els.reportBuilderTemplateRemoveBtn.style.display = hasTemplate ? '' : 'none';
  if (els.reportBuilderTemplateUploadBtn) els.reportBuilderTemplateUploadBtn.textContent = hasTemplate ? 'Replace Template' : 'Upload Template';
}

async function refreshReportBuilderTemplatePreview() {
  const template = state.reportBuilderTemplate;
  if (!template?.stored_id) {
    state.reportBuilderTemplatePreview = null;
    renderReportBuilderLayoutPreview();
    return;
  }
  const reportId = state.reportBuilderOriginalId || String(els.reportBuilderId?.value || '').trim();
  const worksheet = String(els.reportBuilderLayoutWorksheet?.value || 'Report').trim();
  const query = new URLSearchParams({ id: reportId, stored_id: template.stored_id, worksheet, format: template.format || 'xlsx' });
  try {
    const response = await apiGet(`/api/reports/admin/template/preview?${query.toString()}`);
    state.reportBuilderTemplatePreview = response?.preview || null;
    if (state.reportBuilderTemplatePreview?.worksheet &&
        state.reportBuilderTemplatePreview.worksheet !== worksheet && els.reportBuilderLayoutWorksheet) {
      els.reportBuilderLayoutWorksheet.value = state.reportBuilderTemplatePreview.worksheet;
    }
    if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = '';
  } catch (err) {
    state.reportBuilderTemplatePreview = null;
    if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = `Template preview unavailable: ${err.message || err}`;
  }
  renderReportBuilderLayoutPreview();
}

function renderReportBuilderLayout() {
  if (!els.reportBuilderLayoutColumns || !els.reportBuilderLayoutPlacedCells || !els.reportBuilderLayoutPreview) return;
  const fixedSummary = String(els.reportBuilderLayoutSummaryPlacement?.value || 'after_data') === 'fixed';
  if (els.reportBuilderLayoutSummaryGapLabel) els.reportBuilderLayoutSummaryGapLabel.style.display = fixedSummary ? 'none' : '';
  if (els.reportBuilderLayoutSummaryRowLabel) els.reportBuilderLayoutSummaryRowLabel.style.display = fixedSummary ? '' : 'none';
  renderReportBuilderTemplateControls();
  els.reportBuilderLayoutColumns.textContent = '';
  state.reportBuilderColumns.filter((column) => column.visible !== false).forEach((column, visibleIndex) => {
    const tr = document.createElement('tr');
    const heading = document.createElement('td');
    heading.textContent = String(column.heading || column.id || `Column ${visibleIndex + 1}`);
    const placement = document.createElement('td');
    const input = document.createElement('input');
    input.type = 'text';
    input.maxLength = 3;
    input.placeholder = spreadsheetColumnLabel(spreadsheetColumnIndex(els.reportBuilderLayoutTableColumn?.value || 'A') + visibleIndex + 1);
    input.value = normalizeSpreadsheetColumn(column.sheet_column);
    input.style.width = '90px';
    input.addEventListener('input', () => {
      column.sheet_column = normalizeSpreadsheetColumn(input.value);
      renderReportBuilderLayoutPreview();
    });
    placement.appendChild(input);
    tr.append(heading, placement);
    els.reportBuilderLayoutColumns.appendChild(tr);
  });
  els.reportBuilderLayoutPlacedCells.textContent = '';
  els.reportBuilderLayoutPlacedCellsWrap.style.display = state.reportBuilderLayoutPlacedCells.length ? '' : 'none';
  const systemOptions = [
    ['report_name', 'Report name'], ['report_description', 'Report description'],
    ['period_label', 'Reporting period'], ['start_date', 'Beginning date'],
    ['end_date', 'Ending date'], ['generated_at', 'Generated date/time'], ['timezone', 'Report timezone']
  ];
  state.reportBuilderLayoutPlacedCells.forEach((item, index) => {
    const tr = document.createElement('tr');
    const cellTd = document.createElement('td');
    const cell = document.createElement('input');
    cell.type = 'text';
    cell.value = String(item.target || '');
    cell.placeholder = 'A1 or A1:F1';
    cell.style.width = '130px';
    cell.addEventListener('input', () => { item.target = cell.value; renderReportBuilderLayoutPreview(); });
    cellTd.appendChild(cell);
    const typeTd = document.createElement('td');
    const type = document.createElement('select');
    [['system', 'Standard report value'], ['text', 'Custom text'], ['formula', 'Formula']].forEach(([key, label]) => {
      const option = document.createElement('option'); option.value = key; option.textContent = label; type.appendChild(option);
    });
    type.value = String(item.type || 'text');
    typeTd.appendChild(type);
    const valueTd = document.createElement('td');
    const renderValue = () => {
      valueTd.textContent = '';
      let control;
      if (item.type === 'system') {
        control = document.createElement('select');
        systemOptions.forEach(([key, label]) => { const option = document.createElement('option'); option.value = key; option.textContent = label; control.appendChild(option); });
        control.value = item.value || 'report_name';
        control.addEventListener('change', () => { item.value = control.value; renderReportBuilderLayout(); });
      } else {
        control = document.createElement('input'); control.type = 'text';
        const property = item.type === 'formula' ? 'expression' : 'text';
        control.value = String(item[property] || '');
        control.placeholder = item.type === 'formula' ? 'sum([column_id])' : 'Text to display';
        control.addEventListener('input', () => { item[property] = control.value; renderReportBuilderLayoutPreview(); });
        if (item.type === 'formula') {
          const controls = document.createElement('div');
          controls.className = 'row-actions';
          controls.style.flexWrap = 'nowrap';
          control.style.minWidth = '180px';
          const edit = document.createElement('button');
          edit.className = 'btn'; edit.type = 'button'; edit.textContent = 'Edit Formula';
          edit.addEventListener('click', () => openReportPlacedCellFormulaModal(index));
          controls.append(control, edit);
          valueTd.appendChild(controls);
          return;
        }
      }
      valueTd.appendChild(control);
    };
    type.addEventListener('change', () => {
      item.type = type.value;
      renderReportBuilderLayout();
      if (item.type === 'formula') openReportPlacedCellFormulaModal(index);
    });
    renderValue();
    const formatTd = document.createElement('td');
    const format = document.createElement('input'); format.type = 'text'; format.placeholder = 'mm/dd/yyyy';
    format.value = String(item.date_format || '');
    const dateValue = item.type === 'system' && ['start_date', 'end_date', 'generated_at'].includes(item.value);
    format.disabled = !dateValue;
    format.addEventListener('input', () => { item.date_format = format.value; });
    formatTd.appendChild(format);
    const actionTd = document.createElement('td');
    const remove = document.createElement('button');
    remove.className = 'btn danger';
    remove.type = 'button';
    remove.textContent = 'Remove';
    remove.addEventListener('click', () => { state.reportBuilderLayoutPlacedCells.splice(index, 1); renderReportBuilderLayout(); });
    actionTd.appendChild(remove);
    tr.append(cellTd, typeTd, valueTd, formatTd, actionTd);
    els.reportBuilderLayoutPlacedCells.appendChild(tr);
  });
  renderReportBuilderLayoutPreview();
}

function renderReportBuilderLayoutPreview() {
  const table = els.reportBuilderLayoutPreview;
  if (!table) return;
  const tableRow = Math.max(1, Math.min(200, Math.trunc(Number(els.reportBuilderLayoutTableRow?.value || 5))));
  const tableColumn = spreadsheetColumnIndex(els.reportBuilderLayoutTableColumn?.value || 'A') || 1;
  const visibleColumns = state.reportBuilderColumns.filter((column) => column.visible !== false);
  const placements = visibleColumns.map((column, index) => reportBuilderLayoutColumnIndex(column, index));
  const sampleRows = 3;
  const headerRows = els.reportBuilderLayoutIncludeHeader?.checked === false ? 0 : 1;
  const summaryGap = Math.max(0, Math.min(20, Math.trunc(Number(els.reportBuilderLayoutSummaryGap?.value || 0))));
  const summaryStart = String(els.reportBuilderLayoutSummaryPlacement?.value || 'after_data') === 'fixed'
    ? Math.max(1, Math.min(200, Math.trunc(Number(els.reportBuilderLayoutSummaryRow?.value || 40))))
    : tableRow + headerRows + sampleRows + summaryGap;
  const cells = new Map();
  const put = (row, column, text, className = '') => {
    if (row > 0 && column > 0) cells.set(`${row}:${column}`, {
      ...(cells.get(`${row}:${column}`) || {}), text, className
    });
  };
  const templatePreview = state.reportBuilderTemplate?.enabled === true ? state.reportBuilderTemplatePreview : null;
  (templatePreview?.cells || []).forEach((cell) => {
    if (Number(cell?.row) > 0 && Number(cell?.column) > 0) {
      cells.set(`${Number(cell.row)}:${Number(cell.column)}`, {
        text: String(cell.value || ''), className: 'layout-template', style: cell.style || {}
      });
    }
  });
  const systemSamples = {
    report_name: String(els.reportBuilderName?.value || 'Report Title'),
    report_description: String(els.reportBuilderDescription?.value || 'Report description'),
    period_label: 'Selected reporting period', start_date: 'Beginning date', end_date: 'Ending date',
    generated_at: 'Generated date/time', timezone: String(els.reportBuilderTimezone?.value || browserTimezone())
  };
  state.reportBuilderLayoutPlacedCells.forEach((item) => {
    const target = spreadsheetRangeParts(item.target)?.start;
    if (!target) return;
    const text = item.type === 'system' ? systemSamples[item.value]
      : (item.type === 'formula' ? Number(123.456).toFixed(Math.max(0, Math.min(10, Math.trunc(Number(item.precision ?? 2)))) ) : item.text);
    put(target.row, target.column, String(text || ''), item.value === 'report_name' ? 'layout-title' : 'layout-fixed');
  });
  if (headerRows) {
    put(tableRow, tableColumn, 'Date', 'layout-heading');
    visibleColumns.forEach((column, index) => put(tableRow, placements[index], String(column.heading || column.id || ''), 'layout-heading'));
  }
  for (let rowOffset = 1; rowOffset <= sampleRows; rowOffset++) {
    const outputRow = tableRow + headerRows + rowOffset - 1;
    put(outputRow, tableColumn, `Day ${rowOffset}`, 'layout-data');
    visibleColumns.forEach((column, index) => {
      const precision = Math.max(0, Math.min(10, Math.trunc(Number(column.precision ?? 2))));
      put(outputRow, placements[index], (100 * rowOffset + index + 0.25).toFixed(precision), 'layout-data');
    });
  }
  state.reportBuilderSummaries.forEach((summary, summaryIndex) => {
    const row = summaryStart + summaryIndex;
    put(row, tableColumn, String(summary.label || 'Summary'), 'layout-summary');
    visibleColumns.forEach((column, visibleIndex) => {
      const columnIndex = state.reportBuilderColumns.indexOf(column);
      if (String(summary.calculations?.[columnIndex] || 'none') === 'none') return;
      const precision = summary.precisions?.[columnIndex] ?? column.precision ?? 2;
      put(row, placements[visibleIndex], (300 + visibleIndex + 0.5).toFixed(precision), 'layout-summary');
    });
  });
  const used = [...cells.keys()].map((key) => key.split(':').map(Number));
  const placedRanges = state.reportBuilderLayoutPlacedCells.map((item) => spreadsheetRangeParts(item.target)).filter(Boolean);
  const maxRow = Math.min(500, Math.max(tableRow + sampleRows, summaryStart + state.reportBuilderSummaries.length - 1,
    Number(templatePreview?.max_row || 0), ...used.map(([row]) => row), ...placedRanges.map((range) => range.end.row)));
  const maxColumn = Math.min(100, Math.max(tableColumn, ...placements, Number(templatePreview?.max_column || 0),
    ...used.map(([, column]) => column), ...placedRanges.map((range) => range.end.column)));
  table.textContent = '';
  const colgroup = document.createElement('colgroup');
  const rowHeaderColumn = document.createElement('col');
  rowHeaderColumn.style.width = '46px';
  colgroup.appendChild(rowHeaderColumn);
  for (let column = 1; column <= maxColumn; column++) {
    const col = document.createElement('col');
    const templateWidth = Number(templatePreview?.column_widths?.[String(column)] || 0);
    if (templateWidth > 0) col.style.width = `${Math.max(40, Math.min(420, templateWidth * 7))}px`;
    colgroup.appendChild(col);
  }
  table.appendChild(colgroup);
  const header = document.createElement('tr');
  header.appendChild(document.createElement('th'));
  for (let column = 1; column <= maxColumn; column++) {
    const th = document.createElement('th');
    th.textContent = spreadsheetColumnLabel(column);
    header.appendChild(th);
  }
  table.appendChild(header);
  const mergeAnchors = new Map();
  const mergedCells = new Set();
  const previewMerges = [...(templatePreview?.merges || []), ...placedRanges.filter((range) => range.range.includes(':')).map((range) => ({
    start_row: range.start.row, start_column: range.start.column, end_row: range.end.row, end_column: range.end.column
  }))];
  previewMerges.forEach((merge) => {
    const startRow = Number(merge.start_row);
    const startColumn = Number(merge.start_column);
    const endRow = Math.min(maxRow, Number(merge.end_row));
    const endColumn = Math.min(maxColumn, Number(merge.end_column));
    if (startRow < 1 || startColumn < 1 || endRow < startRow || endColumn < startColumn) return;
    mergeAnchors.set(`${startRow}:${startColumn}`, {
      rowspan: endRow - startRow + 1, colspan: endColumn - startColumn + 1
    });
    for (let mergeRow = startRow; mergeRow <= endRow; mergeRow++) {
      for (let mergeColumn = startColumn; mergeColumn <= endColumn; mergeColumn++) {
        if (mergeRow !== startRow || mergeColumn !== startColumn) mergedCells.add(`${mergeRow}:${mergeColumn}`);
      }
    }
  });
  for (let row = 1; row <= maxRow; row++) {
    const tr = document.createElement('tr');
    const templateHeight = Number(templatePreview?.row_heights?.[String(row)] || 0);
    if (templateHeight > 0) tr.style.height = `${Math.max(20, Math.min(240, templateHeight * 1.33))}px`;
    const rowHeading = document.createElement('th');
    rowHeading.textContent = String(row);
    tr.appendChild(rowHeading);
    for (let column = 1; column <= maxColumn; column++) {
      if (mergedCells.has(`${row}:${column}`)) continue;
      const td = document.createElement('td');
      const merge = mergeAnchors.get(`${row}:${column}`);
      if (merge) {
        td.rowSpan = merge.rowspan;
        td.colSpan = merge.colspan;
      }
      const content = cells.get(`${row}:${column}`);
      if (content) {
        td.textContent = content.text;
        if (content.className) td.classList.add(content.className);
        const style = content.style || {};
        if (style.bold) td.style.fontWeight = '700';
        if (style.italic) td.style.fontStyle = 'italic';
        if (Number(style.size) > 0) td.style.fontSize = `${Math.min(36, Number(style.size))}px`;
        if (/^[A-Fa-f0-9]{8}$/.test(String(style.color || ''))) td.style.color = `#${String(style.color).slice(2)}`;
        if (/^[A-Fa-f0-9]{8}$/.test(String(style.fill || ''))) td.style.backgroundColor = `#${String(style.fill).slice(2)}`;
        if (['left', 'center', 'right'].includes(style.horizontal)) td.style.textAlign = style.horizontal;
        if (['top', 'center', 'bottom'].includes(style.vertical)) td.style.verticalAlign = style.vertical === 'center' ? 'middle' : style.vertical;
        if (style.wrap) td.style.whiteSpace = 'normal';
      }
      tr.appendChild(td);
    }
    table.appendChild(tr);
  }
}

function closeReportFormulaModal() {
  if (els.reportFormulaModal) els.reportFormulaModal.style.display = 'none';
  state.reportFormulaColumnIndex = -1;
  state.reportFormulaSummaryIndex = -1;
  state.reportFormulaSummaryColumnIndex = -1;
  state.reportFormulaPlacedCellIndex = -1;
}

function openReportFormulaModal(index) {
  const column = state.reportBuilderColumns[index];
  if (!column || column.source !== 'calculated') return;
  state.reportFormulaColumnIndex = index;
  state.reportFormulaSummaryIndex = -1;
  state.reportFormulaSummaryColumnIndex = -1;
  state.reportFormulaPlacedCellIndex = -1;
  if (els.reportFormulaModalTitle) els.reportFormulaModalTitle.textContent = 'Calculated Column Formula';
  if (els.reportFormulaHelp) {
    els.reportFormulaHelp.textContent = 'Supported: numbers, quoted text, +, −, ×, ÷, comparisons, and/or/not, if(), coalesce(), min(), max(), avg(), abs(), round(), and null.';
  }
  if (els.reportFormulaPrecisionWrap) els.reportFormulaPrecisionWrap.style.display = 'none';
  if (els.reportFormulaExpression) {
    els.reportFormulaExpression.value = String(column.expression || '');
    els.reportFormulaExpression.placeholder = 'Example: if([effluent_ph] <= 6.0, "No Limit", [numeric_limit])';
  }
  if (els.reportFormulaStatus) els.reportFormulaStatus.textContent = '';
  if (els.reportFormulaColumns) {
    els.reportFormulaColumns.textContent = '';
    state.reportBuilderColumns.forEach((candidate, candidateIndex) => {
      if (candidateIndex === index) return;
      const button = document.createElement('button');
      button.className = 'btn';
      button.type = 'button';
      button.textContent = String(candidate.heading || candidate.id || `Column ${candidateIndex + 1}`);
      button.title = `[${String(candidate.id || '')}]`;
      button.addEventListener('click', () => {
        const textarea = els.reportFormulaExpression;
        if (!textarea) return;
        const reference = `[${String(candidate.id || '')}]`;
        const start = textarea.selectionStart ?? textarea.value.length;
        const end = textarea.selectionEnd ?? start;
        textarea.setRangeText(reference, start, end, 'end');
        textarea.focus();
      });
      els.reportFormulaColumns.appendChild(button);
    });
  }
  if (els.reportFormulaModal) els.reportFormulaModal.style.display = 'flex';
  els.reportFormulaExpression?.focus();
}

function openReportSummaryFormulaModal(summaryIndex, columnIndex) {
  const summary = state.reportBuilderSummaries[summaryIndex];
  const column = state.reportBuilderColumns[columnIndex];
  if (!summary || !column) return;
  if (!Array.isArray(summary.formulas)) summary.formulas = [];
  if (!Array.isArray(summary.precisions)) summary.precisions = [];
  state.reportFormulaColumnIndex = -1;
  state.reportFormulaSummaryIndex = summaryIndex;
  state.reportFormulaSummaryColumnIndex = columnIndex;
  state.reportFormulaPlacedCellIndex = -1;
  if (els.reportFormulaModalTitle) els.reportFormulaModalTitle.textContent = `Summary Formula — ${String(column.heading || column.id || 'Column')}`;
  if (els.reportFormulaHelp) {
    els.reportFormulaHelp.textContent = 'Aggregate a column with sum(), avg(), min(), max(), first(), last(), count(), or missing(). You can combine results with arithmetic and other formula functions.';
  }
  if (els.reportFormulaPrecisionWrap) els.reportFormulaPrecisionWrap.style.display = '';
  if (els.reportFormulaPrecision) {
    const savedPrecision = summary.precisions[columnIndex];
    els.reportFormulaPrecision.value = String(savedPrecision ?? column.precision ?? 2);
  }
  if (els.reportFormulaExpression) {
    els.reportFormulaExpression.value = String(summary.formulas[columnIndex] || '');
    els.reportFormulaExpression.placeholder = 'Example: sum([flow]) / sum([runtime])';
  }
  if (els.reportFormulaStatus) els.reportFormulaStatus.textContent = '';
  if (els.reportFormulaColumns) {
    els.reportFormulaColumns.textContent = '';
    state.reportBuilderColumns.forEach((candidate, candidateIndex) => {
      const button = document.createElement('button');
      button.className = 'btn';
      button.type = 'button';
      button.textContent = String(candidate.heading || candidate.id || `Column ${candidateIndex + 1}`);
      button.title = `sum([${String(candidate.id || '')}])`;
      button.addEventListener('click', () => {
        const textarea = els.reportFormulaExpression;
        if (!textarea) return;
        const reference = `sum([${String(candidate.id || '')}])`;
        const start = textarea.selectionStart ?? textarea.value.length;
        const end = textarea.selectionEnd ?? start;
        textarea.setRangeText(reference, start, end, 'end');
        textarea.focus();
      });
      els.reportFormulaColumns.appendChild(button);
    });
  }
  if (els.reportFormulaModal) els.reportFormulaModal.style.display = 'flex';
  els.reportFormulaExpression?.focus();
}

function openReportPlacedCellFormulaModal(index) {
  const item = state.reportBuilderLayoutPlacedCells[index];
  if (!item || item.type !== 'formula') return;
  state.reportFormulaColumnIndex = -1;
  state.reportFormulaSummaryIndex = -1;
  state.reportFormulaSummaryColumnIndex = -1;
  state.reportFormulaPlacedCellIndex = index;
  if (els.reportFormulaModalTitle) els.reportFormulaModalTitle.textContent = `Placed Cell Formula — ${String(item.target || 'Unplaced cell')}`;
  if (els.reportFormulaHelp) {
    els.reportFormulaHelp.textContent = 'Aggregate a report column with sum(), avg(), min(), max(), first(), last(), count(), or missing(). You can combine aggregate results with arithmetic and other formula functions.';
  }
  if (els.reportFormulaPrecisionWrap) els.reportFormulaPrecisionWrap.style.display = '';
  if (els.reportFormulaPrecision) els.reportFormulaPrecision.value = String(item.precision ?? 2);
  if (els.reportFormulaExpression) {
    els.reportFormulaExpression.value = String(item.expression || '');
    els.reportFormulaExpression.placeholder = 'Example: sum([flow]) / sum([runtime])';
  }
  if (els.reportFormulaStatus) els.reportFormulaStatus.textContent = '';
  if (els.reportFormulaColumns) {
    els.reportFormulaColumns.textContent = '';
    state.reportBuilderColumns.forEach((column, columnIndex) => {
      const button = document.createElement('button');
      button.className = 'btn';
      button.type = 'button';
      button.textContent = String(column.heading || column.id || `Column ${columnIndex + 1}`);
      button.title = `sum([${String(column.id || '')}])`;
      button.addEventListener('click', () => {
        const textarea = els.reportFormulaExpression;
        if (!textarea) return;
        const reference = `sum([${String(column.id || '')}])`;
        const start = textarea.selectionStart ?? textarea.value.length;
        const end = textarea.selectionEnd ?? start;
        textarea.setRangeText(reference, start, end, 'end');
        textarea.focus();
      });
      els.reportFormulaColumns.appendChild(button);
    });
  }
  if (els.reportFormulaModal) els.reportFormulaModal.style.display = 'flex';
  els.reportFormulaExpression?.focus();
}

function reorderReportBuilderSummaryColumns(fromIndex, toIndex) {
  state.reportBuilderSummaries.forEach((summary) => {
    const calculations = Array.isArray(summary.calculations) ? summary.calculations : [];
    const [moved] = calculations.splice(fromIndex, 1);
    calculations.splice(toIndex, 0, moved || 'none');
    summary.calculations = calculations;
    const formulas = Array.isArray(summary.formulas) ? summary.formulas : [];
    const [movedFormula] = formulas.splice(fromIndex, 1);
    formulas.splice(toIndex, 0, movedFormula || '');
    summary.formulas = formulas;
    const precisions = Array.isArray(summary.precisions) ? summary.precisions : [];
    const [movedPrecision] = precisions.splice(fromIndex, 1);
    precisions.splice(toIndex, 0, movedPrecision ?? null);
    summary.precisions = precisions;
  });
}

function renderReportBuilderSummaries() {
  if (!els.reportBuilderSummaries || !els.reportBuilderSummariesHead || !els.reportBuilderSummariesWrap) return;
  els.reportBuilderSummariesHead.textContent = '';
  els.reportBuilderSummaries.textContent = '';
  els.reportBuilderSummariesWrap.style.display = state.reportBuilderSummaries.length ? '' : 'none';
  if (!state.reportBuilderSummaries.length) return;
  const visibleColumns = state.reportBuilderColumns
    .map((column, index) => ({ column, index }))
    .filter(({ column }) => column.visible !== false);
  const header = document.createElement('tr');
  ['Order', 'Label', ...visibleColumns.map(({ column }) => String(column.heading || column.tag_name || column.field || 'Column')), 'Actions']
    .forEach((text) => {
      const th = document.createElement('th');
      th.textContent = text;
      header.appendChild(th);
    });
  els.reportBuilderSummariesHead.appendChild(header);
  const choices = [
    ['none', 'Blank'], ['sum', 'Total'], ['avg', 'Average'], ['min', 'Minimum'],
    ['max', 'Maximum'], ['first', 'First'], ['last', 'Last'],
    ['count', 'Sample count'], ['missing', 'Missing count'], ['formula', 'Formula…']
  ];
  state.reportBuilderSummaries.forEach((summary, summaryIndex) => {
    if (!Array.isArray(summary.calculations)) summary.calculations = [];
    if (!Array.isArray(summary.formulas)) summary.formulas = [];
    if (!Array.isArray(summary.precisions)) summary.precisions = [];
    const tr = document.createElement('tr');
    tr.className = 'report-summary-config-row';
    const orderCell = document.createElement('td');
    orderCell.className = 'report-summary-order';
    const dragHandle = document.createElement('span');
    dragHandle.className = 'report-summary-drag-handle';
    dragHandle.draggable = true;
    dragHandle.title = `Drag to move summary row ${summaryIndex + 1}`;
    dragHandle.setAttribute('aria-label', `Drag to move summary row ${summaryIndex + 1}`);
    dragHandle.textContent = `⠿ ${summaryIndex + 1}`;
    dragHandle.addEventListener('dragstart', (event) => {
      state.reportBuilderDraggedSummaryIndex = summaryIndex;
      tr.classList.add('is-dragging');
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', String(summaryIndex));
      }
    });
    dragHandle.addEventListener('dragend', () => {
      state.reportBuilderDraggedSummaryIndex = -1;
      els.reportBuilderSummaries?.querySelectorAll('.report-summary-config-row').forEach((row) => {
        row.classList.remove('is-dragging', 'drag-before', 'drag-after');
      });
    });
    orderCell.appendChild(dragHandle);
    tr.addEventListener('dragover', (event) => {
      const fromIndex = state.reportBuilderDraggedSummaryIndex;
      if (fromIndex < 0 || fromIndex === summaryIndex) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      const after = event.clientY >= tr.getBoundingClientRect().top + tr.offsetHeight / 2;
      tr.classList.toggle('drag-before', !after);
      tr.classList.toggle('drag-after', after);
    });
    tr.addEventListener('dragleave', () => {
      tr.classList.remove('drag-before', 'drag-after');
    });
    tr.addEventListener('drop', (event) => {
      event.preventDefault();
      const fromIndex = state.reportBuilderDraggedSummaryIndex;
      if (fromIndex < 0 || fromIndex >= state.reportBuilderSummaries.length || fromIndex === summaryIndex) return;
      const after = event.clientY >= tr.getBoundingClientRect().top + tr.offsetHeight / 2;
      let insertIndex = summaryIndex + (after ? 1 : 0);
      const [moved] = state.reportBuilderSummaries.splice(fromIndex, 1);
      if (fromIndex < insertIndex) insertIndex -= 1;
      state.reportBuilderSummaries.splice(insertIndex, 0, moved);
      state.reportBuilderDraggedSummaryIndex = -1;
      renderReportBuilderSummaries();
    });
    const labelCell = document.createElement('td');
    const label = document.createElement('input');
    label.value = String(summary.label || '');
    label.placeholder = 'Summary';
    label.addEventListener('input', () => { summary.label = label.value; });
    labelCell.appendChild(label);
    tr.append(orderCell, labelCell);
    visibleColumns.forEach(({ index: columnIndex }) => {
      const td = document.createElement('td');
      const select = document.createElement('select');
      choices.forEach(([value, text]) => {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = text;
        select.appendChild(option);
      });
      select.value = String(summary.calculations[columnIndex] || 'none');
      const editFormula = document.createElement('button');
      editFormula.className = 'btn report-summary-formula-button';
      editFormula.type = 'button';
      editFormula.textContent = summary.formulas[columnIndex] ? 'Edit Formula' : 'Set Formula';
      editFormula.hidden = select.value !== 'formula';
      editFormula.addEventListener('click', () => openReportSummaryFormulaModal(summaryIndex, columnIndex));
      select.addEventListener('change', () => {
        summary.calculations[columnIndex] = select.value;
        if (select.value === 'formula') openReportSummaryFormulaModal(summaryIndex, columnIndex);
        else renderReportBuilderSummaries();
      });
      const controls = document.createElement('div');
      controls.className = 'report-summary-cell-controls';
      controls.append(select, editFormula);
      td.appendChild(controls);
      tr.appendChild(td);
    });
    const actions = document.createElement('td');
    const actionButtons = document.createElement('div');
    actionButtons.className = 'report-summary-action-buttons';
    const up = document.createElement('button');
    up.className = 'btn';
    up.type = 'button';
    up.textContent = '↑ Move up';
    up.disabled = summaryIndex === 0;
    up.addEventListener('click', () => {
      [state.reportBuilderSummaries[summaryIndex - 1], state.reportBuilderSummaries[summaryIndex]] =
        [state.reportBuilderSummaries[summaryIndex], state.reportBuilderSummaries[summaryIndex - 1]];
      renderReportBuilderSummaries();
    });
    const down = document.createElement('button');
    down.className = 'btn';
    down.type = 'button';
    down.textContent = '↓ Move down';
    down.disabled = summaryIndex === state.reportBuilderSummaries.length - 1;
    down.addEventListener('click', () => {
      [state.reportBuilderSummaries[summaryIndex], state.reportBuilderSummaries[summaryIndex + 1]] =
        [state.reportBuilderSummaries[summaryIndex + 1], state.reportBuilderSummaries[summaryIndex]];
      renderReportBuilderSummaries();
    });
    const remove = document.createElement('button');
    remove.className = 'btn danger';
    remove.type = 'button';
    remove.textContent = 'Remove';
    remove.addEventListener('click', () => {
      state.reportBuilderSummaries.splice(summaryIndex, 1);
      renderReportBuilderSummaries();
    });
    actionButtons.append(up, down, remove);
    actions.appendChild(actionButtons);
    tr.appendChild(actions);
    els.reportBuilderSummaries.appendChild(tr);
  });
}

function renderReportBuilderColumns() {
  if (!els.reportBuilderColumns) return;
  els.reportBuilderColumns.textContent = '';
  state.reportBuilderColumns.forEach((column, index) => {
    const tr = document.createElement('tr');
    tr.className = 'report-column-row';
    const order = document.createElement('td');
    order.className = 'report-column-order';
    const dragHandle = document.createElement('span');
    dragHandle.className = 'report-column-drag-handle';
    dragHandle.draggable = true;
    dragHandle.title = `Drag to move column ${index + 1}`;
    dragHandle.setAttribute('aria-label', `Drag to move column ${index + 1}`);
    dragHandle.textContent = `⠿ ${index + 1}`;
    dragHandle.addEventListener('dragstart', (event) => {
      state.reportBuilderDraggedColumnIndex = index;
      tr.classList.add('is-dragging');
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', String(index));
      }
    });
    dragHandle.addEventListener('dragend', () => {
      state.reportBuilderDraggedColumnIndex = -1;
      els.reportBuilderColumns?.querySelectorAll('.report-column-row').forEach((row) => {
        row.classList.remove('is-dragging', 'drag-before', 'drag-after');
      });
    });
    order.appendChild(dragHandle);
    tr.addEventListener('dragover', (event) => {
      const fromIndex = state.reportBuilderDraggedColumnIndex;
      if (fromIndex < 0 || fromIndex === index) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      const after = event.clientY >= tr.getBoundingClientRect().top + tr.offsetHeight / 2;
      tr.classList.toggle('drag-before', !after);
      tr.classList.toggle('drag-after', after);
    });
    tr.addEventListener('dragleave', () => {
      tr.classList.remove('drag-before', 'drag-after');
    });
    tr.addEventListener('drop', (event) => {
      event.preventDefault();
      const fromIndex = state.reportBuilderDraggedColumnIndex;
      if (fromIndex < 0 || fromIndex >= state.reportBuilderColumns.length || fromIndex === index) return;
      const after = event.clientY >= tr.getBoundingClientRect().top + tr.offsetHeight / 2;
      let insertIndex = index + (after ? 1 : 0);
      const [moved] = state.reportBuilderColumns.splice(fromIndex, 1);
      if (fromIndex < insertIndex) insertIndex -= 1;
      state.reportBuilderColumns.splice(insertIndex, 0, moved);
      reorderReportBuilderSummaryColumns(fromIndex, insertIndex);
      state.reportBuilderDraggedColumnIndex = -1;
      renderReportBuilderColumns();
    });
    const headingCell = document.createElement('td');
    const heading = document.createElement('input');
    heading.value = String(column.heading || column.tag_name || '');
    heading.addEventListener('input', () => { column.heading = heading.value; });
    headingCell.appendChild(heading);
    const connection = document.createElement('td');
    connection.textContent = column.source === 'calculated' ? 'Calculated' : (column.source === 'database'
      ? String(column.database_id || '')
      : String(column.connection_id || ''));
    const tag = document.createElement('td');
    if (column.source === 'calculated') {
      const editFormula = document.createElement('button');
      editFormula.className = 'btn';
      editFormula.type = 'button';
      editFormula.textContent = 'Edit Formula';
      editFormula.addEventListener('click', () => openReportFormulaModal(index));
      tag.appendChild(editFormula);
    } else if (column.source === 'database' && column.layout === 'category') {
      tag.textContent = `${String(column.category_value ?? '')} (value: ${String(column.field || '')})`;
    } else {
      tag.textContent = column.source === 'database'
        ? String(column.field || '')
        : String(column.tag_name || '');
    }
    const companionCell = document.createElement('td');
    if (column.source === 'database') {
      const controls = document.createElement('div'); controls.className = 'report-companion-controls';
      const companion = document.createElement('select'); companion.title = 'Optional text field';
      const profile = selectedReportDataSource() || state.reportBuilderDataSources.find((source) =>
        source.database_id === column.database_id && source.table === column.table);
      const profileFields = (profile?.value_fields || []).filter((field) =>
        field.column !== column.field && String(field.type || 'numeric') === 'text');
      const schemaFields = (reportBuilderSelectedTable()?.columns || []).filter((field) => field.name !== column.field)
        .map((field) => ({ column: field.name, label: field.name }));
      const fields = profile ? profileFields : schemaFields;
      fillSelect(companion, [{ value: '', label: 'No additional text' },
        ...fields.map((field) => ({ value: field.column, label: field.label || field.column }))], String(column.companion_field || ''));
      const placement = document.createElement('select'); placement.title = 'Text placement';
      fillSelect(placement, [
        { value: 'before', label: 'Before value' }, { value: 'after', label: 'After value' },
        { value: 'text_only', label: 'Text only' }
      ], String(column.companion_position || 'before'));
      const separator = document.createElement('input'); separator.type = 'text'; separator.maxLength = 20;
      separator.style.width = '55px'; separator.title = 'Separator between text and value';
      separator.placeholder = 'space'; separator.value = String(column.companion_separator ?? ' ');
      const sync = () => {
        column.companion_field = companion.value;
        column.companion_position = companion.value ? placement.value : 'none';
        column.companion_separator = separator.value;
        placement.disabled = !companion.value; separator.disabled = !companion.value || placement.value === 'text_only';
      };
      companion.addEventListener('change', sync); placement.addEventListener('change', sync);
      separator.addEventListener('input', sync); sync(); controls.append(companion, placement, separator); companionCell.appendChild(controls);
    } else companionCell.textContent = '—';
    const calculationCell = document.createElement('td');
    const calculation = document.createElement('select');
    const calculations = column.source === 'database' && column.field_type === 'text'
      ? [['last', 'Last available value'], ['first', 'First value'], ['count', 'Count']]
      : column.source === 'database'
      ? [
          ['last', 'Last available value'], ['last_nonzero', 'Last non-zero value'],
          ['change', 'Change during period'],
          ['first', 'First value'], ['avg', 'Average'], ['min', 'Minimum'],
          ['max', 'Maximum'], ['sum', 'Total'], ['count', 'Count']
        ]
      : [['last', 'Last available value']];
    if (column.source === 'calculated') calculations.splice(0, calculations.length);
    calculations.forEach(([value, label]) => {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = label;
      calculation.appendChild(option);
    });
    calculation.value = String(column.aggregation || 'last');
    calculation.addEventListener('change', () => {
      column.aggregation = calculation.value;
      renderReportBuilderColumns();
    });
    if (column.source === 'calculated') calculationCell.textContent = 'Formula';
    else calculationCell.appendChild(calculation);
    const multiplierCell = document.createElement('td');
    const multiplier = document.createElement('input');
    multiplier.type = 'number';
    multiplier.step = 'any';
    multiplier.style.width = '90px';
    multiplier.value = String(column.multiplier ?? 1);
    multiplier.addEventListener('input', () => {
      const value = Number(multiplier.value);
      column.multiplier = Number.isFinite(value) ? value : 1;
    });
    if (column.source === 'calculated' || column.field_type === 'text') multiplierCell.textContent = '—';
    else multiplierCell.appendChild(multiplier);
    const precisionCell = document.createElement('td');
    const precision = document.createElement('input');
    precision.type = 'number';
    precision.min = '0';
    precision.max = '10';
    precision.style.width = '72px';
    precision.value = String(column.precision ?? 2);
    precision.addEventListener('input', () => { column.precision = Math.max(0, Math.min(10, Number(precision.value) || 0)); });
    if (column.source === 'database' && column.field_type === 'text') precisionCell.textContent = '—';
    else precisionCell.appendChild(precision);
    const visibleCell = document.createElement('td');
    visibleCell.style.textAlign = 'center';
    const visible = document.createElement('input');
    visible.type = 'checkbox';
    visible.checked = column.visible !== false;
    visible.title = 'Show this column in the report';
    visible.addEventListener('change', () => {
      column.visible = visible.checked;
      renderReportBuilderSummaries();
    });
    visibleCell.appendChild(visible);
    const decreaseCell = document.createElement('td');
    decreaseCell.className = 'report-counter-decrease';
    if (column.source === 'database' && String(column.aggregation || 'last') === 'change') {
      const decreaseControls = document.createElement('div');
      decreaseControls.className = 'report-counter-decrease-controls';
      const handling = document.createElement('select');
      handling.className = 'report-counter-decrease-select';
      [
        ['blank', 'Leave blank'], ['reset', 'Counter reset'], ['rollover', 'Counter rollover']
      ].forEach(([value, label]) => {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = label;
        handling.appendChild(option);
      });
      handling.value = String(column.negative_change || 'blank');
      handling.addEventListener('change', () => {
        column.negative_change = handling.value;
        renderReportBuilderColumns();
      });
      decreaseControls.appendChild(handling);
      if (handling.value === 'rollover') {
        const modulus = document.createElement('input');
        modulus.type = 'number';
        modulus.className = 'report-counter-rollover';
        modulus.min = '1';
        modulus.step = '1';
        modulus.title = 'Counter rollover value; use 65536 for an unsigned 16-bit counter.';
        modulus.style.width = '105px';
        modulus.value = String(column.rollover_modulus ?? 65536);
        modulus.addEventListener('input', () => {
          const value = Number(modulus.value);
          column.rollover_modulus = Number.isFinite(value) && value > 0 ? value : 65536;
        });
        decreaseControls.appendChild(modulus);
      }
      decreaseCell.appendChild(decreaseControls);
    } else {
      decreaseCell.textContent = '—';
    }
    const actions = document.createElement('td');
    actions.className = 'report-column-actions';
    const up = document.createElement('button');
    up.className = 'btn';
    up.type = 'button';
    up.textContent = '↑ Move up';
    up.disabled = index === 0;
    up.addEventListener('click', () => {
      [state.reportBuilderColumns[index - 1], state.reportBuilderColumns[index]] =
        [state.reportBuilderColumns[index], state.reportBuilderColumns[index - 1]];
      reorderReportBuilderSummaryColumns(index, index - 1);
      renderReportBuilderColumns();
    });
    const down = document.createElement('button');
    down.className = 'btn';
    down.type = 'button';
    down.textContent = '↓ Move down';
    down.disabled = index === state.reportBuilderColumns.length - 1;
    down.addEventListener('click', () => {
      [state.reportBuilderColumns[index], state.reportBuilderColumns[index + 1]] =
        [state.reportBuilderColumns[index + 1], state.reportBuilderColumns[index]];
      reorderReportBuilderSummaryColumns(index, index + 1);
      renderReportBuilderColumns();
    });
    const remove = document.createElement('button');
    remove.className = 'btn danger';
    remove.type = 'button';
    remove.textContent = 'Remove';
    remove.addEventListener('click', () => {
      state.reportBuilderColumns.splice(index, 1);
      state.reportBuilderSummaries.forEach((summary) => summary.calculations?.splice(index, 1));
      state.reportBuilderSummaries.forEach((summary) => summary.formulas?.splice(index, 1));
      state.reportBuilderSummaries.forEach((summary) => summary.precisions?.splice(index, 1));
      renderReportBuilderColumns();
    });
    const actionButtons = document.createElement('div');
    actionButtons.className = 'report-column-action-buttons';
    actionButtons.append(up, down, remove);
    actions.appendChild(actionButtons);
    tr.append(order, headingCell, connection, tag, companionCell, calculationCell, multiplierCell, precisionCell, visibleCell, decreaseCell, actions);
    els.reportBuilderColumns.appendChild(tr);
  });
  renderReportBuilderSummaries();
  renderReportBuilderSourceUi();
}

function loadReportBuilderDefinition(report) {
  const value = report || {
    id: '', name: '', description: '', timezone: browserTimezone(),
    published: false, formats: ['xlsx', 'csv'], columns: []
  };
  state.reportBuilderOriginalId = String(value.id || '');
  state.reportBuilderColumns = Array.isArray(value.columns) ? value.columns.map((column, index) => ({
    ...column,
    id: String(column.id || `column_${index + 1}`),
    visible: column.visible !== false
  })) : [];
  state.reportBuilderSummaries = Array.isArray(value.summaries)
    ? value.summaries.map((summary) => ({
        label: String(summary?.label || ''),
        calculations: Array.isArray(summary?.calculations) ? [...summary.calculations] : [],
        formulas: Array.isArray(summary?.formulas) ? [...summary.formulas] : [],
        precisions: Array.isArray(summary?.precisions) ? [...summary.precisions] : []
      })) : [];
  state.reportBuilderAccess = Array.isArray(value.access) ? value.access.map((grant) => ({ ...grant })) : [];
  const layout = value.layout && typeof value.layout === 'object' ? value.layout : {};
  state.reportBuilderLayoutPlacedCells = migrateLayoutPlacedCells(layout, !report);
  state.reportBuilderTemplate = value.template && typeof value.template === 'object'
    ? { ...value.template, enabled: value.template.enabled === true }
    : null;
  state.reportBuilderTemplatePreview = null;
  if (!report) {
    const ownGroups = (Array.isArray(state.opcbridgeAuthStatus?.user?.groups)
      ? state.opcbridgeAuthStatus.user.groups : [])
      .map((group) => String(group || '').trim())
      .filter((group) => group && group !== 'admin');
    if (ownGroups.length === 1) {
      state.reportBuilderAccess.push({
        group_id: ownGroups[0], view: true, download: true, edit: true, manage: true
      });
    }
  }
  if (els.reportBuilderId) els.reportBuilderId.value = String(value.id || '');
  if (els.reportBuilderName) els.reportBuilderName.value = String(value.name || '');
  if (els.reportBuilderDescription) els.reportBuilderDescription.value = String(value.description || '');
  if (els.reportBuilderPeriod) els.reportBuilderPeriod.value = String(value.period || 'month');
  if (els.reportBuilderHmiEnabled) els.reportBuilderHmiEnabled.checked = value.hmi_enabled === true;
  if (els.reportBuilderWeekStart) els.reportBuilderWeekStart.value = String(value.week_start || 'sunday');
  if (els.reportBuilderWeekStartLabel) els.reportBuilderWeekStartLabel.style.display = String(value.period || 'month') === 'weekly' ? '' : 'none';
  if (els.reportBuilderInterval) els.reportBuilderInterval.value = String(value.interval_minutes || 60);
  if (els.reportBuilderIntervalLabel) {
    els.reportBuilderIntervalLabel.style.display = String(value.period || 'month') === 'daily' ? '' : 'none';
  }
  if (els.reportBuilderGroupBy) els.reportBuilderGroupBy.value = String(value.group_by || 'day');
  if (els.reportBuilderGroupByLabel) {
    els.reportBuilderGroupByLabel.style.display = String(value.period || 'month') === 'custom' ? '' : 'none';
  }
  populateReportBuilderTimezones(String(value.timezone || browserTimezone()));
  if (els.reportBuilderPublished) els.reportBuilderPublished.checked = Boolean(value.published);
  if (els.reportBuilderXlsx) els.reportBuilderXlsx.checked = (value.formats || []).includes('xlsx');
  if (els.reportBuilderOds) els.reportBuilderOds.checked = (value.formats || []).includes('ods');
  if (els.reportBuilderCsv) els.reportBuilderCsv.checked = (value.formats || []).includes('csv');
  if (els.reportBuilderLayoutWorksheet) els.reportBuilderLayoutWorksheet.value = String(layout.worksheet || 'Report');
  if (els.reportBuilderLayoutTableRow) els.reportBuilderLayoutTableRow.value = String(layout.table_start_row || 5);
  if (els.reportBuilderLayoutTableColumn) els.reportBuilderLayoutTableColumn.value = String(layout.table_start_column || 'A');
  if (els.reportBuilderLayoutIncludeHeader) els.reportBuilderLayoutIncludeHeader.checked = layout.include_header_row !== false;
  if (els.reportBuilderLayoutSummaryGap) els.reportBuilderLayoutSummaryGap.value = String(layout.summary_gap_rows || 0);
  if (els.reportBuilderLayoutSummaryPlacement) els.reportBuilderLayoutSummaryPlacement.value = String(layout.summary_placement || 'after_data');
  if (els.reportBuilderLayoutSummaryRow) els.reportBuilderLayoutSummaryRow.value = String(layout.summary_start_row || 40);
  const source = { ...(value.data_source || { type: 'historian' }) };
  const firstDatabaseColumn = state.reportBuilderColumns.find((column) => column?.source === 'database');
  if (source.type === 'database' && firstDatabaseColumn) {
    source.database_id = String(firstDatabaseColumn.database_id || source.database_id || '');
    source.table = String(firstDatabaseColumn.table || source.table || '');
    source.time_column = String(firstDatabaseColumn.time_column || source.time_column || '');
    source.layout = String(firstDatabaseColumn.layout || source.layout || 'wide');
    source.value_column = String(firstDatabaseColumn.field || source.value_column || '');
    if (source.layout === 'category') {
      source.category_column = String(firstDatabaseColumn.category_column || source.category_column || '');
    }
  }
  if (els.reportBuilderSourceType) els.reportBuilderSourceType.value = String(source.type || 'historian');
  if (els.reportBuilderLayout) els.reportBuilderLayout.value = String(source.layout || 'wide');
  renderReportBuilderDatabaseSources(String(source.database_id || ''));
  renderReportBuilderDataSources(String(source.source_id || ''));
  renderReportBuilderSourceUi();
  if (source.type === 'database') {
    const predefined = state.reportBuilderDataSources.find((item) => item.id === source.source_id);
    if (predefined) applyReportDataSource(predefined);
    else loadReportBuilderDatabaseSchema(source).catch(() => {});
  }
  renderReportBuilderColumns();
  renderReportBuilderAccess();
  renderReportBuilderLayout();
  if (state.reportBuilderTemplate?.stored_id) refreshReportBuilderTemplatePreview().catch(() => {});
}

function renderReportBuilderTags() {
  if (!els.reportBuilderTagSelect) return;
  els.reportBuilderTagSelect.textContent = '';
  state.reportBuilderTags
    .slice()
    .sort((a, b) => `${a.connection_id}:${a.tag_name}`.localeCompare(`${b.connection_id}:${b.tag_name}`))
    .forEach((tag) => {
      const option = document.createElement('option');
      option.value = `${tag.connection_id}\u001f${tag.tag_name}`;
      option.textContent = `${tag.connection_id} — ${tag.tag_name}`;
      els.reportBuilderTagSelect.appendChild(option);
    });
}

async function refreshReportBuilder() {
  if (!canAccessReportsTab()) {
    if (els.reportBuilderCard) els.reportBuilderCard.style.display = 'none';
    return;
  }
  try {
    const [definitions, tags, sources, dataSources] = await Promise.all([
      apiGet('/api/reports/admin'),
      apiGet('/api/historian/tags').catch(() => ({ tags: [] })),
      apiGet('/api/reports/admin/sources').catch(() => ({ databases: [] })),
      apiGet('/api/reports/data-sources').catch(() => ({ sources: [] }))
    ]);
    state.reportBuilderReports = Array.isArray(definitions?.reports) ? definitions.reports : [];
    state.reportBuilderTags = Array.isArray(tags?.tags) ? tags.tags.filter((tag) => tag?.connection_id && tag?.tag_name) : [];
    state.reportBuilderDatabases = Array.isArray(sources?.databases) ? sources.databases : [];
    state.reportBuilderDataSources = Array.isArray(dataSources?.sources) ? dataSources.sources : [];
    renderReportBuilderDatabaseSources(els.reportBuilderDatabase?.value || '');
    renderReportBuilderDataSources(els.reportBuilderDataSource?.value || '');
    renderReportBuilderTags();
  } catch (err) {
    reportBuilderSetStatus(err.message || err);
  }
}

async function saveReportBuilderDefinition() {
  const report = reportBuilderCurrentDefinition();
  reportBuilderSetStatus('Saving…');
  const response = await apiPostJson('/api/reports/admin', {
    original_id: state.reportBuilderOriginalId,
    report
  });
  state.reportBuilderOriginalId = response.report.id;
  await refreshReportBuilder();
  await refreshPublishedReports(false);
  if (els.publishedReportSelect) {
    els.publishedReportSelect.value = response.report.id;
    renderPublishedReportSelection();
  }
  loadReportBuilderDefinition(response.report);
  if (els.reportBuilderTitle) els.reportBuilderTitle.textContent = `Edit ${response.report.name || 'Report'}`;
  const savedPermissions = reportPermissions(response.report);
  if (els.reportBuilderDuplicateBtn) {
    els.reportBuilderDuplicateBtn.style.display = savedPermissions.manage ? '' : 'none';
    els.reportBuilderDuplicateBtn.disabled = !savedPermissions.manage;
  }
  if (els.reportBuilderDeleteBtn) {
    els.reportBuilderDeleteBtn.style.display = savedPermissions.manage ? '' : 'none';
    els.reportBuilderDeleteBtn.disabled = !savedPermissions.manage;
  }
  reportBuilderSetStatus('Saved.');
  return response.report;
}

function renderReportBuilderPreview(preview) {
  if (!els.reportBuilderPreviewHead || !els.reportBuilderPreviewBody || !els.reportBuilderPreviewWrap) return;
  els.reportBuilderPreviewHead.textContent = '';
  els.reportBuilderPreviewBody.textContent = '';
  const headerRow = document.createElement('tr');
  const periodHeading = ['hour', 'raw'].includes(String(preview.group_by || '')) ||
    String(preview.group_by || '').startsWith('minute:')
    ? 'Time' : (preview.group_by === 'month' ? 'Month' : 'Date');
  [periodHeading, ...(preview.columns || []).map((column) => column.heading)].forEach((heading) => {
    const th = document.createElement('th');
    th.textContent = String(heading || '');
    headerRow.appendChild(th);
  });
  els.reportBuilderPreviewHead.appendChild(headerRow);
  (preview.rows || []).forEach((row) => {
    const tr = document.createElement('tr');
    const cells = [row.date, ...(row.values || [])];
    cells.forEach((value, index) => {
      const td = document.createElement('td');
      if (value === null || value === undefined) td.textContent = '—';
      else if (index > 0) td.textContent = Number(value).toLocaleString(undefined, {
        minimumFractionDigits: preview.columns?.[index - 1]?.precision ?? 0,
        maximumFractionDigits: preview.columns?.[index - 1]?.precision ?? 2
      });
      else td.textContent = String(value);
      tr.appendChild(td);
    });
    els.reportBuilderPreviewBody.appendChild(tr);
  });
  renderReportPreviewSummaryRows(els.reportBuilderPreviewBody, preview);
  els.reportBuilderPreviewWrap.style.display = '';
}

function renderReportPreviewSummaryRows(body, preview) {
  (preview.summary_rows || []).forEach((row) => {
    const tr = document.createElement('tr');
    tr.className = 'report-summary-row';
    [row.label, ...(row.values || [])].forEach((value, index) => {
      const td = document.createElement('td');
      if (value === null || value === undefined) td.textContent = '';
      else if (index > 0 && typeof value === 'number') {
        const precision = row.precisions?.[index - 1] ?? preview.columns?.[index - 1]?.precision;
        td.textContent = value.toLocaleString(undefined, {
          minimumFractionDigits: precision ?? 0,
          maximumFractionDigits: precision ?? 2
        });
      }
      else td.textContent = String(value);
      tr.appendChild(td);
    });
    body.appendChild(tr);
  });
}

function wireReportBuilderUi() {
  populateReportBuilderTimezones();
  els.reportBuilderTabs?.querySelectorAll('[data-report-builder-tab]').forEach((button) => {
    button.addEventListener('click', () => setReportBuilderTab(button.dataset.reportBuilderTab));
  });
  [els.reportBuilderLayoutWorksheet, els.reportBuilderLayoutTableRow, els.reportBuilderLayoutTableColumn,
    els.reportBuilderLayoutSummaryGap, els.reportBuilderLayoutSummaryPlacement, els.reportBuilderLayoutSummaryRow,
    els.reportBuilderName, els.reportBuilderDescription].forEach((input) => {
    input?.addEventListener('input', () => {
      if (state.reportBuilderActiveTab === 'layout') renderReportBuilderLayoutPreview();
    });
  });
  els.reportBuilderLayoutIncludeHeader?.addEventListener('change', () => {
    if (state.reportBuilderActiveTab === 'layout') renderReportBuilderLayoutPreview();
  });
  els.reportBuilderTemplateEnabled?.addEventListener('change', () => {
    if (state.reportBuilderTemplate) state.reportBuilderTemplate.enabled = els.reportBuilderTemplateEnabled.checked;
    renderReportBuilderLayoutPreview();
  });
  els.reportBuilderLayoutWorksheet?.addEventListener('change', () => {
    if (state.reportBuilderTemplate?.stored_id) refreshReportBuilderTemplatePreview().catch(() => {});
  });
  els.reportBuilderTemplateUploadBtn?.addEventListener('click', async () => {
    const file = els.reportBuilderTemplateFile?.files?.[0];
    if (!file) {
      if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = 'Choose an .xlsx or .ods template first.';
      return;
    }
    const reportId = state.reportBuilderOriginalId || String(els.reportBuilderId?.value || '').trim();
    if (!reportId) {
      if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = 'Enter a report name before uploading a template.';
      return;
    }
    els.reportBuilderTemplateUploadBtn.disabled = true;
    if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = 'Uploading template…';
    try {
      const response = await fetch(`/api/reports/admin/template/upload?id=${encodeURIComponent(reportId)}`, {
        method: 'POST',
        credentials: 'same-origin',
        cache: 'no-store',
        headers: { 'Content-Type': file.type || 'application/octet-stream', 'X-File-Name': encodeURIComponent(file.name) },
        body: file
      });
      const body = await response.json().catch(() => ({}));
      if (!response.ok || !body?.ok) throw new Error(body?.error || `Upload failed (${response.status})`);
      state.reportBuilderTemplate = { ...body.template, enabled: true };
      state.reportBuilderTemplatePreview = body.preview || null;
      if (body.preview?.worksheet && els.reportBuilderLayoutWorksheet) {
        els.reportBuilderLayoutWorksheet.value = body.preview.worksheet;
      }
      if (els.reportBuilderTemplateFile) els.reportBuilderTemplateFile.value = '';
      renderReportBuilderTemplateControls();
      if (!state.reportBuilderTemplatePreview) await refreshReportBuilderTemplatePreview();
      else renderReportBuilderLayoutPreview();
      if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = 'Template staged. Save the report to make it active.';
    } catch (err) {
      if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = `Upload failed: ${err.message || err}`;
    } finally {
      els.reportBuilderTemplateUploadBtn.disabled = false;
    }
  });
  els.reportBuilderTemplateDownloadBtn?.addEventListener('click', () => {
    const template = state.reportBuilderTemplate;
    if (!template?.stored_id) return;
    const reportId = state.reportBuilderOriginalId || String(els.reportBuilderId?.value || '').trim();
    const query = new URLSearchParams({ id: reportId, stored_id: template.stored_id,
      format: template.format || 'xlsx', filename: template.filename || `report-template.${template.format || 'xlsx'}` });
    window.location.href = `/api/reports/admin/template/download?${query.toString()}`;
  });
  els.reportBuilderTemplateRemoveBtn?.addEventListener('click', () => {
    if (!state.reportBuilderTemplate?.stored_id) return;
    if (!window.confirm('Remove this template from the report? The change takes effect when the report is saved.')) return;
    state.reportBuilderTemplate = null;
    state.reportBuilderTemplatePreview = null;
    renderReportBuilderTemplateControls();
    renderReportBuilderLayoutPreview();
    if (els.reportBuilderTemplateStatus) els.reportBuilderTemplateStatus.textContent = 'Template removal staged. Save the report to apply it.';
  });
  const updateSummaryPlacement = () => {
    const fixed = String(els.reportBuilderLayoutSummaryPlacement?.value || 'after_data') === 'fixed';
    if (els.reportBuilderLayoutSummaryGapLabel) els.reportBuilderLayoutSummaryGapLabel.style.display = fixed ? 'none' : '';
    if (els.reportBuilderLayoutSummaryRowLabel) els.reportBuilderLayoutSummaryRowLabel.style.display = fixed ? '' : 'none';
    if (state.reportBuilderActiveTab === 'layout') renderReportBuilderLayoutPreview();
  };
  els.reportBuilderLayoutSummaryPlacement?.addEventListener('change', updateSummaryPlacement);
  updateSummaryPlacement();
  els.reportBuilderLayoutAddPlacedCellBtn?.addEventListener('click', () => {
    state.reportBuilderLayoutPlacedCells.push({ target: '', type: 'system', value: 'report_name', text: '', expression: '', date_format: '' });
    renderReportBuilderLayout();
  });
  if (els.reportBuilderAddSummaryBtn) els.reportBuilderAddSummaryBtn.addEventListener('click', () => {
    state.reportBuilderSummaries.push({
      label: 'Summary',
      calculations: state.reportBuilderColumns.map(() => 'none'),
      formulas: state.reportBuilderColumns.map(() => ''),
      precisions: state.reportBuilderColumns.map(() => null)
    });
    renderReportBuilderSummaries();
  });
  if (els.reportBuilderPeriod) els.reportBuilderPeriod.addEventListener('change', () => {
    if (els.reportBuilderIntervalLabel) {
      els.reportBuilderIntervalLabel.style.display = els.reportBuilderPeriod.value === 'daily' ? '' : 'none';
    }
    if (els.reportBuilderGroupByLabel) {
      els.reportBuilderGroupByLabel.style.display = els.reportBuilderPeriod.value === 'custom' ? '' : 'none';
    }
    if (els.reportBuilderWeekStartLabel) {
      els.reportBuilderWeekStartLabel.style.display = els.reportBuilderPeriod.value === 'weekly' ? '' : 'none';
    }
  });
  if (els.reportBuilderNewBtn) els.reportBuilderNewBtn.addEventListener('click', () => showReportBuilder(null));
  if (els.reportBuilderEditBtn) els.reportBuilderEditBtn.addEventListener('click', () => {
    const selected = selectedPublishedReport();
    const report = state.reportBuilderReports.find((item) => item.id === selected?.id) || selected;
    if (report) showReportBuilder(report);
  });
  if (els.reportBuilderBackBtn) els.reportBuilderBackBtn.addEventListener('click', () => {
    showReportsLanding();
    previewPublishedReport().catch(() => {});
  });
  if (els.reportBuilderSourceType) els.reportBuilderSourceType.addEventListener('change', () => {
    renderReportBuilderSourceUi();
    if (els.reportBuilderSourceType.value === 'database') {
      renderReportBuilderDataSources(els.reportBuilderDataSource?.value || '');
      const source = selectedReportDataSource();
      if (source) applyReportDataSource(source);
      else if (hasPerm('reports.administer')) {
        if (!state.reportBuilderSchema.length) loadReportBuilderDatabaseSchema().catch(() => {});
        else reportBuilderSourceSetStatus('Using advanced/manual database mapping.');
      } else reportBuilderSourceSetStatus('No predefined report data source is available for this database.');
    }
  });
  if (els.reportBuilderLayout) els.reportBuilderLayout.addEventListener('change', renderReportBuilderSourceUi);
  if (els.reportBuilderDatabase) els.reportBuilderDatabase.addEventListener('change', () => {
    renderReportBuilderDataSources('');
    const source = selectedReportDataSource();
    if (source) applyReportDataSource(source);
    else if (hasPerm('reports.administer')) loadReportBuilderDatabaseSchema().catch(() => {});
    else reportBuilderSourceSetStatus('No predefined report data source is available for this database.');
  });
  if (els.reportBuilderDataSource) els.reportBuilderDataSource.addEventListener('change', () => {
    const source = selectedReportDataSource();
    if (source) applyReportDataSource(source);
    else loadReportBuilderDatabaseSchema().catch(() => {});
    renderReportBuilderSourceUi();
  });
  if (els.reportBuilderManageDataSourcesBtn) els.reportBuilderManageDataSourcesBtn.addEventListener('click', openReportDataSourceModal);
  if (els.reportDataSourceCloseBtn) els.reportDataSourceCloseBtn.addEventListener('click', () => { els.reportDataSourceModal.style.display = 'none'; });
  if (els.reportDataSourceNewBtn) els.reportDataSourceNewBtn.addEventListener('click', () => {
    renderReportDataSourceExisting(''); loadReportDataSourceEditor(null); reportDataSourceSetStatus('');
  });
  if (els.reportDataSourceExisting) els.reportDataSourceExisting.addEventListener('change', () => {
    const source = state.reportBuilderDataSources.find((item) => item.id === els.reportDataSourceExisting.value) || null;
    loadReportDataSourceEditor(source); if (els.reportDataSourceDeleteBtn) els.reportDataSourceDeleteBtn.disabled = !source;
  });
  if (els.reportDataSourceDatabase) els.reportDataSourceDatabase.addEventListener('change', () => loadReportDataSourceSchema().catch(() => {}));
  if (els.reportDataSourceTable) els.reportDataSourceTable.addEventListener('change', () => renderReportDataSourceSchema());
  if (els.reportDataSourceLayout) els.reportDataSourceLayout.addEventListener('change', () => {
    if (els.reportDataSourceCategoryLabel) els.reportDataSourceCategoryLabel.style.display = els.reportDataSourceLayout.value === 'category' ? '' : 'none';
  });
  if (els.reportDataSourceSaveBtn) els.reportDataSourceSaveBtn.addEventListener('click', () => saveReportDataSource());
  if (els.reportDataSourceDeleteBtn) els.reportDataSourceDeleteBtn.addEventListener('click', async () => {
    const id = String(state.reportDataSourceOriginalId || '');
    if (!id || !window.confirm('Delete this report data source? Existing reports will retain their saved database mapping.')) return;
    reportDataSourceSetStatus('Deleting…');
    try {
      await apiPostJson('/api/reports/data-sources/delete', { id });
      await refreshReportBuilder(); renderReportDataSourceExisting(''); loadReportDataSourceEditor(null);
      renderReportBuilderDataSources(els.reportBuilderDataSource?.value || ''); reportDataSourceSetStatus('Data source deleted.');
    } catch (err) { reportDataSourceSetStatus(err.message || err); }
  });
  if (els.reportBuilderTable) els.reportBuilderTable.addEventListener('change', () => {
    renderReportBuilderSchemaSelections();
    if (els.reportBuilderCategoryPicker) els.reportBuilderCategoryPicker.style.display = 'none';
  });
  if (els.reportBuilderAddDatabaseFieldBtn) els.reportBuilderAddDatabaseFieldBtn.addEventListener('click', () => {
    const field = String(els.reportBuilderDatabaseField?.value || '').trim();
    const databaseId = String(els.reportBuilderDatabase?.value || '').trim();
    if (!field || !databaseId) return;
    const sourceField = selectedReportDataSource()?.value_fields?.find((item) => item.column === field);
    state.reportBuilderColumns.push({
      id: newReportColumnId(field),
      heading: field,
      source: 'database',
      database_id: databaseId,
      table: String(els.reportBuilderTable?.value || '').trim(),
      time_column: String(els.reportBuilderTimeColumn?.value || '').trim(),
      layout: 'wide',
      field,
      field_type: String(sourceField?.type || 'numeric'),
      aggregation: String(els.reportBuilderAggregation?.value || 'last'),
      multiplier: 1,
      negative_change: 'blank',
      rollover_modulus: 65536,
      precision: 2
    });
    renderReportBuilderColumns();
  });
  if (els.reportBuilderLoadCategoriesBtn) els.reportBuilderLoadCategoriesBtn.addEventListener('click', async () => {
    const payload = {
      database_id: String(els.reportBuilderDatabase?.value || '').trim(),
      table: String(els.reportBuilderTable?.value || '').trim(),
      column: String(els.reportBuilderCategoryColumn?.value || '').trim()
    };
    reportBuilderSourceSetStatus('Finding available item names…');
    try {
      const database = state.reportBuilderDatabases.find(
        (candidate) => String(candidate?.id || '') === payload.database_id
      ) || {};
      const response = await apiPostJson('/api/reports/admin/distinct', payload, {
        timeoutMs: reporterDatabaseDiscoveryTimeoutMs(database)
      });
      state.reportBuilderCategoryItems = (response.values || []).map((value) => String(value));
      state.reportBuilderSelectedCategoryItems = new Set();
      if (els.reportBuilderCategoryFilter) els.reportBuilderCategoryFilter.value = '';
      renderReportBuilderCategoryItems(false);
      if (els.reportBuilderCategoryPicker) els.reportBuilderCategoryPicker.style.display = '';
      const count = response.values?.length || 0;
      reportBuilderSourceSetStatus(response.truncated
        ? `${count} item name(s) loaded (limit reached)`
        : `${count} item name(s) available`);
    } catch (err) {
      reportBuilderSourceSetStatus(err.message || err);
    }
  });
  if (els.reportBuilderAddCategoriesBtn) els.reportBuilderAddCategoriesBtn.addEventListener('click', () => {
    syncReportBuilderCategorySelections();
    const databaseId = String(els.reportBuilderDatabase?.value || '').trim();
    const valueField = String(els.reportBuilderValueColumn?.value || '').trim();
    const sourceField = selectedReportDataSource()?.value_fields?.find((field) => field.column === valueField);
    state.reportBuilderSelectedCategoryItems.forEach((itemName) => {
      state.reportBuilderColumns.push({
        id: newReportColumnId(itemName),
        heading: itemName,
        source: 'database',
        database_id: databaseId,
        table: String(els.reportBuilderTable?.value || '').trim(),
        time_column: String(els.reportBuilderTimeColumn?.value || '').trim(),
        layout: 'category',
        category_column: String(els.reportBuilderCategoryColumn?.value || '').trim(),
        field: valueField,
        field_type: String(sourceField?.type || 'numeric'),
        category_value: itemName,
        aggregation: String(els.reportBuilderAggregation?.value || 'last'),
        multiplier: 1,
        negative_change: 'blank',
        rollover_modulus: 65536,
        precision: 2
      });
    });
    state.reportBuilderSelectedCategoryItems = new Set();
    renderReportBuilderCategoryItems(false);
    renderReportBuilderColumns();
  });
  if (els.reportBuilderCategoryValues) {
    els.reportBuilderCategoryValues.addEventListener('change', () => {
      syncReportBuilderCategorySelections();
      updateReportBuilderCategoryCount(els.reportBuilderCategoryValues.options.length);
    });
  }
  if (els.reportBuilderCategoryFilter) {
    els.reportBuilderCategoryFilter.addEventListener('input', renderReportBuilderCategoryItems);
  }
  if (els.reportBuilderCategoryFilterClearBtn) {
    els.reportBuilderCategoryFilterClearBtn.addEventListener('click', () => {
      if (els.reportBuilderCategoryFilter) els.reportBuilderCategoryFilter.value = '';
      renderReportBuilderCategoryItems();
      els.reportBuilderCategoryFilter?.focus();
    });
  }
  if (els.reportBuilderAddTagBtn) els.reportBuilderAddTagBtn.addEventListener('click', () => {
    const [connectionId, tagName] = String(els.reportBuilderTagSelect?.value || '').split('\u001f');
    if (!connectionId || !tagName) return;
    state.reportBuilderColumns.push({
      id: newReportColumnId(tagName),
      heading: tagName, source: 'historian', connection_id: connectionId,
      tag_name: tagName, aggregation: 'last', precision: 2
    });
    renderReportBuilderColumns();
  });
  if (els.reportBuilderAddCalculatedBtn) els.reportBuilderAddCalculatedBtn.addEventListener('click', () => {
    const column = {
      id: newReportColumnId('calculated_value'),
      heading: 'Calculated Value',
      source: 'calculated',
      expression: '',
      precision: 2,
      visible: true
    };
    state.reportBuilderColumns.push(column);
    state.reportBuilderSummaries.forEach((summary) => summary.calculations?.push('none'));
    state.reportBuilderSummaries.forEach((summary) => summary.formulas?.push(''));
    state.reportBuilderSummaries.forEach((summary) => summary.precisions?.push(null));
    renderReportBuilderColumns();
    openReportFormulaModal(state.reportBuilderColumns.length - 1);
  });
  [els.reportFormulaCloseBtn, els.reportFormulaCancelBtn].forEach((button) => {
    button?.addEventListener('click', closeReportFormulaModal);
  });
  if (els.reportFormulaSaveBtn) els.reportFormulaSaveBtn.addEventListener('click', () => {
    const expression = String(els.reportFormulaExpression?.value || '').trim();
    const placedCellIndex = state.reportFormulaPlacedCellIndex;
    if (placedCellIndex >= 0) {
      const item = state.reportBuilderLayoutPlacedCells[placedCellIndex];
      if (!item || item.type !== 'formula') return closeReportFormulaModal();
      if (!expression) {
        if (els.reportFormulaStatus) els.reportFormulaStatus.textContent = 'Enter a formula.';
        return;
      }
      item.expression = expression;
      const precision = Math.trunc(Number(els.reportFormulaPrecision?.value));
      item.precision = Number.isFinite(precision) ? Math.max(0, Math.min(10, precision)) : 2;
      closeReportFormulaModal();
      renderReportBuilderLayout();
      return;
    }
    const summaryIndex = state.reportFormulaSummaryIndex;
    const summaryColumnIndex = state.reportFormulaSummaryColumnIndex;
    if (summaryIndex >= 0 && summaryColumnIndex >= 0) {
      const summary = state.reportBuilderSummaries[summaryIndex];
      if (!summary) return closeReportFormulaModal();
      if (!expression) {
        if (els.reportFormulaStatus) els.reportFormulaStatus.textContent = 'Enter a formula.';
        return;
      }
      if (!Array.isArray(summary.formulas)) summary.formulas = [];
      if (!Array.isArray(summary.precisions)) summary.precisions = [];
      summary.calculations[summaryColumnIndex] = 'formula';
      summary.formulas[summaryColumnIndex] = expression;
      const precision = Math.trunc(Number(els.reportFormulaPrecision?.value));
      summary.precisions[summaryColumnIndex] = Number.isFinite(precision)
        ? Math.max(0, Math.min(10, precision)) : null;
      closeReportFormulaModal();
      renderReportBuilderSummaries();
      return;
    }
    const index = state.reportFormulaColumnIndex;
    const column = state.reportBuilderColumns[index];
    if (!column || column.source !== 'calculated') return closeReportFormulaModal();
    if (!expression) {
      if (els.reportFormulaStatus) els.reportFormulaStatus.textContent = 'Enter a formula.';
      return;
    }
    column.expression = expression;
    closeReportFormulaModal();
    renderReportBuilderColumns();
  });
  if (els.reportBuilderSaveBtn) els.reportBuilderSaveBtn.addEventListener('click', () => {
    saveReportBuilderDefinition().catch((err) => reportBuilderSetStatus(err.message || err));
  });
  if (els.reportBuilderPreviewBtn) els.reportBuilderPreviewBtn.addEventListener('click', async () => {
    try {
      const report = await saveReportBuilderDefinition();
      reportBuilderSetStatus('Generating preview…');
      const range = publishedReportRangePayload();
      if (!range) throw new Error('Select a valid report period.');
      const preview = await apiPostJson('/api/reports/admin/preview', {
        id: report.id,
        ...range
      }, { timeoutMs: 120000 });
      renderReportBuilderPreview(preview);
      reportBuilderSetStatus(preview.truncated
        ? `Preview reached the ${Number(preview.row_limit || 250000).toLocaleString()}-row limit; narrow the date range to inspect all samples.`
        : 'Preview ready.');
    } catch (err) {
      reportBuilderSetStatus(err.message || err);
    }
  });
  if (els.reportBuilderDuplicateBtn) els.reportBuilderDuplicateBtn.addEventListener('click', async () => {
    try {
      const response = await apiPostJson('/api/reports/admin/duplicate', { id: state.reportBuilderOriginalId });
      state.reportBuilderOriginalId = response.report.id;
      await refreshReportBuilder();
      await refreshPublishedReports(false);
      if (els.publishedReportSelect) {
        els.publishedReportSelect.value = response.report.id;
        renderPublishedReportSelection();
      }
      showReportBuilder(response.report);
    } catch (err) { reportBuilderSetStatus(err.message || err); }
  });
  if (els.reportBuilderDeleteBtn) els.reportBuilderDeleteBtn.addEventListener('click', async () => {
    if (!state.reportBuilderOriginalId || !window.confirm(`Delete report '${state.reportBuilderOriginalId}'?`)) return;
    try {
      await apiPostJson('/api/reports/admin/delete', { id: state.reportBuilderOriginalId });
      state.reportBuilderOriginalId = '';
      await refreshReportBuilder();
      await refreshPublishedReports();
      showReportsLanding();
    } catch (err) { reportBuilderSetStatus(err.message || err); }
  });
}

function selectedDataEntryForm() {
  const id = String(els.dataEntryFormSelect?.value || '');
  return state.dataEntryForms.find((form) => form.id === id) || null;
}

function dataEntrySetStatus(message) { if (els.dataEntryStatus) els.dataEntryStatus.textContent = String(message || ''); }
function dataEntryBuilderSetStatus(message) { if (els.dataEntryBuilderStatus) els.dataEntryBuilderStatus.textContent = String(message || ''); }

function renderDataEntryPreviewHeading() {
  const form = selectedDataEntryForm();
  if (els.dataEntryPreviewHeading) els.dataEntryPreviewHeading.style.display = form ? '' : 'none';
  if (els.dataEntryPreviewTitle) els.dataEntryPreviewTitle.textContent = form?.name || '';
  if (els.dataEntryPreviewDescription) els.dataEntryPreviewDescription.textContent = form?.description || '';
  [els.dataEntryPreviousBtn, els.dataEntryNextBtn, els.dataEntryLoadBtn, els.dataEntrySaveValuesBtn, els.dataEntryRevertBtn, els.dataEntryDownloadBtn, els.dataEntryDate]
    .forEach((control) => { if (control) control.disabled = !form; });
}

function renderDataEntryFields() {
  if (!els.dataEntryFields) return;
  els.dataEntryFields.textContent = '';
  const form = selectedDataEntryForm();
  if (!form) { els.dataEntryFields.textContent = 'Select a data-entry form.'; return; }
  (form.fields || []).forEach((field) => {
    const loaded = state.dataEntryLoadedValues?.[field.item] || {};
    const value = field.value_type === 'text' ? loaded.text : loaded.numeric;
    const row = document.createElement('div'); row.className = 'data-entry-field'; row.dataset.fieldId = field.id;
    const label = document.createElement('label'); label.textContent = field.label + (field.unit ? ` (${field.unit})` : '');
    const input = document.createElement('input'); input.type = field.value_type === 'numeric' ? 'number' : 'text';
    if (field.value_type === 'numeric') { input.step = String(1 / Math.pow(10, Number(field.precision ?? 2))); if (field.min != null) input.min = field.min; if (field.max != null) input.max = field.max; }
    input.value = value == null ? '' : String(value); input.dataset.original = input.value; input.required = field.required === true;
    row.append(label, input);
    if (form.allow_delete && loaded.timestamp) {
      const button = document.createElement('button'); button.type = 'button'; button.className = 'btn data-entry-delete'; button.textContent = 'Delete';
      button.addEventListener('click', () => { const marked = state.dataEntryDeletedFields.has(field.id); if (marked) state.dataEntryDeletedFields.delete(field.id); else state.dataEntryDeletedFields.add(field.id); row.classList.toggle('is-delete', !marked); input.disabled = !marked; button.textContent = marked ? 'Delete' : 'Undo Delete'; });
      row.appendChild(button);
    }
    els.dataEntryFields.appendChild(row);
  });
}

async function moveDataEntryDate(days) {
  if (!els.dataEntryDate?.value) return;
  const parts = els.dataEntryDate.value.split('-').map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isFinite(part))) return;
  const date = new Date(parts[0], parts[1] - 1, parts[2]);
  date.setDate(date.getDate() + days);
  els.dataEntryDate.value = localIsoDate(date);
  await loadDataEntryValues();
}

function downloadDataEntryValues() {
  const form = selectedDataEntryForm(); const recordDate = String(els.dataEntryDate?.value || '');
  if (!form || !recordDate) return dataEntrySetStatus('Select a form and operational date.');
  const rowsById = new Map(Array.from(els.dataEntryFields?.querySelectorAll('.data-entry-field') || []).map((row) => [row.dataset.fieldId, row]));
  const rows = (form.fields || []).map((field) => {
    const input = rowsById.get(field.id)?.querySelector('input');
    const loaded = state.dataEntryLoadedValues?.[field.item] || {};
    return {
      Field: field.label || field.item,
      Item: field.item,
      Value: input?.value ?? '',
      Unit: field.unit || '',
      Timestamp: loaded.timestamp || '',
      Status: state.dataEntryDeletedFields.has(field.id) ? 'Marked for deletion' : ''
    };
  });
  downloadTextFile({ filename: `${form.id || 'data-entry'}-${recordDate}.csv`, mime: 'text/csv;charset=utf-8', text: toCsv(rows, ['Field', 'Item', 'Value', 'Unit', 'Timestamp', 'Status']) });
  dataEntrySetStatus(`Downloaded values for ${recordDate}.`);
}

async function loadDataEntryValues() {
  const form = selectedDataEntryForm(); const recordDate = String(els.dataEntryDate?.value || '');
  if (!form || !recordDate) return dataEntrySetStatus('Select a form and operational date.');
  dataEntrySetStatus('Loading…');
  try {
    const response = await apiPostJson('/api/data-entry/load', { form_id: form.id, record_date: recordDate }, { timeoutMs: 120000 });
    state.dataEntryLoadedValues = response.values || {}; state.dataEntryDeletedFields = new Set(); renderDataEntryFields();
    dataEntrySetStatus(`${Object.keys(state.dataEntryLoadedValues).length} existing value(s) loaded for ${recordDate}.`);
  } catch (err) { dataEntrySetStatus(err.message || err); }
}

async function saveDataEntryValues() {
  const form = selectedDataEntryForm(); const recordDate = String(els.dataEntryDate?.value || '');
  if (!form || !recordDate) return dataEntrySetStatus('Select a form and operational date.');
  const rows = Array.from(els.dataEntryFields?.querySelectorAll('.data-entry-field') || []);
  const changes = [];
  rows.forEach((row) => {
    const field = (form.fields || []).find((item) => item.id === row.dataset.fieldId); const input = row.querySelector('input');
    if (!field || !input) return;
    if (state.dataEntryDeletedFields.has(field.id)) changes.push({ field_id: field.id, action: 'delete' });
    else if (input.value !== input.dataset.original) changes.push({ field_id: field.id, action: 'set', value: input.value });
  });
  if (!changes.length) return dataEntrySetStatus('No changes to save.');
  const deletions = changes.filter((change) => change.action === 'delete').length;
  if (deletions && !window.confirm(`Save ${changes.length - deletions} change(s) and delete ${deletions} value(s) for ${recordDate}?`)) return;
  dataEntrySetStatus('Saving…');
  try {
    const response = await apiPostJson('/api/data-entry/save', { form_id: form.id, record_date: recordDate, changes }, { timeoutMs: 120000 });
    await loadDataEntryValues();
    dataEntrySetStatus(`Saved: ${response.inserted || 0} inserted, ${response.updated || 0} updated, ${response.deleted || 0} deleted.`);
  } catch (err) { dataEntrySetStatus(err.message || err); }
}

function dataEntryColumnOptions(select, columns, value = '', optional = false) {
  if (!select) return; select.textContent = '';
  if (optional) select.add(new Option('None', ''));
  columns.forEach((column) => select.add(new Option(`${column.name} (${column.data_type || ''})`, column.name)));
  select.value = value;
}

function renderDataEntryBuilderFields() {
  if (!els.dataEntryBuilderFields) return; els.dataEntryBuilderFields.textContent = '';
  const target = state.dataEntryTargets.find((item) => item.id === els.dataEntryTarget?.value);
  const sources = new Set((target?.columns || []).map((entry) => entry.source));
  const valueTypes = [];
  if (sources.has('numeric_value')) valueTypes.push(['numeric','Numeric']);
  if (sources.has('text_value')) valueTypes.push(['text','Text']);
  if (!valueTypes.length) valueTypes.push(['numeric','Numeric']);
  state.dataEntryBuilderFields.forEach((field, index) => {
    const tr = document.createElement('tr');
    const add = (type, key, options = null) => { const td = document.createElement('td'); let input;
      if (options) { input = document.createElement('select'); options.forEach(([value, label]) => input.add(new Option(label, value))); }
      else { input = document.createElement('input'); input.type = type; }
      if (type === 'checkbox') input.checked = Boolean(field[key]); else input.value = field[key] ?? '';
      input.addEventListener('change', () => { field[key] = type === 'checkbox' ? input.checked : input.value; }); td.appendChild(input); tr.appendChild(td); };
    add('text', 'label'); add('text', 'item'); add('select', 'value_type', valueTypes); add('text', 'unit'); add('number', 'precision'); add('checkbox', 'required'); add('number', 'min'); add('number', 'max');
    const td = document.createElement('td'); const remove = document.createElement('button'); remove.className = 'btn'; remove.textContent = 'Remove'; remove.addEventListener('click', () => { state.dataEntryBuilderFields.splice(index, 1); renderDataEntryBuilderFields(); }); td.appendChild(remove); tr.appendChild(td);
    els.dataEntryBuilderFields.appendChild(tr);
  });
}

function renderDataEntryInsertValues() {
  if (!els.dataEntryInsertValues) return;
  els.dataEntryInsertValues.textContent = '';
  const table = state.dataEntrySchema.find((item) => item.name === els.dataEntryTable?.value);
  const columns = (table?.columns || []).filter((column) => !String(column.extra || '').toLowerCase().includes('auto_increment') && !String(column.extra || '').toLowerCase().includes('generated'));
  const previous = new Map(state.dataEntryInsertValues.map((entry) => [entry.column, entry]));
  const suggestedSource = (name) => {
    const key = String(name || '').toLowerCase();
    if (key === 'timestamp_ms') return 'record_epoch_ms';
    if (['timestamp', 'datetime', 'date_time', 'record_datetime', 'recorded_at'].includes(key)) return 'record_datetime';
    if (['created_at', 'updated_at', 'save_time', 'modified_at'].includes(key)) return 'save_datetime';
    if (['connection_id', 'database_id', 'source_connection'].includes(key)) return 'database_id';
    if (['tag_name','item_name','point_name'].includes(key)) return 'item_name';
    if (['value','numeric_value','float_value'].includes(key)) return 'numeric_value';
    if (['text_value','alpha_value'].includes(key)) return 'text_value';
    if (key === 'form_id') return 'form_id';
    if (['job_name', 'form_name'].includes(key)) return 'form_name';
    return 'unused';
  };
  state.dataEntryInsertValues = columns
    .map((column) => ({ column: column.name, source: previous.get(column.name)?.source || suggestedSource(column.name), value: previous.get(column.name)?.value ?? '' }));
  columns.forEach((column) => {
    const required = column.required_on_insert === true;
    const entry = state.dataEntryInsertValues.find((item) => item.column === column.name);
    const tr = document.createElement('tr'); tr.className = required ? 'data-entry-required-field' : '';
    const nameCell = document.createElement('td'); nameCell.textContent = column.name;
    const requirementCell = document.createElement('td'); requirementCell.textContent = required ? 'Required' : 'Optional';
    const sourceCell = document.createElement('td'); const source = document.createElement('select');
    [['unused','Not used'],['record_datetime','Operational date and record time'],['record_epoch_ms','Operational timestamp (milliseconds)'],
      ['save_datetime','Current save time'],['database_id','Database connection ID'],['target_name','Target name'],['target_id','Target ID'],
      ['form_name','Form name'],['form_id','Form ID'],['item_name','Item/tag name'],['numeric_value','Entered numeric value'],
      ['text_value','Entered text value'],['record_msec','Millisecond portion'],['fixed','Fixed value']].forEach(([optionValue, label]) => source.add(new Option(label, optionValue)));
    source.value = entry?.source || suggestedSource(column.name); sourceCell.appendChild(source);
    const valueCell = document.createElement('td'); const value = document.createElement('input'); value.type = 'text'; value.value = entry?.value ?? ''; value.disabled = source.value !== 'fixed';
    source.addEventListener('change', () => { const selected = state.dataEntryInsertValues.find((item) => item.column === column.name); if (selected) selected.source = source.value; value.disabled = source.value !== 'fixed'; renderDataEntryRequiredColumns(); });
    value.addEventListener('input', () => { const selected = state.dataEntryInsertValues.find((item) => item.column === column.name); if (selected) selected.value = value.value; });
    valueCell.appendChild(value); tr.append(nameCell, requirementCell, sourceCell, valueCell); els.dataEntryInsertValues.appendChild(tr);
  });
  renderDataEntryRequiredColumns();
}

function renderDataEntryRequiredColumns() {
  if (!els.dataEntryRequiredColumns) return;
  const table = state.dataEntrySchema.find((item) => item.name === els.dataEntryTable?.value);
  const required = (table?.columns || []).filter((column) => column.required_on_insert === true).map((column) => column.name);
  const configured = new Set(state.dataEntryInsertValues.filter((entry) => entry.source !== 'unused').map((entry) => entry.column));
  const missing = required.filter((column) => !configured.has(column));
  els.dataEntryRequiredColumns.style.display = required.length ? '' : 'none';
  els.dataEntryRequiredColumns.classList.toggle('is-complete', missing.length === 0);
  els.dataEntryRequiredColumns.textContent = missing.length
    ? `Required database fields still need a source: ${missing.join(', ')}`
    : `All required database columns are supplied: ${required.join(', ')}`;
}

async function loadDataEntrySchema(selected = {}) {
  const database = String(els.dataEntryDatabase?.value || selected.database_id || ''); if (!database) return;
  if (els.dataEntryTargetStatus) els.dataEntryTargetStatus.textContent = 'Loading database schema…';
  try {
    const response = await apiGet(`/api/data-entry/schema?database=${encodeURIComponent(database)}`, { timeoutMs: 120000 }); state.dataEntrySchema = response.tables || [];
    if (els.dataEntryTable) { els.dataEntryTable.textContent = ''; state.dataEntrySchema.forEach((table) => { if (table.type !== 'VIEW') els.dataEntryTable.add(new Option(table.name, table.name)); }); els.dataEntryTable.value = selected.table || els.dataEntryTable.value; }
    renderDataEntryInsertValues(); if (els.dataEntryTargetStatus) els.dataEntryTargetStatus.textContent = 'Schema loaded.';
  } catch (err) { if (els.dataEntryTargetStatus) els.dataEntryTargetStatus.textContent = String(err.message || err); }
}

async function showDataEntryBuilder(form = null) {
  if (!canAdministerDataEntry()) return;
  if (els.dataEntryBuilder) els.dataEntryBuilder.style.display = '';
  const value = form || {};
  els.dataEntryOriginalId.value = value.id || ''; els.dataEntryName.value = value.name || ''; els.dataEntryDescription.value = value.description || '';
  els.dataEntryAllowDelete.checked = value.allow_delete === true; els.dataEntryHmiEnabled.checked = value.hmi_enabled === true; els.dataEntryRequireLogin.checked = value.require_login !== false;
  els.dataEntryTarget.textContent = ''; state.dataEntryTargets.forEach((target) => els.dataEntryTarget.add(new Option(target.name, target.id))); els.dataEntryTarget.value = value.target_id || els.dataEntryTarget.value;
  state.dataEntryBuilderFields = JSON.parse(JSON.stringify(value.fields || [])); renderDataEntryBuilderFields();
}

function currentDataEntryFormDefinition() {
  return { name: els.dataEntryName.value, description: els.dataEntryDescription.value, target_id: els.dataEntryTarget.value,
    allow_delete: els.dataEntryAllowDelete.checked, hmi_enabled: els.dataEntryHmiEnabled.checked,
    require_login: els.dataEntryRequireLogin.checked, fields: state.dataEntryBuilderFields };
}

async function showDataEntryTargetBuilder(target = null) {
  if (!canAdministerDataEntry()) return;
  els.dataEntryTargetBuilder.style.display = '';
  const value = target || {};
  els.dataEntryTargetOriginalId.value = value.id || ''; els.dataEntryTargetName.value = value.name || ''; els.dataEntryTargetDescription.value = value.description || '';
  els.dataEntryRecordTime.value = value.record_time || '08:00:00'; els.dataEntryAlternateTimes.value = (value.alternate_times || []).join(', ');
  state.dataEntryInsertValues = JSON.parse(JSON.stringify(value.columns || []));
  try {
    const sources = await apiGet('/api/data-entry/sources'); state.dataEntrySources = sources.databases || [];
    els.dataEntryDatabase.textContent = ''; state.dataEntrySources.forEach((database) => els.dataEntryDatabase.add(new Option(database.name, database.id)));
    els.dataEntryDatabase.value = value.database_id || els.dataEntryDatabase.value; await loadDataEntrySchema(value);
  } catch (err) { els.dataEntryTargetStatus.textContent = String(err.message || err); }
}

function currentDataEntryTargetDefinition() {
  const time = String(els.dataEntryRecordTime.value || '08:00:00');
  const table = state.dataEntrySchema.find((item) => item.name === els.dataEntryTable.value);
  const configured = new Set(state.dataEntryInsertValues.filter((entry) => entry.source !== 'unused').map((entry) => entry.column));
  const missing = (table?.columns || []).filter((column) => column.required_on_insert && !configured.has(column.name)).map((column) => column.name);
  if (missing.length) throw new Error(`Required database fields still need a source: ${missing.join(', ')}`);
  return { name: els.dataEntryTargetName.value, description: els.dataEntryTargetDescription.value,
    database_id: els.dataEntryDatabase.value, table: els.dataEntryTable.value, record_time: `${time}${time.length === 5 ? ':00' : ''}`,
    alternate_times: els.dataEntryAlternateTimes.value.split(/[ ,]+/).filter(Boolean), columns: state.dataEntryInsertValues };
}

function refreshDataEntryTargetSelectors() {
  if (els.dataEntryTargetSelect) {
    els.dataEntryTargetSelect.textContent = ''; els.dataEntryTargetSelect.add(new Option('New target', ''));
    state.dataEntryTargets.forEach((target) => els.dataEntryTargetSelect.add(new Option(target.name, target.id)));
  }
}

async function refreshDataEntryForms(loadValues = true) {
  if (canAdministerDataEntry()) {
    const targets = await apiGet('/api/data-entry/targets'); state.dataEntryTargets = targets.targets || []; state.dataEntryTargets.sort((a,b) => a.name.localeCompare(b.name)); refreshDataEntryTargetSelectors();
  }
  const response = await apiGet('/api/data-entry/forms'); state.dataEntryForms = response.forms || [];
  const previous = els.dataEntryFormSelect.value; els.dataEntryFormSelect.textContent = '';
  state.dataEntryForms.sort((a,b) => a.name.localeCompare(b.name)).forEach((form) => els.dataEntryFormSelect.add(new Option(form.name, form.id)));
  if (!state.dataEntryForms.length) els.dataEntryFormSelect.add(new Option('No forms defined', ''));
  els.dataEntryFormSelect.value = state.dataEntryForms.some((form) => form.id === previous) ? previous : (state.dataEntryForms[0]?.id || '');
  els.dataEntryNewBtn.style.display = canAdministerDataEntry() ? '' : 'none'; els.dataEntryEditBtn.style.display = canAdministerDataEntry() && selectedDataEntryForm() ? '' : 'none'; els.dataEntryTargetsBtn.style.display = canAdministerDataEntry() ? '' : 'none';
  renderDataEntryPreviewHeading(); renderDataEntryFields(); if (loadValues && selectedDataEntryForm()) await loadDataEntryValues();
}

function wireDataEntryUi() {
  if (els.dataEntryDate) els.dataEntryDate.value = localIsoDate(new Date());
  els.dataEntryRefreshBtn?.addEventListener('click', () => refreshDataEntryForms()); els.dataEntryFormSelect?.addEventListener('change', () => { renderDataEntryPreviewHeading(); loadDataEntryValues(); });
  els.dataEntryDate?.addEventListener('change', () => loadDataEntryValues()); els.dataEntryLoadBtn?.addEventListener('click', loadDataEntryValues);
  els.dataEntryPreviousBtn?.addEventListener('click', () => moveDataEntryDate(-1)); els.dataEntryNextBtn?.addEventListener('click', () => moveDataEntryDate(1));
  els.dataEntryDownloadBtn?.addEventListener('click', downloadDataEntryValues);
  els.dataEntrySaveValuesBtn?.addEventListener('click', saveDataEntryValues); els.dataEntryRevertBtn?.addEventListener('click', () => { state.dataEntryDeletedFields = new Set(); renderDataEntryFields(); dataEntrySetStatus('Unsaved changes reverted.'); });
  els.dataEntryNewBtn?.addEventListener('click', () => showDataEntryBuilder()); els.dataEntryEditBtn?.addEventListener('click', () => showDataEntryBuilder(selectedDataEntryForm()));
  els.dataEntryTarget?.addEventListener('change', renderDataEntryBuilderFields);
  els.dataEntryTargetsBtn?.addEventListener('click', () => showDataEntryTargetBuilder());
  els.dataEntryTargetSelect?.addEventListener('change', () => showDataEntryTargetBuilder(state.dataEntryTargets.find((target) => target.id === els.dataEntryTargetSelect.value) || null));
  els.dataEntryNewTargetBtn?.addEventListener('click', () => showDataEntryTargetBuilder());
  els.dataEntryDatabase?.addEventListener('change', () => loadDataEntrySchema({})); els.dataEntryTable?.addEventListener('change', () => loadDataEntrySchema({ table: els.dataEntryTable.value }));
  [els.dataEntryTimeColumn, els.dataEntryItemColumn, els.dataEntryNumericColumn, els.dataEntryTextColumn, els.dataEntryMsecColumn]
    .forEach((select) => select?.addEventListener('change', renderDataEntryInsertValues));
  els.dataEntryAddFieldBtn?.addEventListener('click', () => { state.dataEntryBuilderFields.push({ label: '', item: '', value_type: 'numeric', unit: '', precision: 2, required: false, min: '', max: '' }); renderDataEntryBuilderFields(); });
  els.dataEntryCancelBuilderBtn?.addEventListener('click', () => { els.dataEntryBuilder.style.display = 'none'; });
  els.dataEntrySaveFormBtn?.addEventListener('click', async () => { try { dataEntryBuilderSetStatus('Saving…'); await apiPostJson('/api/data-entry/forms', { original_id: els.dataEntryOriginalId.value, form: currentDataEntryFormDefinition() }); els.dataEntryBuilder.style.display = 'none'; await refreshDataEntryForms(false); dataEntrySetStatus('Form saved.'); } catch (err) { dataEntryBuilderSetStatus(err.message || err); } });
  els.dataEntryDeleteFormBtn?.addEventListener('click', async () => { const id = els.dataEntryOriginalId.value; if (!id || !confirm(`Delete data-entry form '${id}'?`)) return; try { await apiPostJson('/api/data-entry/forms/delete', { id }); els.dataEntryBuilder.style.display = 'none'; await refreshDataEntryForms(false); } catch (err) { dataEntryBuilderSetStatus(err.message || err); } });
  els.dataEntryCancelTargetBtn?.addEventListener('click', () => { els.dataEntryTargetBuilder.style.display = 'none'; });
  els.dataEntrySaveTargetBtn?.addEventListener('click', async () => { try { els.dataEntryTargetStatus.textContent = 'Saving…'; await apiPostJson('/api/data-entry/targets', { original_id: els.dataEntryTargetOriginalId.value, target: currentDataEntryTargetDefinition() }); els.dataEntryTargetBuilder.style.display = 'none'; await refreshDataEntryForms(false); dataEntrySetStatus('Data entry target saved.'); } catch (err) { els.dataEntryTargetStatus.textContent = String(err.message || err); } });
  els.dataEntryDeleteTargetBtn?.addEventListener('click', async () => { const id = els.dataEntryTargetOriginalId.value; if (!id || !confirm(`Delete data entry target '${id}'?`)) return; try { await apiPostJson('/api/data-entry/targets/delete', { id }); els.dataEntryTargetBuilder.style.display = 'none'; await refreshDataEntryForms(false); } catch (err) { els.dataEntryTargetStatus.textContent = String(err.message || err); } });
}

function setTab(id) {
  const next = String(id || '').trim();
  if (!next) return;
  if (next === 'alarms') {
    // Alarms page removed (data is still visible elsewhere).
    id = 'overview';
  }
  if (next === 'configure' && !canAccessConfigureTab()) {
    id = 'overview';
  }
  if (next === 'workspace' && !canAccessWorkspaceTab()) {
    id = 'overview';
  }
  if (next === 'alarms_events' && !canAccessAlarmsEventsTab()) {
    id = 'overview';
  }
  if (next === 'logger' && !canAccessLoggerTab()) {
    id = 'overview';
  }
  if (next === 'historian' && !canAccessHistorianTab()) {
    id = 'overview';
  }
  if (next === 'reports' && !canAccessReportsTab() && !REPORTS_PORTAL_MODE) {
    id = 'overview';
  }
  if (next === 'data_entry' && !canAccessDataEntryTab()) id = 'overview';
  if (next === 'logic' && !canAccessLogicTab()) {
    id = 'overview';
  }
  if (next === 'flow' && !canAccessFlowTab()) {
    id = 'overview';
  }
  if ((next === 'logs' || next === 'hmi_audit') && !canAccessLogsTab()) {
    id = 'overview';
  }
  if (next === 'users' && !canAccessUsersTab()) {
    id = 'overview';
  }

  document.querySelectorAll('.tab').forEach((b) => b.classList.toggle('is-active', b.dataset.tab === id));
  document.querySelectorAll('.panel').forEach((p) => p.classList.toggle('is-active', p.id === `tab-${id}`));
  document.body.classList.toggle('reports-active', id === 'reports');
  document.body.classList.toggle('flow-active', id === 'flow');
  document.body.classList.toggle('app-viewport', !REPORTS_PORTAL_MODE || id === 'reports');
  if (id !== 'reports') document.body.classList.remove('reports-builder-active');

  if (id === 'users') {
    refreshUsersPanel().catch(() => {});
    refreshUserAuthLine().catch(() => {});
  }
  if (id === 'logs') {
    refreshLogs().catch(() => {});
  }
  if (id === 'hmi_audit') {
    refreshHmiAudit().catch(() => {});
  }
  if (id === 'logger') {
    refreshReporterAll().catch(() => {});
  }
  if (id === 'historian') {
    refreshHistorianTab().catch(() => {});
  }
  if (id === 'reports') {
    showReportsLanding();
    refreshPublishedReports().catch(() => {});
    refreshReportBuilder().catch(() => {});
  }
  if (id === 'data_entry') refreshDataEntryForms().catch(() => {});
  if (id === 'logic') {
    refreshLogicTab().catch(() => {});
  }
  if (id === 'flow') {
    // Returning to Flow should refresh runtime status without replacing the
    // selected in-browser draft or discarding unsaved edits.
    refreshFlowTab({ preserveDraft: state.flowDrafts.length > 0 }).catch(() => {});
  } else if (state.flowRefreshTimer) {
    window.clearTimeout(state.flowRefreshTimer);
    state.flowRefreshTimer = 0;
  }
  if (id === 'configure') {
    ensureAuthAdminPanelLoaded();
    loadSoundSettings().catch(() => {});
    loadSmtpSettings().catch(() => {});
    loadVoiceModemSettings().catch(() => {});
    refreshServerCertificateLibrary().catch(() => {});
  }
  if (id === 'alarms_events') {
    loadAlarmNotificationSettings().catch(() => {});
    renderAlarmsSchemaStatus(state.alarmsStatusLast);
    renderAlarmsEventsTree();
    refreshTagEventsHistory().catch(() => {});
  }
  if (id === 'workspace') {
    if (workspaceIsDirty()) {
      // The current Workspace state is the authoritative editing copy until
      // Save, Save & Apply, or Discard is chosen.
      renderWorkspaceTree();
    } else {
      refreshWorkspaceTab().catch((err) => {
        if (els.statusLine) els.statusLine.textContent = `Workspace refresh failed: ${err.message}`;
      });
    }
  }
  if (state.uiRefreshReady && (id === 'overview' || id === 'workspace' || id === 'alarms_events')) {
    refreshVisible().catch(() => {});
  }
  if (id !== 'logic') {
    renderLogicValidationStatus(null);
  }
}

els.tabs?.addEventListener('click', (e) => {
  const btn = e.target.closest('.tab');
  if (!btn) return;
  if (!btn.dataset.tab) return; // ignore non-tab links in the header
  setTab(btn.dataset.tab);
});

function classForStatus(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'ok') return 'status-ok';
  if (s === 'degraded' || s === 'warn' || s === 'warning') return 'status-degraded';
  return 'status-error';
}

function renderOverviewHealth(health, metrics = null) {
  if (!health) return;

  const overall = String(health?.status || 'error');
  const cached = Boolean(health?.ui_cached);
  const formatMsCompact = (value) => {
    const ms = Number(value);
    if (!Number.isFinite(ms) || ms < 0) return '';
    if (ms >= 10000) return `${(ms / 1000).toFixed(1)} s`;
    if (ms >= 1000) return `${(ms / 1000).toFixed(2)} s`;
    return `${Math.round(ms)} ms`;
  };
  if (els.overviewHealthOverall) {
    els.overviewHealthOverall.textContent = `Status: ${overall.toUpperCase()}${cached ? ' (cached)' : ''}`;
    els.overviewHealthOverall.className = classForStatus(overall);
  }
  if (els.overviewHealthWatchdog) {
    const watchdog = (health?.watchdog && typeof health.watchdog === 'object') ? health.watchdog : null;
    if (!watchdog) {
      els.overviewHealthWatchdog.textContent = '';
      els.overviewHealthWatchdog.className = 'small';
    } else {
      const wdStatus = String(watchdog?.status || 'unknown');
      const lastReadAgeMs = (typeof watchdog?.runtime_last_read_age_ms === 'number' && watchdog.runtime_last_read_age_ms >= 0)
        ? watchdog.runtime_last_read_age_ms
        : null;
      const stalledCount = Math.max(0, Number(watchdog?.connections_stalled || 0) || 0);
      const wsState = watchdog?.ws_enabled ? 'ws on' : 'ws off';
      const reason = watchdog?.reason ? ` • ${watchdog.reason}` : '';
      const lastRead = lastReadAgeMs != null ? ` • last read ${formatMsCompact(lastReadAgeMs)} ago` : '';
      const stalled = ` • stalled ${stalledCount}`;
      els.overviewHealthWatchdog.textContent = `Watchdog: ${wdStatus.toUpperCase()} • ${wsState}${lastRead}${stalled}${reason}`;
      els.overviewHealthWatchdog.className = `small ${classForStatus(wdStatus)}`;
    }
  }

  const counts = health?.counts || {};
  const ok = Number(counts?.ok ?? 0) || 0;
  const degraded = Number(counts?.degraded ?? 0) || 0;
  const err = Number(counts?.error ?? 0) || 0;

  const conns = health?.connections && typeof health.connections === 'object' ? health.connections : {};
  const connCount = Object.keys(conns).length;

  if (els.overviewHealthMeta) {
    const cacheText = cached
      ? ` | cached ${Math.round(Number(health.ui_cache_age_ms || 0) / 1000)}s after ${health.ui_fetch_error || 'health fetch failed'}`
      : '';
    els.overviewHealthMeta.textContent = `Connections: ${connCount} | OK: ${ok} | Degraded: ${degraded} | Error: ${err}${cacheText}`;
  }

  if (els.overviewHealthConnections) {
    const lines = [];
    const metricConns = metrics?.connections && typeof metrics.connections === 'object' ? metrics.connections : {};
    Object.entries(conns).forEach(([cid, info]) => {
      const connectionName = displayConnectionName(cid);
      const st = String(info?.status || 'unknown');
      const metricInfo = metricConns[cid] && typeof metricConns[cid] === 'object' ? metricConns[cid] : {};
      const reason = info?.reason ? (` - ${info.reason}`) : '';
      const ratio = (typeof info?.stale_ratio === 'number') ? ` (${Math.round(info.stale_ratio * 100)}% stale/bad)` : '';
      const seen = (typeof info?.tags_seen === 'number') ? info.tags_seen : null;
      const good = (typeof info?.good_recent === 'number') ? info.good_recent : null;
      const age = (typeof info?.newest_age_ms === 'number') ? info.newest_age_ms : null;
      const readMsAvg = (typeof info?.read_ms_avg === 'number' && info.read_ms_avg > 0) ? info.read_ms_avg : null;
      const sweepMs = (typeof info?.expected_sweep_ms === 'number' && info.expected_sweep_ms >= 0) ? info.expected_sweep_ms : null;
      const sweepLastMs = (typeof info?.sweep_ms_last === 'number' && info.sweep_ms_last > 0) ? info.sweep_ms_last : null;
      const sweepAvg10sMs = (typeof info?.sweep_ms_avg_10s === 'number' && info.sweep_ms_avg_10s > 0) ? info.sweep_ms_avg_10s : null;
      const sweepAvg60sMs = (typeof info?.sweep_ms_avg_60s === 'number' && info.sweep_ms_avg_60s > 0) ? info.sweep_ms_avg_60s : null;
      const lanes = (typeof info?.poll_lanes === 'number' && info.poll_lanes > 0) ? info.poll_lanes : null;
      const lastOkAgeMs = (typeof info?.last_ok_age_ms === 'number' && info.last_ok_age_ms >= 0) ? info.last_ok_age_ms : null;

      let details = '';
      if (seen != null && good != null) details += ` • ${good}/${seen} good recent`;
      if (age != null) details += ` • newest ${age} ms`;
      if (readMsAvg != null) details += ` • read ${formatMsCompact(readMsAvg)} avg`;
      if (sweepAvg10sMs != null) details += ` • sweep ${formatMsCompact(sweepAvg10sMs)} avg10s`;
      else if (sweepLastMs != null) details += ` • sweep ${formatMsCompact(sweepLastMs)} last`;
      if (sweepMs != null) details += ` • est ${formatMsCompact(sweepMs)}`;
      if (sweepAvg60sMs != null && sweepAvg10sMs != null) details += ` • avg60s ${formatMsCompact(sweepAvg60sMs)}`;
      if (lanes != null) details += ` • lanes ${lanes}`;
      if (typeof info?.last_read_age_ms === 'number' && info.last_read_age_ms >= 0) details += ` • last read ${formatMsCompact(info.last_read_age_ms)} ago`;
      if (lastOkAgeMs != null) details += ` • last ok ${formatMsCompact(lastOkAgeMs)} ago`;
      if (info?.stalled === true) details += ` • stalled`;

      const cls = classForStatus(st);
      const blocks = Array.isArray(metricInfo?.blocks) ? metricInfo.blocks : [];
      let blockHtml = '';
      if (blocks.length) {
        const rows = blocks.map((block) => {
          const name = escapeHtml(String(block?.logical_name || ''));
          const addressCell = formatOverviewBlockAddress(cid, block);
          const datatype = escapeHtml(String(block?.datatype || ''));
          const elemCount = Math.max(1, Number(block?.elem_count || 1) || 1);
          const mapped = Math.max(1, Number(block?.mapped_tag_count || elemCount) || elemCount);
          const readAvg = (typeof block?.read_ms_avg === 'number' && block.read_ms_avg > 0) ? formatMsCompact(block.read_ms_avg) : '-';
          const readLast = (typeof block?.read_ms_last === 'number' && block.read_ms_last > 0) ? formatMsCompact(block.read_ms_last) : '-';
          const okAge = (typeof block?.last_ok_age_ms === 'number' && block.last_ok_age_ms >= 0) ? `${formatMsCompact(block.last_ok_age_ms)} ago` : '-';
          const readsOk = Math.max(0, Number(block?.reads_ok || 0) || 0);
          const readsErr = Math.max(0, Number(block?.reads_err || 0) || 0);
          const statusText = String(block?.last_status_text || '').trim();
          const statusCode = Number.isFinite(Number(block?.last_status)) ? String(block.last_status) : '';
          const lastStatus = statusText ? `${escapeHtml(statusText)}${statusCode ? ` (${escapeHtml(statusCode)})` : ''}` : '-';
          return `<tr><td><code>${name}</code></td><td>${addressCell}</td><td>${datatype}${elemCount > 1 ? ` [${elemCount}]` : ''}</td><td>${mapped}</td><td>${readAvg}</td><td>${readLast}</td><td>${okAge}</td><td>${readsOk}</td><td>${readsErr}</td><td>${lastStatus}</td></tr>`;
        }).join('');
        const isExpanded = state.overviewHealthExpanded.has(cid);
        blockHtml = `<details class="details overview-health-blocks" data-conn-id="${escapeHtml(cid)}" style="margin:6px 0 0 16px;"${isExpanded ? ' open' : ''}><summary class="small">Block reads (${blocks.length})</summary><div class="small" style="overflow:auto; margin-top:6px;"><table class="table mono" style="width:100%;"><thead><tr><th>Root Tag</th><th>Address</th><th>Type</th><th>Mapped</th><th>Avg</th><th>Last</th><th>Last OK</th><th>OK Count</th><th>Err Count</th><th>Last Status</th></tr></thead><tbody>${rows}</tbody></table></div></details>`;
      }
      lines.push(`<div class="${cls}">${escapeHtml(connectionName)}: ${st.toUpperCase()}${reason}${ratio}${details}${blockHtml}</div>`);
    });

    els.overviewHealthConnections.innerHTML = lines.join('');
    els.overviewHealthConnections.querySelectorAll('.overview-health-blocks').forEach((detailEl) => {
      detailEl.addEventListener('toggle', () => {
        const cid = String(detailEl.dataset.connId || '');
        if (!cid) return;
        if (detailEl.open) state.overviewHealthExpanded.add(cid);
        else state.overviewHealthExpanded.delete(cid);
      });
    });
  }
}

function badge(status) {
  const s = String(status || '').toLowerCase();
  const cls = s === 'ok' ? 'ok' : s === 'degraded' ? 'warn' : 'bad';
  return `<span class="badge ${cls}">${s || '-'}</span>`;
}

if (els.workspaceChildrenFilterInput) {
  els.workspaceChildrenFilterInput.addEventListener('input', () => {
    state.workspaceChildrenFilter = String(els.workspaceChildrenFilterInput.value || '').trim();
    state.workspaceChildrenSel = new Set();
    state.workspaceChildrenLastIndex = -1;
    renderWorkspaceTree();
  });
}

async function fetchWithTimeout(url, init = {}, timeoutMs = 30000) {
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { credentials: 'same-origin', ...init, signal: controller.signal });
  } catch (err) {
    if (err?.name === 'AbortError') {
      throw new Error(`Request timed out after ${Math.round(timeoutMs / 1000)} seconds`);
    }
    throw err;
  } finally {
    window.clearTimeout(timer);
  }
}

function serviceUnavailableMessage(url, detail = '') {
  const path = String(url || '');
  if (path.startsWith('/api/historian/')) return `historian service is unavailable${detail}`;
  if (path.startsWith('/api/logger/') || path.startsWith('/api/logger/')) return `logger service is unavailable${detail}`;
  if (path.startsWith('/api/alarms/')) return `alarm service is unavailable${detail}`;
  if (path.startsWith('/api/opcbridge/')) return `OPCBridge request failed${detail}`;
  return `service is unavailable${detail}`;
}

async function apiGet(url, { timeoutMs = 30000 } = {}) {
  const res = await fetchWithTimeout(url, { cache: 'no-store', credentials: 'same-origin', headers: { Accept: 'application/json' } }, timeoutMs);
  if (!res.ok) {
    if (res.status === 401 || res.status === 403) {
      refreshUserAuthLine().catch(() => {});
      if (state.opcbridgeAuthStatus?.configured) {
        setWorkspaceSaveStatus('Login required. Press Login.');
      }
    }
    let detail = '';
    try {
      const body = await res.json();
      detail = body?.error ? `: ${body.error}` : '';
    } catch {
      // ignore
    }
    throw new Error(res.status === 502 ? serviceUnavailableMessage(url, detail) : `HTTP ${res.status}${detail}`);
  }
  return res.json();
}

async function loadOpcbridgeHealth({ allowCached = true } = {}) {
  try {
    const health = await apiGet('/api/opcbridge/health');
    state.healthLast = health;
    state.healthLastOkAtMs = Date.now();
    state.healthLastFetchError = '';
    return health;
  } catch (err) {
    state.healthLastFetchError = String(err?.message || err || '');
    const ageMs = Date.now() - Number(state.healthLastOkAtMs || 0);
    if (allowCached && state.healthLast && ageMs >= 0 && ageMs <= 30000) {
      const cached = { ...state.healthLast };
      cached.ui_cached = true;
      cached.ui_cache_age_ms = ageMs;
      cached.ui_fetch_error = state.healthLastFetchError;
      return cached;
    }
    throw err;
  }
}

async function loadOpcbridgeMetrics({ allowCached = true } = {}) {
  try {
    const metrics = await apiGet('/api/opcbridge/metrics');
    state.metricsLast = metrics;
    state.metricsLastOkAtMs = Date.now();
    state.metricsLastFetchError = '';
    return metrics;
  } catch (err) {
    state.metricsLastFetchError = String(err?.message || err || '');
    const ageMs = Date.now() - Number(state.metricsLastOkAtMs || 0);
    if (allowCached && state.metricsLast && ageMs >= 0 && ageMs <= 30000) {
      const cached = { ...state.metricsLast };
      cached.ui_cached = true;
      cached.ui_cache_age_ms = ageMs;
      cached.ui_fetch_error = state.metricsLastFetchError;
      return cached;
    }
    throw err;
  }
}

async function apiGetText(url, { timeoutMs = 30000 } = {}) {
  const res = await fetchWithTimeout(url, { cache: 'no-store', credentials: 'same-origin' }, timeoutMs);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.text();
}

async function apiPostJson(url, bodyObj, { timeoutMs = 120000 } = {}) {
  const res = await fetchWithTimeout(url, {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify(bodyObj || {})
  }, timeoutMs);
  const text = await res.text();
  let parsed = null;
  try { parsed = JSON.parse(text); } catch { parsed = { ok: false, error: text || `HTTP ${res.status}` }; }
  if (!res.ok) {
    if (res.status === 401 || res.status === 403) {
      refreshUserAuthLine().catch(() => {});
      if (state.opcbridgeAuthStatus?.configured) {
        setWorkspaceSaveStatus('Login required. Press Login.');
      }
    }
    const msg = parsed?.error || `HTTP ${res.status}`;
    const err = new Error(msg);
    err.status = res.status;
    err.response = parsed;
    throw err;
  }
  return parsed;
}

async function apiJson(url, { method, bodyObj, timeoutMs } = {}) {
  const m = String(method || 'GET').toUpperCase();
  const init = { method: m, credentials: 'same-origin', headers: { Accept: 'application/json' } };
  if (m !== 'GET' && m !== 'HEAD') {
    init.headers['Content-Type'] = 'application/json';
    init.body = JSON.stringify(bodyObj || {});
  }
  const res = await fetchWithTimeout(url, init, timeoutMs || (m === 'GET' || m === 'HEAD' ? 30000 : 120000));
  const text = await res.text();
  let parsed = null;
  try { parsed = JSON.parse(text); } catch { parsed = { ok: false, error: text || `HTTP ${res.status}` }; }
  if (!res.ok) {
    if (res.status === 401 || res.status === 403) {
      refreshUserAuthLine().catch(() => {});
      if (state.opcbridgeAuthStatus?.configured) {
        setWorkspaceSaveStatus('Login required. Press Login.');
      }
    }
    const msg = parsed?.error || `HTTP ${res.status}`;
    const err = new Error(msg);
    err.status = res.status;
    err.response = parsed;
    throw err;
  }
  return parsed;
}

async function copyTextToClipboardSafe(text) {
  const value = String(text || '');
  if (!value) return;
  if (navigator?.clipboard?.writeText) {
    await navigator.clipboard.writeText(value);
    return;
  }

  const ta = document.createElement('textarea');
  ta.value = value;
  ta.setAttribute('readonly', 'readonly');
  ta.style.position = 'fixed';
  ta.style.left = '-9999px';
  ta.style.top = '0';
  document.body.appendChild(ta);
  ta.focus();
  ta.select();
  let ok = false;
  try { ok = document.execCommand('copy'); } catch { ok = false; }
  document.body.removeChild(ta);
  if (!ok) throw new Error('Clipboard API unavailable');
}

async function opcbridgeReload() {
  const r = await apiPostJson('/api/opcbridge/reload', {});
  if (r && r.pending) {
    const gen = (typeof r.gen === 'number') ? r.gen : null;
    await waitForOpcbridgeReloadDone({ gen });
  }
}

async function opcbridgeReloadConnection(connectionId) {
  const cid = String(connectionId || '').trim();
  if (!cid) return null;
  const r = await apiPostJson('/api/opcbridge/reload/connection', { connection_id: cid });
  if (r && r.pending) {
    const gen = (typeof r.gen === 'number') ? r.gen : null;
    const done = await waitForOpcbridgeReloadDone({ gen });
    return done && typeof done === 'object' ? done : r;
  }
  return r;
}

async function opcbridgeReloadConnections(connectionIds) {
  const ids = Array.from(new Set((Array.isArray(connectionIds) ? connectionIds : [])
    .map((v) => String(v || '').trim())
    .filter(Boolean))).sort();
  const results = [];
  for (const cid of ids) {
    const result = await opcbridgeReloadConnection(cid);
    if (result) results.push(result);
  }
  return { ids, results };
}

function summarizeOpcuaSyncResults(results) {
  const rows = Array.isArray(results) ? results : [];
  const total = { added: 0, updated: 0, retired: 0, datatype_conflicts: 0, add_failures: 0 };
  let attempted = false;
  let fullRebuild = false;
  let failed = false;
  rows.forEach((r) => {
    const sync = r?.opcua_sync || {};
    attempted = attempted || Boolean(sync.attempted);
    fullRebuild = fullRebuild || Boolean(sync.full_rebuild_required || r?.full_rebuild_required);
    failed = failed || sync.ok === false;
    total.added += Math.max(0, Math.trunc(Number(sync.added) || 0));
    total.updated += Math.max(0, Math.trunc(Number(sync.updated) || 0));
    total.retired += Math.max(0, Math.trunc(Number(sync.retired) || 0));
    total.datatype_conflicts += Math.max(0, Math.trunc(Number(sync.datatype_conflicts) || 0));
    total.add_failures += Math.max(0, Math.trunc(Number(sync.add_failures) || 0));
  });
  const bits = [];
  if (total.added) bits.push(`${total.added} OPC UA node${total.added === 1 ? '' : 's'} added`);
  if (total.updated) bits.push(`${total.updated} updated`);
  if (total.retired) bits.push(`${total.retired} retired`);
  if (total.datatype_conflicts) bits.push(`${total.datatype_conflicts} datatype conflict${total.datatype_conflicts === 1 ? '' : 's'}`);
  if (total.add_failures) bits.push(`${total.add_failures} add failure${total.add_failures === 1 ? '' : 's'}`);
  if (!attempted) return fullRebuild ? 'Saved. Polling applied; OPC UA rebuild required.' : 'Saved. Polling changes applied.';
  if (failed) return `Saved. Polling applied; OPC UA sync had errors${bits.length ? ` (${bits.join(', ')})` : ''}.`;
  if (fullRebuild) return `Saved. OPC UA synced; full rebuild recommended${bits.length ? ` (${bits.join(', ')})` : ''}.`;
  return `Saved. Polling and OPC UA synced${bits.length ? ` (${bits.join(', ')})` : ''}.`;
}

function renderRuntimeRebuildStatus(status) {
  const st = status && typeof status === 'object' ? status : {};
  const required = Boolean(status?.full_rebuild_required);
  const requested = Boolean(st.requested);
  const inProgress = Boolean(st.in_progress);
  const done = Boolean(st.done);
  const ok = Boolean(st.ok);
  const target = String(st.target_connection_id || '').trim();
  const targetName = target ? displayConnectionName(target) : '';
  const gen = Number.isFinite(Number(st.gen)) ? Number(st.gen) : 0;
  const sync = st.opcua_sync && typeof st.opcua_sync === 'object' ? st.opcua_sync : {};
  const syncAttempted = Boolean(sync.attempted);
  const syncOk = syncAttempted ? sync.ok !== false : true;

  let label = required ? 'Full rebuild required.' : 'Full runtime is current.';
  let cls = required ? 'status-degraded' : 'status-ok';
  if (requested && !inProgress) {
    label = target ? `Connection reload queued: ${targetName}` : 'Full runtime rebuild queued.';
    cls = 'status-degraded';
  } else if (inProgress) {
    label = target ? `Connection reload running: ${targetName}` : 'Full runtime rebuild running.';
    cls = 'status-degraded';
  } else if (done && !ok) {
    label = 'Last rebuild/reload failed.';
    cls = 'status-error';
  } else if (required) {
    cls = 'status-degraded';
  }

  if (els.overviewRebuildStatus) {
    els.overviewRebuildStatus.textContent = label;
    els.overviewRebuildStatus.className = cls;
  }
  if (els.overviewRebuildHint) {
    if (inProgress || requested) {
      els.overviewRebuildHint.textContent = 'SCADA will keep polling this status while OPCBridge applies the runtime change.';
    } else if (required) {
      els.overviewRebuildHint.textContent = 'Press Rebuild Full Runtime to refresh OPC UA nodes and rebuild all runtime bindings.';
    } else {
      els.overviewRebuildHint.textContent = 'Connection-level polling changes can apply without a full OPC UA rebuild unless structural OPC UA cleanup is required.';
    }
  }
  if (els.overviewRebuildDetails) {
    const rows = [];
    rows.push(`Generation: ${gen || '-'}`);
    rows.push(`Scope: ${target ? `connection ${targetName}` : 'full runtime'}`);
    rows.push(`Requested: ${requested ? 'yes' : 'no'} | Running: ${inProgress ? 'yes' : 'no'} | Done: ${done ? 'yes' : 'no'} | OK: ${done ? (ok ? 'yes' : 'no') : '-'}`);
    if (syncAttempted) {
      const bits = [];
      bits.push(`OPC UA sync: ${syncOk ? 'ok' : 'error'}`);
      bits.push(`added ${Number(sync.added || 0)}`);
      bits.push(`updated ${Number(sync.updated || 0)}`);
      bits.push(`retired ${Number(sync.retired || 0)}`);
      if (Number(sync.datatype_conflicts || 0)) bits.push(`datatype conflicts ${Number(sync.datatype_conflicts || 0)}`);
      if (Number(sync.add_failures || 0)) bits.push(`add failures ${Number(sync.add_failures || 0)}`);
      rows.push(bits.join(' | '));
    } else {
      rows.push('OPC UA sync: not attempted');
    }
    if (st.error) rows.push(`Error: ${String(st.error)}`);
    if (sync.message) rows.push(`Message: ${String(sync.message)}`);
    els.overviewRebuildDetails.innerHTML = rows.map((r) => `<div>${escapeHtml(r)}</div>`).join('');
  }
  if (els.overviewRebuildBtn) {
    els.overviewRebuildBtn.disabled = !canEditConfig() || requested || inProgress;
  }
}

function wireOverviewRuntimeUi() {
  if (els.overviewRebuildBtn && els.overviewRebuildBtn.dataset.wired !== '1') {
    els.overviewRebuildBtn.dataset.wired = '1';
    els.overviewRebuildBtn.addEventListener('click', async () => {
      if (!canEditConfig()) {
        openLoginModal();
        return;
      }
      if (!window.confirm('Rebuild the full OPCBridge runtime? This pauses all pollers and rebuilds OPC UA nodes.')) return;
      try {
        els.overviewRebuildBtn.disabled = true;
        if (els.overviewRebuildStatus) {
          els.overviewRebuildStatus.textContent = 'Rebuilding full runtime…';
          els.overviewRebuildStatus.className = 'status-degraded';
        }
        await opcbridgeReload();
        await refreshAll();
      } catch (err) {
        if (els.overviewRebuildStatus) {
          els.overviewRebuildStatus.textContent = `Rebuild failed: ${err.message}`;
          els.overviewRebuildStatus.className = 'status-error';
        }
      }
    });
  }
  const refreshBtns = [els.alarmRuntimeRefreshBtn, els.alarmsEventsRuntimeRefreshBtn].filter(Boolean);
  refreshBtns.forEach((btn) => {
    if (btn.dataset.wired === '1') return;
    btn.dataset.wired = '1';
    btn.addEventListener('click', () => { refreshAlarmsRuntimeViews().catch(() => {}); });
  });
  const restartBtns = [els.alarmRuntimeRestartBtn, els.alarmsEventsRuntimeRestartBtn].filter(Boolean);
  restartBtns.forEach((btn) => {
    if (btn.dataset.wired === '1') return;
    btn.dataset.wired = '1';
    btn.addEventListener('click', restartAlarmRuntimeService);
  });
  if (els.alarmActivityRefreshBtn && els.alarmActivityRefreshBtn.dataset.wired !== '1') {
    els.alarmActivityRefreshBtn.dataset.wired = '1';
    els.alarmActivityRefreshBtn.addEventListener('click', () => { refreshAlarmsRuntimeViews().catch(() => {}); });
  }
  if (els.alarmEventsDownloadCsvBtn && els.alarmEventsDownloadCsvBtn.dataset.wired !== '1') {
    els.alarmEventsDownloadCsvBtn.dataset.wired = '1';
    els.alarmEventsDownloadCsvBtn.addEventListener('click', () => {
      downloadAlarmEventsHistoryCsv().catch((err) => {
        if (els.alarmEventsStatus) els.alarmEventsStatus.textContent = `CSV download failed: ${err.message}`;
      });
    });
  }
  if (els.tagEventsRefreshBtn && els.tagEventsRefreshBtn.dataset.wired !== '1') {
    els.tagEventsRefreshBtn.dataset.wired = '1';
    els.tagEventsRefreshBtn.addEventListener('click', () => {
      refreshTagEventsHistory().catch((err) => {
        if (els.tagEventsStatus) els.tagEventsStatus.textContent = `Refresh failed: ${err.message}`;
      });
    });
  }
  if (els.tagEventsDownloadCsvBtn && els.tagEventsDownloadCsvBtn.dataset.wired !== '1') {
    els.tagEventsDownloadCsvBtn.dataset.wired = '1';
    els.tagEventsDownloadCsvBtn.addEventListener('click', downloadTagEventsHistoryCsv);
  }
  (els.tagEventsPresetBtns || []).forEach((btn) => {
    if (btn.dataset.wired === '1') return;
    btn.dataset.wired = '1';
    btn.addEventListener('click', () => {
      applyTagEventsPreset(btn.dataset.range || '');
      refreshTagEventsHistory().catch((err) => {
        if (els.tagEventsStatus) els.tagEventsStatus.textContent = `Refresh failed: ${err.message}`;
      });
    });
  });
}

async function waitForOpcbridgeReloadDone({ gen, maxWaitMs = 180000, intervalMs = 750 } = {}) {
  const start = Date.now();
  while ((Date.now() - start) < maxWaitMs) {
    try {
      const s = await apiGet('/api/opcbridge/reload/status');
      renderRuntimeRebuildStatus(s);
      const sGen = (typeof s?.gen === 'number') ? s.gen : 0;
      if (typeof gen === 'number' && sGen < gen) {
        // Still reporting an older reload; keep polling.
      } else if (s && s.done) {
        if (s.ok) return s;
        throw new Error(String(s.error || 'Reload failed'));
      }
    } catch (err) {
      // If the status endpoint is temporarily unavailable during reload, keep waiting.
      const msg = String(err?.message || err || '');
      if (msg.toLowerCase().includes('blocked path')) throw err;
    }
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
  return false;
}

function stripJsonComments(text) {
  const s = String(text || '');
  const noBlock = s.replace(/\/\*[\s\S]*?\*\//g, '');
  return noBlock.replace(/(^|[^:])\/\/.*$/gm, '$1');
}

function parseJsonc(text) {
  return JSON.parse(stripJsonComments(text));
}

function prettyJson(obj) {
  return JSON.stringify(obj, null, 2) + '\n';
}

function csvEscape(value) {
  const s = value == null ? '' : String(value);
  // RFC4180-ish: quote if contains comma, quote, or newline. Double quotes inside quoted fields.
  if (!/[,"\r\n]/.test(s)) return s;
  return `"${s.replace(/"/g, '""')}"`;
}

function toCsv(rows, headers) {
  const hdr = Array.isArray(headers) ? headers : [];
  const lines = [];
  if (hdr.length) lines.push(hdr.map(csvEscape).join(','));
  (rows || []).forEach((row) => {
    lines.push(hdr.map((h) => csvEscape(row?.[h])).join(','));
  });
  return `${lines.join('\n')}\n`;
}

function downloadTextFile({ filename, mime, text }) {
  const blob = new Blob([text], { type: mime || 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename || 'download.txt';
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 250);
}

function isDeleteAction(value) {
  const raw = String(value ?? '').trim().toLowerCase();
  return raw === 'delete';
}

async function downloadConnectivityCsv() {
  const connItems = state.connFiles.slice().sort((a, b) => String(a?.path || '').localeCompare(String(b?.path || '')));
  const objs = await Promise.all(connItems.map(async (f) => {
    const rel = String(f?.path || '').trim();
    if (!rel) return null;
    try {
      const obj = await getConnObjForPath(rel);
      return { rel, obj };
    } catch {
      return { rel, obj: null };
    }
  }));

  const headers = [
    'connection_name',
    'driver',
    'driver_label',
    'gateway',
    'path',
    'slot',
    'plc_type',
    'plc_type_label',
    'polling_mode',
    'polling_pacing',
    'poll_batch_size',
    'poll_time_budget_ms',
    'action'
  ];

  const rows = objs.filter(Boolean).map(({ obj }) => {
    const driver = String(obj?.driver || '').trim();
    const plcType = String(obj?.plc_type || obj?.plcType || '').trim();
    const pollingMode = normalizePollingMode(obj?.polling_mode);
    const pollingPacing = normalizePollingPacing(obj?.polling_pacing);
    const pollBatchSize = Number(obj?.poll_batch_size);
    const pollTimeBudgetMs = Number(obj?.poll_time_budget_ms);
    return {
      connection_name: String(obj?.description || '').trim(),
      driver,
      driver_label: labelForDriver(driver),
      gateway: String(obj?.gateway || '').trim(),
      path: String(obj?.path || '').trim(),
      slot: (obj?.slot == null) ? '' : String(obj.slot),
      plc_type: plcType,
      plc_type_label: labelForPlcType(plcType),
      polling_mode: pollingMode,
      polling_pacing: pollingPacing,
      poll_batch_size: Number.isFinite(pollBatchSize) && pollBatchSize > 0 ? String(Math.trunc(pollBatchSize)) : '',
      poll_time_budget_ms: Number.isFinite(pollTimeBudgetMs) && pollTimeBudgetMs > 0 ? String(Math.trunc(pollTimeBudgetMs)) : '',
      action: ''
    };
  });

  downloadTextFile({
    filename: 'opcbridge-devices.csv',
    mime: 'text/csv',
    text: toCsv(rows, headers)
  });
}

function firstPresentTagValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}

function getTagScalingCsvFields(tag) {
  const t = tag && typeof tag === 'object' ? tag : {};
  const nested = (t.scale && typeof t.scale === 'object') ? t.scale
    : ((t.scaling_config && typeof t.scaling_config === 'object') ? t.scaling_config
      : ((t.scaling && typeof t.scaling === 'object') ? t.scaling : {}));
  const modeRaw = firstPresentTagValue(
    typeof t.scaling === 'string' ? t.scaling : '',
    nested.mode,
    nested.type,
    nested.scaling
  );
  return {
    scaling: String(modeRaw || '').trim(),
    raw_low: firstPresentTagValue(t.raw_low, t.rawLow, nested.raw_low, nested.rawLow, nested.input_low, nested.inputLow),
    raw_high: firstPresentTagValue(t.raw_high, t.rawHigh, nested.raw_high, nested.rawHigh, nested.input_high, nested.inputHigh),
    scaled_low: firstPresentTagValue(t.scaled_low, t.scaledLow, nested.scaled_low, nested.scaledLow, nested.output_low, nested.outputLow),
    scaled_high: firstPresentTagValue(t.scaled_high, t.scaledHigh, nested.scaled_high, nested.scaledHigh, nested.output_high, nested.outputHigh),
    clamp_low: firstPresentTagValue(t.clamp_low, t.clampLow, nested.clamp_low, nested.clampLow),
    clamp_high: firstPresentTagValue(t.clamp_high, t.clampHigh, nested.clamp_high, nested.clampHigh),
    scaled_datatype: firstPresentTagValue(t.scaled_datatype, t.scaledDatatype, nested.scaled_datatype, nested.scaledDatatype, nested.datatype)
  };
}

function downloadDeviceTagsCsv(connectionId) {
  const cid = String(connectionId || '').trim();
  if (!cid) return;

  const tags = getEffectiveTagsAll()
    .filter((t) => String(t?.connection_id || '') === cid)
    .slice()
    .sort((a, b) => String(a?.name || '').localeCompare(String(b?.name || '')));

	  const headers = [
	    'name',
	    'source',
	    'plc_tag_name',
	    'register_type',
	    'address',
	    'offset',
	    'source_tag',
	    'bit',
	    'initial_value',
	    'invert',
	    'datatype',
	    'elem_count',
	    'scan_ms',
	    'enabled',
	    'writable',
	    'scaling',
	    'raw_low',
	    'raw_high',
	    'scaled_low',
	    'scaled_high',
	    'clamp_low',
	    'clamp_high',
	    'scaled_datatype',
	    'log_event_on_change',
	    'log_periodic_mode',
	    'log_periodic_interval_sec',
	    'historian_enabled',
	    'historian_mode',
	    'historian_interval_sec',
	    'action'
	  ];

	  const rows = tags.map((t) => {
	    const historian = normalizeTagHistorianSettings(t);
	    const scaling = getTagScalingCsvFields(t);
	    const sourceTag = String(t?.source_tag || '').trim();
	    const rawRegisterType = String(firstPresentTagValue(t?.register_type, t?.modbus_type, t?.register) ?? '').trim();
	    const rawAddress = firstPresentTagValue(t?.address, t?.modbus_address);
	    const rawOffset = firstPresentTagValue(t?.offset, t?.modbus_offset);
	    const hasModbusFields = rawRegisterType !== '' ||
	      (rawAddress != null && String(rawAddress).trim() !== '') ||
	      (rawOffset != null && String(rawOffset).trim() !== '');
	    return {
	      // Derived tags: source_tag is set (bit optional) and no plc_tag_name
	      // Direct tags: plc_tag_name and no source_tag/bit
	      name: String(t?.name || '').trim(),
	      source: String(t?.source || t?.source_type || '').trim(),
	      plc_tag_name: (sourceTag !== '') ? '' : String(t?.plc_tag_name || '').trim(),
	      register_type: (sourceTag === '' && hasModbusFields) ? normalizeModbusRegisterType(rawRegisterType) : '',
	      address: (sourceTag === '' && rawAddress != null) ? String(rawAddress).trim() : '',
	      offset: (sourceTag === '' && rawOffset != null) ? String(rawOffset).trim() : '',
	      source_tag: sourceTag,
	      bit: (t?.bit == null || sourceTag === '') ? '' : String(t.bit),
	      initial_value: String(t?.initial_value ?? ''),
	      invert: (t?.invert === true) ? 'true' : 'false',
	      datatype: String(t?.datatype || '').trim(),
	      elem_count: (t?.elem_count == null) ? '' : String(t.elem_count),
	      scan_ms: (t?.scan_ms == null) ? '' : String(t.scan_ms),
	      enabled: (t?.enabled !== false) ? 'true' : 'false',
	      writable: (t?.writable === true) ? 'true' : 'false',
	      scaling: String(scaling.scaling || '').trim(),
	      raw_low: String(scaling.raw_low ?? ''),
	      raw_high: String(scaling.raw_high ?? ''),
	      scaled_low: String(scaling.scaled_low ?? ''),
	      scaled_high: String(scaling.scaled_high ?? ''),
	      clamp_low: (String(scaling.clamp_low).toLowerCase() === 'true') ? 'true' : 'false',
	      clamp_high: (String(scaling.clamp_high).toLowerCase() === 'true') ? 'true' : 'false',
	      scaled_datatype: String(scaling.scaled_datatype || '').trim(),
	      log_event_on_change: (t?.log_event_on_change === true) ? 'true' : 'false',
	      log_periodic_mode: String(t?.log_periodic_mode || '').trim(),
	      log_periodic_interval_sec: (t?.log_periodic_interval_sec == null) ? '' : String(t.log_periodic_interval_sec),
	      historian_enabled: historian.enabled ? 'true' : 'false',
	      historian_mode: historian.enabled ? historian.mode : '',
	      historian_interval_sec: historian.enabled ? String(Math.max(1, Math.trunc(historian.interval_ms / 1000))) : '',
	      action: ''
	    };
	  });

  const safe = displayConnectionName(cid).replace(/[^a-z0-9._-]+/gi, '_');
  downloadTextFile({
    filename: `opcbridge-tags-${safe}.csv`,
    mime: 'text/csv',
    text: toCsv(rows, headers)
  });
}

const ALARM_CSV_HEADERS = [
  'id',
  'name',
  'group',
  'site',
  'connection_id',
  'tag_name',
  'type',
  'value',
  'threshold',
  'hysteresis',
  'delay_sec',
  'severity',
  'enabled',
  'audio_file',
  'speech_text',
  'notification_policy',
  'message_on_active',
  'message_on_return',
  'action'
];

function alarmCsvValueText(alarm) {
  if (!Object.prototype.hasOwnProperty.call(alarm || {}, 'value')) return '';
  const value = alarm.value;
  if (value == null) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function parseAlarmCompareValueCsv(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return '';
  const lower = raw.toLowerCase();
  if (lower === 'true') return true;
  if (lower === 'false') return false;
  const n = Number(raw);
  if (Number.isFinite(n) && raw !== '') return n;
  try {
    if ((raw.startsWith('{') && raw.endsWith('}')) || (raw.startsWith('[') && raw.endsWith(']'))) return JSON.parse(raw);
  } catch {
    // Keep plain text if the user did not enter valid JSON.
  }
  return raw;
}

function unwrapAlarmCompareValue(value) {
  let cur = value;
  for (let i = 0; i < 8; i += 1) {
    if (!cur || typeof cur !== 'object' || Array.isArray(cur)) break;
    if (!Object.prototype.hasOwnProperty.call(cur, 'value')) break;
    if (Object.prototype.hasOwnProperty.call(cur, 'ok') && cur.ok !== true) break;
    cur = cur.value;
  }
  return cur;
}

function downloadAlarmsCsv({ group = '', site = '' } = {}) {
  const cfg = state.alarmsConfig || { alarms: [] };
  const g = String(group || '').trim();
  const s = String(site || '').trim();
  const alarms = (Array.isArray(cfg.alarms) ? cfg.alarms : [])
    .filter((a) => {
      if (!g && !s) return true;
      const ag = String(a?.group || '').trim();
      const as = String(a?.site || '').trim();
      if (g && ag !== g) return false;
      if (s && as !== s) return false;
      return true;
    })
    .slice()
    .sort((a, b) => String(a?.group || '').localeCompare(String(b?.group || ''), undefined, { numeric: true, sensitivity: 'base' })
      || String(a?.site || '').localeCompare(String(b?.site || ''), undefined, { numeric: true, sensitivity: 'base' })
      || String(a?.name || a?.id || '').localeCompare(String(b?.name || b?.id || ''), undefined, { numeric: true, sensitivity: 'base' }));
  const rows = alarms.map((a) => ({
    id: String(a?.id || '').trim(),
    name: String(a?.name || a?.id || '').trim(),
    group: String(a?.group || '').trim(),
    site: String(a?.site || '').trim(),
    connection_id: String(a?.connection_id || '').trim(),
    tag_name: String(a?.tag_name || a?.tag || '').trim(),
    type: String(a?.type || '').trim(),
    value: alarmCsvValueText(a),
    threshold: (a?.threshold == null) ? '' : String(a.threshold),
    hysteresis: (a?.hysteresis == null) ? '' : String(a.hysteresis),
    delay_sec: Number.isFinite(Number(a?.delay_ms)) ? String(Number(a.delay_ms) / 1000) : '0',
    severity: (a?.severity == null) ? '500' : String(a.severity),
    enabled: (a?.enabled !== false) ? 'true' : 'false',
    audio_file: String(a?.audio_file || '').trim(),
    speech_text: String(a?.speech_text || '').trim(),
    notification_policy: String(a?.notification_policy || '').trim(),
    message_on_active: String(a?.message_on_active || '').trim(),
    message_on_return: String(a?.message_on_return || '').trim(),
    action: ''
  }));

  downloadTextFile({
    filename: (g || s)
      ? `opcbridge-alarms-${(g || 'all').replace(/[^a-z0-9._-]+/gi, '_')}${s ? `-${s.replace(/[^a-z0-9._-]+/gi, '_')}` : ''}.csv`
      : 'opcbridge-alarms.csv',
    mime: 'text/csv',
    text: toCsv(rows, ALARM_CSV_HEADERS)
  });
}

function parseCsv(text) {
  const input = String(text || '');
  const firstNonEmptyLine = (() => {
    const lines = input.split(/\r?\n/g);
    for (const line of lines) {
      if (String(line || '').trim() !== '') return String(line);
    }
    return '';
  })();

  // Auto-detect delimiter (supports CSV and TSV; common spreadsheet exports).
  const delimiter = (() => {
    const line = firstNonEmptyLine;
    const count = (ch) => (line.split(ch).length - 1);
    const commas = count(',');
    const tabs = count('\t');
    const semis = count(';');
    if (tabs > commas && tabs >= semis) return '\t';
    if (semis > commas && semis > tabs) return ';';
    return ',';
  })();

  const rows = [];
  let row = [];
  let field = '';
  let i = 0;
  let inQuotes = false;

  const pushField = () => {
    row.push(field);
    field = '';
  };
  const pushRow = () => {
    // Ignore trailing empty line
    if (row.length === 1 && String(row[0] || '').trim() === '' && rows.length === 0) return;
    rows.push(row);
    row = [];
  };

  while (i < input.length) {
    const ch = input[i];
    if (inQuotes) {
      if (ch === '"') {
        const next = input[i + 1];
        if (next === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (ch === '"') {
      inQuotes = true;
      i += 1;
      continue;
    }
    if (ch === delimiter) {
      pushField();
      i += 1;
      continue;
    }
    if (ch === '\r') {
      // ignore, handle at \n
      i += 1;
      continue;
    }
    if (ch === '\n') {
      pushField();
      pushRow();
      i += 1;
      continue;
    }
    field += ch;
    i += 1;
  }
  // Flush last field/row
  pushField();
  if (row.some((c) => String(c || '').length > 0)) pushRow();

  if (!rows.length) return { headers: [], records: [] };
  const headers = rows[0].map((h) => String(h || '').trim());
  const records = [];
  rows.slice(1).forEach((cells) => {
    const obj = {};
    headers.forEach((h, idx) => {
      obj[h] = (idx < cells.length) ? cells[idx] : '';
    });
    // drop totally empty rows
    const hasAny = Object.values(obj).some((v) => String(v || '').trim() !== '');
    if (hasAny) records.push(obj);
  });
  return { headers, records };
}

function parseBoolLoose(value, defaultValue) {
  const raw = String(value ?? '').trim().toLowerCase();
  if (!raw) return defaultValue;
  if (raw === 'true' || raw === '1' || raw === 'yes' || raw === 'y' || raw === 'on') return true;
  if (raw === 'false' || raw === '0' || raw === 'no' || raw === 'n' || raw === 'off') return false;
  return defaultValue;
}

function parseIntLoose(value, defaultValue) {
  const raw = String(value ?? '').trim();
  if (!raw) return defaultValue;
  const n = Number(raw);
  if (!Number.isFinite(n)) return defaultValue;
  return Math.trunc(n);
}

function parseFloatLoose(value, defaultValue) {
  const raw = String(value ?? '').trim();
  if (!raw) return defaultValue;
  const n = Number(raw);
  if (!Number.isFinite(n)) return defaultValue;
  return n;
}

function isNumericBitSourceDatatype(dt) {
  const s = String(dt || '').trim().toLowerCase();
  return s === 'int16' || s === 'uint16' || s === 'int32' || s === 'uint32';
}

function isDirectPlcSourceTag(t) {
  if (!t || typeof t !== 'object') return false;
  const sourceRaw = String(t?.source || t?.source_type || t?.source_kind || '').trim().toLowerCase();
  if (sourceRaw === 'memory') return false;
  if (String(t?.source_tag || '').trim()) return false;
  if (String(t?.plc_tag_name || '').trim()) return true;
  const registerType = normalizeModbusRegisterType(t?.register_type || t?.modbus_type || t?.register);
  const hasModbusRegister = registerType === 'coil' ||
    registerType === 'discrete_input' ||
    registerType === 'input_register' ||
    registerType === 'holding_register';
  const hasModbusAddress = t?.address != null ||
    t?.offset != null ||
    t?.modbus_address != null ||
    t?.modbus_offset != null;
  return hasModbusRegister && hasModbusAddress;
}

function getDerivedBitSourceOptions(connectionId, excludeTagName) {
  const cid = String(connectionId || '').trim();
  const ex = String(excludeTagName || '').trim();
  const all = getEffectiveTagsAll();
  const names = all
    .filter((t) => String(t?.connection_id || '') === cid)
    .filter((t) => String(t?.name || '') !== ex)
    .filter((t) => isDirectPlcSourceTag(t))
    .filter((t) => isNumericBitSourceDatatype(t?.datatype))
    .flatMap((t) => {
      const name = String(t?.name || '').trim();
      if (!name) return [];
      const ec = Math.max(1, Math.floor(Number(t?.elem_count) || 1));
      if (ec <= 1) return [name];
      const out = [];
      for (let i = 0; i < ec; i++) out.push(`${name}[${i}]`);
      return out;
    })
    .filter(Boolean)
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
  return names;
}

function getDerivedAliasSourceOptions(connectionId, excludeTagName) {
  const cid = String(connectionId || '').trim();
  const ex = String(excludeTagName || '').trim();
  const all = getEffectiveTagsAll();
  const names = all
    .filter((t) => String(t?.connection_id || '') === cid)
    .filter((t) => String(t?.name || '') !== ex)
    .filter((t) => isDirectPlcSourceTag(t))
    .flatMap((t) => {
      const name = String(t?.name || '').trim();
      if (!name) return [];
      const ec = Math.max(1, Math.floor(Number(t?.elem_count) || 1));
      if (ec <= 1) return [name];
      const out = [];
      for (let i = 0; i < ec; i++) out.push(`${name}[${i}]`);
      return out;
    })
    .filter(Boolean)
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
  return names;
}

function applyTagSourceKindUi({ kindEl, plcEl, initialRowEl, initialEl, derivedRowEl, sourceEl, bitBoxEl, bitEl, datatypeEl, elemCountEl, writableEl, scalingEl, scalingLinearRowEl }, { connId, excludeTagName }) {
  const kind = String(kindEl?.value || 'plc').trim().toLowerCase();
  const isMemory = (kind === 'memory');
  const isDerivedBit = (kind === 'derived_bit');
  const isDerivedAlias = (kind === 'derived_alias');
  const isDerived = (isDerivedBit || isDerivedAlias);

  if (derivedRowEl) derivedRowEl.style.display = isDerived ? '' : 'none';
  if (initialRowEl) initialRowEl.style.display = isMemory ? '' : 'none';
  if (bitBoxEl) bitBoxEl.style.display = isDerivedBit ? '' : 'none';
  if (plcEl) plcEl.disabled = isDerived || isMemory || !canEditConfig();
  if (initialEl) initialEl.disabled = !isMemory || !canEditConfig();
  if (sourceEl) sourceEl.disabled = !canEditConfig();
  if (bitEl) bitEl.disabled = isDerivedAlias || !canEditConfig();

  if (datatypeEl) {
    if (isDerivedBit) {
      fillTagDatatypeSelect(datatypeEl, 'bool');
      datatypeEl.disabled = true;
    } else {
      datatypeEl.disabled = !canEditConfig();
    }
  }

  if (elemCountEl) elemCountEl.disabled = isDerived || isMemory || !canEditConfig();
  if (writableEl) {
    writableEl.disabled = !canEditConfig();
  }
  if (scalingEl) {
    if (isDerivedBit || isMemory) {
      scalingEl.value = 'none';
      scalingEl.disabled = true;
      if (scalingLinearRowEl) scalingLinearRowEl.style.display = 'none';
    } else {
      scalingEl.disabled = !canEditConfig();
    }
  }

  if (isDerivedBit && sourceEl) {
    const opts = getDerivedBitSourceOptions(connId, excludeTagName);
    const selected = String(sourceEl.value || '').trim();
    sourceEl.innerHTML = '';
    opts.forEach((n) => {
      const o = document.createElement('option');
      o.value = n;
      o.textContent = n;
      sourceEl.appendChild(o);
    });
    if (selected && opts.includes(selected)) sourceEl.value = selected;
  }
  if (isDerivedAlias && sourceEl) {
    const opts = getDerivedAliasSourceOptions(connId, excludeTagName);
    const selected = String(sourceEl.value || '').trim();
    sourceEl.innerHTML = '';
    opts.forEach((n) => {
      const o = document.createElement('option');
      o.value = n;
      o.textContent = n;
      sourceEl.appendChild(o);
    });
    if (selected && opts.includes(selected)) sourceEl.value = selected;
  }
}

function csvNormalizeHeaderKey(key) {
  return String(key || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/[^a-z0-9_]/g, '');
}

function csvGet(rowObj, key) {
  if (!rowObj || typeof rowObj !== 'object') return '';
  const direct = rowObj[key];
  if (direct != null) return direct;
  const want = csvNormalizeHeaderKey(key);
  if (!want) return '';
  for (const k of Object.keys(rowObj)) {
    if (csvNormalizeHeaderKey(k) === want) return rowObj[k];
  }
  return '';
}

async function pickCsvText() {
  return new Promise((resolve, reject) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.csv,text/csv';
    input.style.position = 'fixed';
    input.style.left = '-9999px';
    input.style.top = '-9999px';
    document.body.appendChild(input);

    const cleanup = () => {
      try { input.remove(); } catch { /* ignore */ }
    };

    input.addEventListener('change', () => {
      try {
        const file = input.files && input.files[0];
        if (!file) { cleanup(); return resolve(''); }
        const reader = new FileReader();
        reader.onerror = () => { cleanup(); reject(new Error('Failed to read file.')); };
        reader.onload = () => { cleanup(); resolve(String(reader.result || '')); };
        reader.readAsText(file);
      } catch (err) {
        cleanup();
        reject(err);
      }
    }, { once: true });

    input.click();
  });
}

async function importDevicesCsvIntoWorkspace() {
  const csvText = await pickCsvText();
  if (!csvText) return;

  const { records } = parseCsv(csvText);
  if (!records.length) { setWorkspaceSaveStatus('CSV had no data rows (make sure the first row is a header).'); return; }

  let staged = 0;
  let deleted = 0;
  let skipped = 0;
  let ambiguous = 0;
  records.forEach((r) => {
    // Current exports use connection_name. "description" keeps older exports portable.
    const connectionName = String(csvGet(r, 'connection_name') || csvGet(r, 'description') || '').trim();
    if (!connectionName) { skipped += 1; return; }

    const matches = (state.connFiles || []).filter((file) => {
      const path = String(file?.path || '').trim();
      const obj = state.connObjCache?.get?.(path);
      return String(obj?.description || '').trim().toLowerCase() === connectionName.toLowerCase();
    });
    if (matches.length > 1) { skipped += 1; ambiguous += 1; return; }

    const existingPath = String(matches[0]?.path || '').trim();
    const existingObj = existingPath ? state.connObjCache?.get?.(existingPath) : null;
    const connection_id = existingPath
      ? connectionIdForConnFilePath(existingPath)
      : generateWorkspaceConnectionId();
    const relPath = existingPath || `connections/${connection_id}.json`;

    if (isDeleteAction(csvGet(r, 'action'))) {
      if (!existingPath) { skipped += 1; return; }
      state.workspaceDeletePaths?.add?.(relPath);
      state.workspaceConnDirty?.delete?.(relPath);
      state.connObjCache?.delete?.(relPath);
      state.connFiles = (state.connFiles || []).filter((f) => String(f?.path || '') !== relPath);

      // Also remove tags belonging to this device.
      state.tagConfigAll = (state.tagConfigAll || []).filter((t) => String(t?.connection_id || '') !== connection_id);
      state.tagConfigEdited = new Map();
      markTagsDirty(true);

      deleted += 1;
      return;
    }

    const driver = String(csvGet(r, 'driver') || '').trim() || 'ab_eip';
    const plc_type = String(csvGet(r, 'plc_type') || '').trim() || 'lgx';
    const gateway = String(csvGet(r, 'gateway') || '').trim();
    const pathVal = String(csvGet(r, 'path') || '').trim() || '1,0';
    const slot = parseIntLoose(csvGet(r, 'slot'), 0) || 0;
    const pollingMode = normalizePollingMode(csvGet(r, 'polling_mode'));
    const pollingPacing = normalizePollingPacing(csvGet(r, 'polling_pacing'));
    const pollBatchSize = parseIntLoose(csvGet(r, 'poll_batch_size'), 0) || 0;
    const pollTimeBudgetMs = parseIntLoose(csvGet(r, 'poll_time_budget_ms'), 0) || 0;

    const obj = applyPollingConfigToConnection(
      { ...(existingObj || {}), id: connection_id, description: connectionName, driver, gateway, path: pathVal, slot, plc_type },
      { mode: pollingMode, pacing: pollingPacing, batchSize: pollBatchSize, timeBudgetMs: pollTimeBudgetMs }
    );

    if (!state.workspaceConnDirty) state.workspaceConnDirty = new Map();
    state.workspaceConnDirty.set(relPath, obj);
    state.connObjCache?.set?.(relPath, obj);

    if (!Array.isArray(state.connFiles)) state.connFiles = [];
    if (!state.connFiles.some((f) => String(f?.path || '') === relPath)) {
      state.connFiles.push({ kind: 'connection', path: relPath });
    }

    staged += 1;
  });

  renderWorkspaceSaveBar();
  saveWorkspaceDraft();
  renderWorkspaceTree();
  setWorkspaceSaveStatus(`Imported devices CSV: staged ${staged} device(s)${deleted ? `, deleted ${deleted}` : ''}${skipped ? `, skipped ${skipped}${ambiguous ? ` (${ambiguous} ambiguous connection name${ambiguous === 1 ? '' : 's'})` : ''}` : ''}.`);
}

async function importTagsCsvIntoWorkspace(connectionId) {
  const cid = String(connectionId || '').trim();
  if (!cid) return;

  if (workspaceIsDirty()) {
    window.alert('Please Save or Discard current Workspace changes before importing a tag CSV. Server-side CSV import writes directly to the tag file.');
    return;
  }

  const csvText = await pickCsvText();
  if (!csvText) return;

  const connectionName = displayConnectionName(cid);
  setWorkspaceSaveStatus(`Importing tags CSV for ${connectionName} on server...`);
  renderWorkspaceSaveBar();

  const result = await apiPostJson('/api/opcbridge/config/tags/import_csv', {
    connection_id: cid,
    csv: csvText
  });
  invalidateLoggerTagPickerCache();
  setWorkspaceSaveStatus('Imported CSV. Rebuilding full runtime…');
  renderWorkspaceSaveBar();
  await opcbridgeReload();
  await loadTagsConfig();
  let historianSyncText = '';
  try {
    const count = await saveHistorianConfigFromWorkspaceTags(getEffectiveTagsAll());
    historianSyncText = ` Historian config synced for ${count} tag(s).`;
  } catch (err) {
    historianSyncText = ` Historian config sync failed: ${String(err?.message || err)}.`;
  }
  renderWorkspaceTree();
  await refreshVisible().catch(() => {});

  const skipped = Number(result?.skipped || 0);
  const missing = Number(result?.skipped_missing_required_fields || 0);
  const skipParts = [];
  if (missing) skipParts.push(`${missing} missing required fields`);
  const skipText = skipped ? `, skipped ${skipped}${skipParts.length ? ` (${skipParts.join(', ')})` : ''}` : '';
  setWorkspaceSaveStatus(`Imported tags CSV for ${connectionName}: upserted ${Number(result?.upserted || 0)}, deleted ${Number(result?.deleted || 0)}${skipText}. Rebuilt full runtime.${historianSyncText}`);
}

async function importAlarmsCsv() {
  if (!canEditConfig()) { window.alert('Login required to import alarms.'); return; }
  const csvText = await pickCsvText();
  if (!csvText) return;

  const { records } = parseCsv(csvText);
  if (!records.length) { window.alert('CSV had no data rows (make sure the first row is a header).'); return; }

  // Validate imported alarms against configured tags (not runtime tags).
  // This prevents "phantom" alarms created by typos in connection_id/tag_name.
  if (!Array.isArray(state.tagConfigLoadedAll) || state.tagConfigLoadedAll.length === 0) {
    await loadTagsConfig().catch(() => null);
  }
  const tagRefSet = new Set();
  (Array.isArray(state.tagConfigLoadedAll) ? state.tagConfigLoadedAll : []).forEach((t) => {
    const cid = String(t?.connection_id || '').trim();
    if (!cid) return;
    const add = (ref) => {
      const s = String(ref || '').trim();
      if (!s) return;
      tagRefSet.add(`${cid}\0${s}`);
    };
    add(t?.name);
    add(t?.plc_tag_name);
    if (t?.address != null) add(String(t.address));
  });
  if (tagRefSet.size === 0) {
    window.alert('Cannot import alarms CSV: configured tag list is empty or unavailable (needed to validate connection_id/tag_name).');
    return;
  }

  const cfg = await loadOpcbridgeAlarmsConfig();
  if (!Array.isArray(cfg.alarms)) cfg.alarms = [];
  ensureAlarmGroupsTree(cfg);

  // Build lookup maps so re-imports don't accidentally duplicate alarms if IDs differ.
  const idxById = new Map();
  const idxByConnTag = new Map(); // key: conn_id + \0 + tag_name
  const idxByNameConnTag = new Map(); // key: name + \0 + conn_id + \0 + tag_name
  cfg.alarms.forEach((a, i) => {
    const id = String(a?.id || '').trim();
    if (id && !idxById.has(id)) idxById.set(id, i);
    const conn = String(a?.connection_id || '').trim();
    const tag = String(a?.tag_name || a?.tag || '').trim();
    const name = String(a?.name || '').trim();
    if (conn && tag) {
      const k = `${conn}\0${tag}`;
      if (!idxByConnTag.has(k)) idxByConnTag.set(k, i);
      if (name) {
        const k2 = `${name.toLowerCase()}\0${conn}\0${tag}`;
        if (!idxByNameConnTag.has(k2)) idxByNameConnTag.set(k2, i);
      }
    }
  });

  let upserts = 0;
  let deleted = 0;
  let skipped = 0;
  let skippedMissing = 0;
  let skippedInvalid = 0;
  let rejectedUnknownTag = 0;
  let sampleMissing = null;
  let sampleInvalid = null;
  const failures = [];

  records.forEach((r, recordIdx) => {
    const id = String(csvGet(r, 'id') || csvGet(r, 'alarm_id') || '').trim();
    if (!id) {
      skipped += 1;
      skippedMissing += 1;
      if (!sampleMissing) sampleMissing = { id, reason: 'missing id' };
      return;
    }
    // Guardrail: alarm IDs should not contain whitespace.
    // Whitespace (including accidental spaces) can cause imports to create duplicates and break routing.
    if (/\s/.test(id)) {
      skipped += 1;
      skippedInvalid += 1;
      if (!sampleInvalid) sampleInvalid = { id, reason: `invalid id (contains whitespace): '${id}'` };
      return;
    }

    let idx = idxById.has(id) ? idxById.get(id) : -1;
    if (isDeleteAction(csvGet(r, 'action'))) {
      if (idx >= 0) {
        cfg.alarms.splice(idx, 1);
        deleted += 1;
      }
      return;
    }

    const typeRaw = String(csvGet(r, 'type') || '').trim().toLowerCase();
    let type = typeRaw.replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '_').replace(/_+/g, '_').replace(/^_+|_+$/g, '');
    if (type === 'not_equal' || type === 'notequals' || type === 'ne' || type === 'neq' || type === '!=')
      type = 'not_equals';
    if (type === 'equal' || type === 'eq' || type === '==') type = 'equals';
    if (!['equals', 'not_equals', 'contains', 'not_contains', 'empty', 'not_empty', 'change', 'high', 'low'].includes(type)) {
      skipped += 1;
      skippedInvalid += 1;
      if (!sampleInvalid) sampleInvalid = { id, reason: `invalid type '${typeRaw || '(blank)'}'` };
      return;
    }

    const rawConn = String(csvGet(r, 'connection_id') || '');
    const rawTag = String(csvGet(r, 'tag_name') || csvGet(r, 'tag') || '');
    const connectionId = rawConn.trim();
    const tagName = rawTag.trim();
    if (!connectionId || !tagName) {
      skipped += 1;
      skippedMissing += 1;
      if (!sampleMissing) sampleMissing = { id, reason: 'missing connection_id or tag_name' };
      return;
    }
    // Guardrail: connection_id and tag_name should not contain whitespace.
    // Whitespace (including accidental spaces) can cause imports to create duplicate alarms.
    if (/\s/.test(connectionId)) {
      skipped += 1;
      skippedInvalid += 1;
      if (!sampleInvalid) sampleInvalid = { id, reason: `invalid connection_id (contains whitespace): '${connectionId}'` };
      return;
    }
    if (/\s/.test(tagName)) {
      skipped += 1;
      skippedInvalid += 1;
      if (!sampleInvalid) sampleInvalid = { id, reason: `invalid tag_name (contains whitespace): '${tagName}'` };
      return;
    }

    // Strict validation: connection_id/tag_name must refer to a configured tag.
    if (!tagRefSet.has(`${connectionId}\0${tagName}`)) {
      skipped += 1;
      rejectedUnknownTag += 1;
      failures.push({
        row: recordIdx + 2, // +1 for 0-index, +1 for header line
        id,
        connection_id: connectionId,
        tag_name: tagName,
        reason: 'unknown tag (not in configured tag list)'
      });
      if (!sampleInvalid) sampleInvalid = { id, reason: `unknown tag '${connectionId}:${tagName}'` };
      return;
    }

    // If no direct ID match, attempt to match existing alarms by (name+conn+tag) or (conn+tag).
    // This prevents accidental duplication when importing a CSV whose "id" column contains the display name.
    if (idx < 0) {
      const nameKey = String(csvGet(r, 'name') || '').trim();
      const k2 = nameKey ? `${nameKey.toLowerCase()}\0${connectionId}\0${tagName}` : '';
      if (k2 && idxByNameConnTag.has(k2)) idx = idxByNameConnTag.get(k2);
      if (idx < 0) {
        const k = `${connectionId}\0${tagName}`;
        if (idxByConnTag.has(k)) idx = idxByConnTag.get(k);
      }
    }

    const alarm = (idx >= 0) ? { ...(cfg.alarms[idx] || {}) } : { id };
    // Preserve existing ID when matching by conn/tag, otherwise use CSV id.
    alarm.id = (idx >= 0 && String((cfg.alarms[idx] || {}).id || '').trim()) ? String((cfg.alarms[idx] || {}).id || '').trim() : id;
    alarm.name = String(csvGet(r, 'name') || alarm.name || id).trim() || id;
    alarm.group = normalizeAlarmGroupName(csvGet(r, 'group'));
    alarm.site = normalizeAlarmSiteName(csvGet(r, 'site'));
    alarm.connection_id = connectionId;
    alarm.tag_name = tagName;
    alarm.type = type;
    alarm.enabled = parseBoolLoose(csvGet(r, 'enabled'), true);

    const sev = parseIntLoose(csvGet(r, 'severity'), 500);
    alarm.severity = Math.max(0, sev == null ? 500 : sev);

    const audioFile = String(csvGet(r, 'audio_file') || '').trim();
    if (audioFile) alarm.audio_file = validateAlarmAudioFileId(cfg, audioFile);
    else delete alarm.audio_file;

    const speechText = String(csvGet(r, 'speech_text') || '').trim();
    if (speechText) alarm.speech_text = speechText;
    else delete alarm.speech_text;

    const policy = String(csvGet(r, 'notification_policy') || csvGet(r, 'policy') || '').trim();
    if (policy) alarm.notification_policy = policy;
    else delete alarm.notification_policy;

    alarm.message_on_active = String(csvGet(r, 'message_on_active') || '').trim();
    alarm.message_on_return = String(csvGet(r, 'message_on_return') || '').trim();
    const delaySec = parseFloatLoose(csvGet(r, 'delay_sec'), 0);
    alarm.delay_ms = Math.max(0, Math.round((delaySec || 0) * 1000));

    if (type === 'high' || type === 'low') {
      const threshold = parseFloatLoose(csvGet(r, 'threshold'), null);
      if (threshold == null) {
        skipped += 1;
        skippedMissing += 1;
        if (!sampleMissing) sampleMissing = { id, reason: 'missing threshold' };
        return;
      }
      alarm.threshold = threshold;
      delete alarm.value;
      delete alarm.equals_value;
      const hysteresis = parseFloatLoose(csvGet(r, 'hysteresis'), null);
      if (hysteresis == null) delete alarm.hysteresis;
      else alarm.hysteresis = hysteresis;
    } else if (['equals', 'not_equals', 'contains', 'not_contains'].includes(type)) {
      alarm.value = parseAlarmCompareValueCsv(csvGet(r, 'value'));
      delete alarm.threshold;
      delete alarm.hysteresis;
      delete alarm.equals_value;
    } else {
      delete alarm.value;
      delete alarm.threshold;
      delete alarm.hysteresis;
      delete alarm.equals_value;
    }

    if (alarm.group) {
      upsertAlarmGroup(cfg, alarm.group);
      if (alarm.site) ensureGroupSiteInConfig(cfg, alarm.group, alarm.site);
    }

    if (idx >= 0) cfg.alarms[idx] = alarm;
    else cfg.alarms.push(alarm);
    upserts += 1;
  });

  try {
    await saveOpcbridgeAlarmsConfig(cfg);
    await loadOpcbridgeAlarmsConfig();
    renderWorkspaceTree();
    renderAlarmsEventsTree();
  } catch (err) {
    const msg = `CSV import failed: ${String(err?.message || err)}`;
    setWorkspaceSaveStatus(msg);
    window.alert(msg);
    return;
  }

  const details = [];
  if (skippedMissing) details.push(`${skippedMissing} missing required fields`);
  if (skippedInvalid) details.push(`${skippedInvalid} invalid value(s)`);
  if (rejectedUnknownTag) details.push(`${rejectedUnknownTag} unknown tag(s)`);
  const sample = sampleInvalid || sampleMissing;
  const suffix = details.length ? `, skipped ${skipped} (${details.join(', ')})` : (skipped ? `, skipped ${skipped}` : '');
  const example = sample ? ` Example: ${sample.id || '(blank id)'} - ${sample.reason}.` : '';
  const msg = `Imported alarms CSV: upserted ${upserts} alarm(s)${deleted ? `, deleted ${deleted}` : ''}${suffix}.${example}`;
  setWorkspaceSaveStatus(msg);
  window.alert(msg);

  if (failures.length) {
    const lines = failures.slice(0, 12).map((f) => `- row ${f.row}: ${f.id}: ${f.connection_id}:${f.tag_name}`);
    const extra = failures.length > 12 ? `\n… +${failures.length - 12} more` : '';
    const prompt = `Some rows were rejected and not imported (unknown tag):\n\n${lines.join('\n')}${extra}\n\nDownload a failures CSV now?`;
    if (window.confirm(prompt)) {
      downloadTextFile({
        filename: `opcbridge-alarms-import-failures-${new Date().toISOString().replace(/[:.]/g, '-')}.csv`,
        mime: 'text/csv',
        text: toCsv(failures, ['row', 'id', 'connection_id', 'tag_name', 'reason'])
      });
    }
  }
}

const TAG_DATATYPE_OPTIONS = [
  { value: 'bool', label: 'Boolean' },
  { value: 'int16', label: 'Int16' },
  { value: 'uint16', label: 'UInt16' },
  { value: 'int32', label: 'Int32' },
  { value: 'uint32', label: 'UInt32' },
  { value: 'float32', label: 'Float32' },
  { value: 'float64', label: 'Float64' },
  { value: 'string', label: 'String' },
];

const TAG_SCALED_DATATYPE_OPTIONS = [
  { value: '', label: '(default float64)' },
  { value: 'float64', label: 'Float64' },
  { value: 'float32', label: 'Float32' },
  { value: 'int32', label: 'Int32' },
  { value: 'uint32', label: 'UInt32' },
  { value: 'int16', label: 'Int16' },
  { value: 'uint16', label: 'UInt16' },
];

function fillTagDatatypeSelect(selectEl, selected) {
  if (!selectEl) return;
  const cur = String(selected || '').trim().toLowerCase();
  selectEl.textContent = '';

  TAG_DATATYPE_OPTIONS.forEach((opt) => {
    const o = document.createElement('option');
    o.value = opt.value;
    o.textContent = opt.label;
    selectEl.appendChild(o);
  });

  if (cur && TAG_DATATYPE_OPTIONS.some((x) => x.value == cur)) {
    selectEl.value = cur;
    return;
  }

  // default
  selectEl.value = 'bool';
}

function fillScaledDatatypeSelect(selectEl, selected) {
  if (!selectEl) return;
  const cur = String(selected ?? '').trim().toLowerCase();
  selectEl.textContent = '';
  TAG_SCALED_DATATYPE_OPTIONS.forEach((opt) => {
    const o = document.createElement('option');
    o.value = opt.value;
    o.textContent = opt.label;
    selectEl.appendChild(o);
  });

  const known = TAG_SCALED_DATATYPE_OPTIONS.some((x) => x.value === cur);
  selectEl.value = known ? cur : '';
}

function applyScalingModeUi(modeEl, linearRowEl) {
  if (!modeEl || !linearRowEl) return;
  const mode = String(modeEl.value || 'none').trim().toLowerCase();
  linearRowEl.style.display = (mode === 'linear') ? '' : 'none';
}

function readLinearScalingFromUi({ scalingEl, rawLowEl, rawHighEl, scaledLowEl, scaledHighEl, scaledDatatypeEl, clampLowEl, clampHighEl }, datatype) {
  const mode = String(scalingEl?.value || 'none').trim().toLowerCase();
  if (mode !== 'linear') return { ok: true, scaling: 'none', fields: {} };

  const dt = String(datatype || '').trim().toLowerCase();
  if (dt === 'bool' || dt === 'string') return { ok: false, error: 'Scaling is only supported for numeric datatypes.' };

  const rawLowStr = String(rawLowEl?.value ?? '').trim();
  const rawHighStr = String(rawHighEl?.value ?? '').trim();
  const scaledLowStr = String(scaledLowEl?.value ?? '').trim();
  const scaledHighStr = String(scaledHighEl?.value ?? '').trim();
  if (!rawLowStr || !rawHighStr || !scaledLowStr || !scaledHighStr) {
    return { ok: false, error: 'Raw Low/High and Scaled Low/High are required for Linear scaling.' };
  }

  const raw_low = Number(rawLowStr);
  const raw_high = Number(rawHighStr);
  const scaled_low = Number(scaledLowStr);
  const scaled_high = Number(scaledHighStr);
  if (![raw_low, raw_high, scaled_low, scaled_high].every((n) => Number.isFinite(n))) {
    return { ok: false, error: 'Scaling bounds must be valid numbers.' };
  }
  if (raw_high === raw_low) return { ok: false, error: 'Raw High must be different from Raw Low.' };
  if (scaled_high === scaled_low) return { ok: false, error: 'Scaled High must be different from Scaled Low.' };

  const fields = {
    scaling: 'linear',
    raw_low,
    raw_high,
    scaled_low,
    scaled_high,
    clamp_low: Boolean(clampLowEl?.checked),
    clamp_high: Boolean(clampHighEl?.checked),
  };
  const sdt = String(scaledDatatypeEl?.value || '').trim().toLowerCase();
  if (sdt) fields.scaled_datatype = sdt;
  return { ok: true, scaling: 'linear', fields };
}

function fmtTime(tsMs) {
  const t = Number(tsMs);
  if (!Number.isFinite(t) || t <= 0) return '';
  try { return new Date(t).toLocaleString(); } catch { return new Date(t).toISOString(); }
}

function fmtLogTime(tsMs) {
  const t = Number(tsMs);
  if (!Number.isFinite(t) || t <= 0) return '';
  const d = new Date(t);
  const two = (v) => String(v).padStart(2, '0');
  return `${two(d.getMonth() + 1)}/${two(d.getDate())}/${two(d.getFullYear() % 100)} ${two(d.getHours())}:${two(d.getMinutes())}:${two(d.getSeconds())}`;
}

function renderJson(el, obj) {
  if (!el) return;
  el.textContent = JSON.stringify(obj, null, 2);
}

// ---------------- Alarms config (opcbridge alarms.json) ----------------

function normalizeAlarmGroupName(name) {
  return String(name || '').trim();
}

function normalizeAlarmSiteName(name) {
  return String(name || '').trim();
}

function ensureAlarmGroupsTree(cfgObj) {
  const obj = (cfgObj && typeof cfgObj === 'object' && !Array.isArray(cfgObj)) ? cfgObj : {};
  if (!obj.audio || typeof obj.audio !== 'object' || Array.isArray(obj.audio)) obj.audio = {};
  if (!Array.isArray(obj.audio.files)) obj.audio.files = [];
  obj.audio.files = obj.audio.files
    .filter((f) => f && typeof f === 'object' && !Array.isArray(f))
    .map((f) => ({
      ...f,
      id: String(f.id || '').trim(),
      name: String(f.name || f.id || '').trim(),
      path: String(f.path || '').trim()
    }))
    .filter((f) => f.id);
  if (!Array.isArray(obj.groups)) obj.groups = [];
  obj.groups = obj.groups.filter((g) => g && typeof g === 'object' && !Array.isArray(g));
  obj.groups.forEach((g) => {
    g.name = normalizeAlarmGroupName(g.name || g.label || g.id || '');
    if (!Array.isArray(g.sites)) g.sites = [];
    g.sites = g.sites.filter((s) => s && typeof s === 'object' && !Array.isArray(s));
    g.sites.forEach((s) => { s.name = normalizeAlarmSiteName(s.name || s.label || s.id || ''); });
    g.sites = g.sites.filter((s) => s.name);
  });
  obj.groups = obj.groups.filter((g) => g.name);
  return obj;
}

function getAlarmAudioFiles(cfgObj = state.alarmsConfig) {
  const cfg = (cfgObj && typeof cfgObj === 'object' && !Array.isArray(cfgObj)) ? cfgObj : {};
  const files = Array.isArray(cfg.audio?.files) ? cfg.audio.files : [];
  return files
    .filter((f) => f && typeof f === 'object' && !Array.isArray(f) && String(f.id || '').trim())
    .map((f) => ({
      id: String(f.id || '').trim(),
      name: String(f.name || f.id || '').trim(),
      path: String(f.path || '').trim()
    }))
    .sort((a, b) => String(a.name || a.id).localeCompare(String(b.name || b.id), undefined, { numeric: true, sensitivity: 'base' }));
}

function alarmAudioFileText(fileId, cfgObj = state.alarmsConfig) {
  const id = String(fileId || '').trim();
  if (!id) return 'none';
  const f = getAlarmAudioFiles(cfgObj).find((x) => x.id === id);
  return f ? `${f.name || f.id} (${f.id})` : id;
}

function createAlarmAudioFileInput(cfgObj, value = '', { placeholder = 'Blank = inherit', disabled = false } = {}) {
  const wrap = document.createElement('div');
  wrap.style.display = 'grid';
  wrap.style.gap = '6px';

  const files = getAlarmAudioFiles(cfgObj || {});
  const input = document.createElement('input');
  input.type = 'text';
  input.value = String(value || '').trim();
  input.placeholder = placeholder;
  input.disabled = disabled;

  const list = document.createElement('select');
  list.className = 'alarm-audio-picker-list';
  list.size = Math.min(8, Math.max(3, files.length || 3));
  list.disabled = disabled || !files.length;

  const renderList = () => {
    const q = String(input.value || '').trim().toLowerCase();
    const matches = files.filter((f) => {
      if (!q) return true;
      return [f.id, f.name, f.path].some((v) => String(v || '').toLowerCase().includes(q));
    });
    list.textContent = '';
    matches.forEach((f) => {
      const opt = document.createElement('option');
      opt.value = String(f.id || '').trim();
      opt.textContent = f.path ? `${f.name || f.id} (${f.path})` : `${f.name || f.id} (${f.id})`;
      if (opt.value === String(input.value || '').trim()) opt.selected = true;
      list.appendChild(opt);
    });
    if (!matches.length) {
      const opt = document.createElement('option');
      opt.value = '';
      opt.textContent = files.length ? 'No matching audio files' : 'No audio files configured';
      opt.disabled = true;
      list.appendChild(opt);
    }
  };

  input.addEventListener('input', renderList);
  const applyListSelection = () => {
    const selected = list.selectedOptions && list.selectedOptions.length
      ? String(list.selectedOptions[0].value || '').trim()
      : String(list.value || '').trim();
    input.value = selected;
    renderList();
  };
  list.addEventListener('mousedown', (e) => {
    const opt = e.target && e.target.tagName === 'OPTION' ? e.target : null;
    if (!opt) return;
    const selected = String(opt.value || '').trim();
    if (!selected) return;
    input.value = selected;
    opt.selected = true;
    e.preventDefault();
    renderList();
  }, true);
  list.addEventListener('change', applyListSelection);
  list.addEventListener('dblclick', applyListSelection);
  list.addEventListener('focus', () => {
    if (!String(input.value || '').trim()) renderList();
  });
  renderList();

  const clearBtn = document.createElement('button');
  clearBtn.type = 'button';
  clearBtn.className = 'btn';
  clearBtn.textContent = 'Clear / Inherit';
  clearBtn.disabled = disabled;
  clearBtn.addEventListener('click', () => {
    input.value = '';
    renderList();
    input.focus();
  });

  const row = document.createElement('div');
  row.className = 'row-actions';
  row.style.alignItems = 'stretch';
  row.appendChild(input);
  const showAllBtn = document.createElement('button');
  showAllBtn.type = 'button';
  showAllBtn.className = 'btn';
  showAllBtn.textContent = 'Show All';
  showAllBtn.disabled = disabled || !files.length;
  showAllBtn.addEventListener('click', () => {
    input.value = '';
    renderList();
    list.focus();
  });
  row.appendChild(showAllBtn);
  row.appendChild(clearBtn);

  const hint = document.createElement('div');
  hint.className = 'hint';
  hint.textContent = files.length
    ? 'Type to filter, select a file from the list, paste an audio file ID, or clear to inherit.'
    : 'No audio files are configured yet.';

  wrap.appendChild(row);
  wrap.appendChild(list);
  wrap.appendChild(hint);
  return { wrap, input };
}

function createAlarmAudioSequenceInput(cfgObj, values = [], { disabled = false, onDirty = null } = {}) {
  const wrap = document.createElement('div');
  wrap.style.display = 'grid';
  wrap.style.gap = '12px';

  const files = getAlarmAudioFiles(cfgObj || {});
  const byId = new Map(files.map((f) => [String(f.id || '').trim(), f]));
  const sequence = (Array.isArray(values) ? values : [])
    .map((v) => String(v || '').trim())
    .filter(Boolean)
    .filter((id, idx, arr) => arr.indexOf(id) === idx);
  const availableSelection = new Set();
  const sequenceSelection = new Set();
  const filter = document.createElement('input');
  filter.type = 'text';
  filter.placeholder = 'Filter by file name or folder';
  filter.disabled = disabled;
  const notifyDirty = () => { if (typeof onDirty === 'function') onDirty(); };
  const folderText = (pathValue) => {
    const parts = String(pathValue || '').split('/').filter(Boolean);
    if (parts[0]?.toLowerCase() === 'audio') parts.shift();
    if (parts.length && /\.[A-Za-z0-9]+$/.test(parts[parts.length - 1])) parts.pop();
    return parts.join(' / ') || 'Audio root';
  };
  const sortedAvailable = () => files.filter((file) => !sequence.includes(String(file?.id || '').trim()))
    .slice().sort((a, b) => {
      const folderOrder = folderText(a?.path).localeCompare(folderText(b?.path), undefined, { numeric: true, sensitivity: 'base' });
      return folderOrder || String(a?.name || a?.id || '').localeCompare(String(b?.name || b?.id || ''), undefined, { numeric: true, sensitivity: 'base' });
    });

  const availableWrap = document.createElement('div');
  const availableTitle = document.createElement('div');
  availableTitle.className = 'hint';
  availableTitle.textContent = 'Available Audio Files';
  const availableTableWrap = document.createElement('div');
  availableTableWrap.className = 'table-wrap';
  availableTableWrap.style.maxHeight = '230px';
  availableTableWrap.style.overflow = 'auto';
  const availableTable = document.createElement('table');
  availableTable.className = 'table';
  availableTable.innerHTML = '<thead><tr><th style="width:64px;text-align:center;">Select</th><th>Folder</th><th>File</th></tr></thead><tbody></tbody>';
  const availableBody = availableTable.querySelector('tbody');
  availableTableWrap.appendChild(availableTable);
  const availableActions = document.createElement('div');
  availableActions.className = 'row-actions';
  availableActions.style.marginTop = '6px';
  const addSelected = document.createElement('button');
  addSelected.type = 'button'; addSelected.className = 'btn primary'; addSelected.textContent = 'Add Selected ↓'; addSelected.disabled = disabled;
  const selectAllFiltered = document.createElement('button');
  selectAllFiltered.type = 'button'; selectAllFiltered.className = 'btn'; selectAllFiltered.textContent = 'Select All Filtered'; selectAllFiltered.disabled = disabled;
  const availableCount = document.createElement('span');
  availableCount.className = 'hint';
  availableActions.append(addSelected, selectAllFiltered, availableCount);
  availableWrap.append(filter, availableTitle, availableTableWrap, availableActions);

  const sequenceWrap = document.createElement('div');
  const sequenceTitle = document.createElement('div');
  sequenceTitle.className = 'hint';
  sequenceTitle.textContent = 'Playback Sequence';
  const sequenceTableWrap = document.createElement('div');
  sequenceTableWrap.className = 'table-wrap';
  sequenceTableWrap.style.maxHeight = '230px';
  sequenceTableWrap.style.overflow = 'auto';
  const sequenceTable = document.createElement('table');
  sequenceTable.className = 'table';
  sequenceTable.innerHTML = '<thead><tr><th style="width:64px;text-align:center;">Select</th><th style="width:130px;">Order</th><th>Folder</th><th>File</th></tr></thead><tbody></tbody>';
  const sequenceBody = sequenceTable.querySelector('tbody');
  sequenceTableWrap.appendChild(sequenceTable);
  const sequenceActions = document.createElement('div');
  sequenceActions.className = 'row-actions';
  sequenceActions.style.marginTop = '6px';
  const removeSelected = document.createElement('button');
  removeSelected.type = 'button'; removeSelected.className = 'btn bad'; removeSelected.textContent = 'Remove Selected'; removeSelected.disabled = disabled;
  const sequenceCount = document.createElement('span');
  sequenceCount.className = 'hint';
  sequenceActions.append(removeSelected, sequenceCount);
  sequenceWrap.append(sequenceTitle, sequenceTableWrap, sequenceActions);

  let filteredAvailableIds = [];
  const move = (id, delta) => {
    const index = sequence.indexOf(id);
    const next = index + delta;
    if (index < 0 || next < 0 || next >= sequence.length) return;
    [sequence[index], sequence[next]] = [sequence[next], sequence[index]];
    render();
    notifyDirty();
  };
  const render = () => {
    availableBody.textContent = '';
    sequenceBody.textContent = '';
    filteredAvailableIds = [];
    const q = String(filter.value || '').trim().toLowerCase();
    sortedAvailable().forEach((file) => {
      const id = String(file?.id || '').trim();
      const name = String(file?.name || id).trim() || id;
      const path = String(file?.path || '').trim();
      const search = [name, path, id].join(' ').toLowerCase();
      if (q && !search.includes(q)) return;
      filteredAvailableIds.push(id);
      const row = document.createElement('tr');
      const selectCell = document.createElement('td');
      selectCell.style.textAlign = 'center';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = availableSelection.has(id);
      checkbox.disabled = disabled;
      checkbox.setAttribute('aria-label', `Select available audio file ${name}`);
      checkbox.addEventListener('change', () => {
        if (checkbox.checked) availableSelection.add(id);
        else availableSelection.delete(id);
      });
      selectCell.appendChild(checkbox);
      const folderCell = document.createElement('td');
      folderCell.textContent = folderText(path);
      const nameCell = document.createElement('td');
      nameCell.textContent = name;
      row.append(selectCell, folderCell, nameCell);
      availableBody.appendChild(row);
    });
    if (!availableBody.children.length) {
      const row = document.createElement('tr');
      const cell = document.createElement('td');
      cell.colSpan = 3; cell.className = 'hint'; cell.textContent = 'No available audio files match the filter.';
      row.appendChild(cell); availableBody.appendChild(row);
    }
    availableCount.textContent = `${filteredAvailableIds.length} shown`;

    sequence.forEach((id, index) => {
      const file = byId.get(id);
      const name = file ? String(file.name || id) : `${id} (missing)`;
      const row = document.createElement('tr');
      const selectCell = document.createElement('td');
      selectCell.style.textAlign = 'center';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox'; checkbox.checked = sequenceSelection.has(id); checkbox.disabled = disabled;
      checkbox.setAttribute('aria-label', `Select playback item ${name}`);
      checkbox.addEventListener('change', () => {
        if (checkbox.checked) sequenceSelection.add(id);
        else sequenceSelection.delete(id);
      });
      selectCell.appendChild(checkbox);
      const orderCell = document.createElement('td');
      const controls = document.createElement('div');
      controls.className = 'row-actions'; controls.style.flexWrap = 'nowrap';
      const number = document.createElement('span'); number.textContent = `${index + 1}`; number.style.minWidth = '20px';
      const up = document.createElement('button');
      up.type = 'button'; up.className = 'btn'; up.textContent = '↑'; up.title = 'Move earlier'; up.disabled = disabled || index === 0; up.onclick = () => move(id, -1);
      const down = document.createElement('button');
      down.type = 'button'; down.className = 'btn'; down.textContent = '↓'; down.title = 'Move later'; down.disabled = disabled || index === sequence.length - 1; down.onclick = () => move(id, 1);
      controls.append(number, up, down); orderCell.appendChild(controls);
      const folderCell = document.createElement('td'); folderCell.textContent = file ? folderText(file.path) : 'Missing';
      const nameCell = document.createElement('td'); nameCell.textContent = name;
      row.append(selectCell, orderCell, folderCell, nameCell);
      sequenceBody.appendChild(row);
    });
    if (!sequence.length) {
      const row = document.createElement('tr');
      const cell = document.createElement('td'); cell.colSpan = 4; cell.className = 'hint'; cell.textContent = 'No files in the playback sequence.';
      row.appendChild(cell); sequenceBody.appendChild(row);
    }
    sequenceCount.textContent = `${sequence.length} file${sequence.length === 1 ? '' : 's'} in playback order`;
  };

  filter.addEventListener('input', () => {
    availableSelection.clear();
    render();
  });
  selectAllFiltered.addEventListener('click', () => {
    filteredAvailableIds.forEach((id) => availableSelection.add(id));
    render();
  });
  addSelected.addEventListener('click', () => {
    sortedAvailable().forEach((file) => {
      const id = String(file?.id || '').trim();
      if (availableSelection.has(id) && !sequence.includes(id)) sequence.push(id);
    });
    availableSelection.clear();
    render(); notifyDirty();
  });
  removeSelected.addEventListener('click', () => {
    for (let index = sequence.length - 1; index >= 0; index -= 1) {
      if (sequenceSelection.has(sequence[index])) sequence.splice(index, 1);
    }
    sequenceSelection.clear();
    render(); notifyDirty();
  });
  wrap.append(availableWrap, sequenceWrap);
  render();

  return {
    wrap,
    getValues: () => sequence.slice(),
    getSelectedValue: () => sequence[0] || ''
  };
}

function validateAlarmAudioFileId(cfgObj, audioFileId) {
  const raw = String(audioFileId || '').trim();
  if (!raw) return '';
  const files = getAlarmAudioFiles(cfgObj || {});
  const exactId = files.find((f) => String(f?.id || '').trim() === raw);
  if (exactId) return String(exactId.id || '').trim();
  const exactName = files.find((f) => String(f?.name || '').trim().toLowerCase() === raw.toLowerCase());
  if (exactName) return String(exactName.id || '').trim();
  const exactPath = files.find((f) => String(f?.path || '').trim().toLowerCase() === raw.toLowerCase());
  if (exactPath) return String(exactPath.id || '').trim();
  const contains = files.filter((f) => [f?.id, f?.name, f?.path].some((v) => String(v || '').toLowerCase().includes(raw.toLowerCase())));
  if (contains.length === 1) return String(contains[0]?.id || '').trim();
  throw new Error(`Audio file '${raw}' is not in the audio files list.`);
}

function findAlarmGroupConfig(cfgObj, groupName) {
  const want = normalizeAlarmGroupName(groupName).toLowerCase();
  if (!want) return null;
  const groups = Array.isArray(cfgObj?.groups) ? cfgObj.groups : [];
  return groups.find((g) => String(g?.name || '').trim().toLowerCase() === want) || null;
}

function findAlarmSiteConfig(cfgObj, groupName, siteName) {
  const group = findAlarmGroupConfig(cfgObj, groupName);
  const want = normalizeAlarmSiteName(siteName).toLowerCase();
  if (!group || !want) return null;
  const sites = Array.isArray(group.sites) ? group.sites : [];
  return sites.find((s) => String(s?.name || '').trim().toLowerCase() === want) || null;
}

function isAlarmSiteProcessingEnabled(cfgObj, groupName, siteName) {
  const site = findAlarmSiteConfig(cfgObj, groupName, siteName);
  return !site || site.alarms_enabled !== false;
}

function alarmsForSite(cfgObj, groupName, siteName) {
  const g = String(groupName || '').trim();
  const s = String(siteName || '').trim();
  return (Array.isArray(cfgObj?.alarms) ? cfgObj.alarms : []).filter((a) => {
    return String(a?.group || '').trim() === g && String(a?.site || '').trim() === s;
  });
}

function alarmsForGroup(cfgObj, groupName) {
  const g = String(groupName || '').trim();
  return (Array.isArray(cfgObj?.alarms) ? cfgObj.alarms : []).filter((a) => String(a?.group || '').trim() === g);
}

function resolveInheritedAlarmAudio(cfgObj, groupName, siteName) {
  const cfg = (cfgObj && typeof cfgObj === 'object' && !Array.isArray(cfgObj)) ? cfgObj : {};
  const pushSeq = (arr, v) => {
    const id = String(v || '').trim();
    if (!id) return;
    arr.push(id);
  };
  const out = {
    audio_mode: String(cfg.audio?.audio_mode || 'audio_then_speech'),
    audio_file: String(cfg.audio?.default_file || '').trim(),
    audio_files: [],
    speech_text: String(cfg.audio?.speech_text || '').trim(),
    speech_texts: [],
    source: 'global'
  };
  if (out.audio_file) pushSeq(out.audio_files, out.audio_file);
  if (out.speech_text) out.speech_texts.push(out.speech_text);
  const group = findAlarmGroupConfig(cfg, groupName);
  if (group) {
    if (String(group.audio_mode || '').trim()) {
      out.audio_mode = String(group.audio_mode || '').trim();
      out.source = 'group';
    }
    if (String(group.audio_file || '').trim()) {
      out.audio_file = String(group.audio_file || '').trim();
      pushSeq(out.audio_files, out.audio_file);
      out.source = 'group';
    }
    if (Array.isArray(group.audio_files)) {
      group.audio_files.forEach((id) => pushSeq(out.audio_files, id));
      if (!String(group.audio_file || '').trim() && out.audio_files.length) out.audio_file = out.audio_files[out.audio_files.length - 1];
      out.source = 'group';
    }
    if (String(group.speech_text || '').trim()) {
      out.speech_text = String(group.speech_text || '').trim();
      out.speech_texts.push(out.speech_text);
      out.source = 'group';
    }
  }
  const site = findAlarmSiteConfig(cfg, groupName, siteName);
  if (site) {
    if (String(site.audio_mode || '').trim()) {
      out.audio_mode = String(site.audio_mode || '').trim();
      out.source = 'site';
    }
    if (String(site.audio_file || '').trim()) {
      out.audio_file = String(site.audio_file || '').trim();
      pushSeq(out.audio_files, out.audio_file);
      out.source = 'site';
    }
    if (Array.isArray(site.audio_files)) {
      site.audio_files.forEach((id) => pushSeq(out.audio_files, id));
      if (!String(site.audio_file || '').trim() && out.audio_files.length) out.audio_file = out.audio_files[out.audio_files.length - 1];
      out.source = 'site';
    }
    if (String(site.speech_text || '').trim()) {
      out.speech_text = String(site.speech_text || '').trim();
      out.speech_texts.push(out.speech_text);
      out.source = 'site';
    }
  }
  return out;
}

function resolveAlarmAudio(cfgObj, alarm) {
  const inherited = resolveInheritedAlarmAudio(cfgObj, alarm?.group, alarm?.site);
  const ownFile = String(alarm?.audio_file || '').trim();
  const ownFiles = Array.isArray(alarm?.audio_files) ? alarm.audio_files.map((v) => String(v || '').trim()).filter(Boolean) : [];
  const ownSpeech = String(alarm?.speech_text || '').trim();
  const audioFiles = inherited.audio_files ? inherited.audio_files.slice() : [];
  const pushSeq = (arr, v) => {
    const id = String(v || '').trim();
    if (!id) return;
    arr.push(id);
  };
  const speechTexts = inherited.speech_texts ? inherited.speech_texts.slice() : [];
  ownFiles.forEach((id) => pushSeq(audioFiles, id));
  if (ownFile && !(ownFiles.length && ownFiles[0] === ownFile)) pushSeq(audioFiles, ownFile);
  if (ownSpeech) speechTexts.push(ownSpeech);
  const effectiveFile = ownFile || (ownFiles.length ? ownFiles[0] : '') || inherited.audio_file || '';
  const mode = String(alarm?.audio_mode || inherited.audio_mode || 'audio_then_speech').trim();
  const normalizedMode = ['audio_only', 'speech_only', 'audio_then_speech', 'speech_then_audio'].includes(mode) ? mode : 'audio_then_speech';
  return {
    audio_file: String(effectiveFile).trim(),
    speech_text: String(ownSpeech || inherited.speech_text || '').trim(),
    audio_files: audioFiles,
    speech_texts: speechTexts,
    audio_mode: normalizedMode,
    source: ownFile || ownFiles.length || ownSpeech ? 'alarm' : inherited.source
  };
}

function alarmAudioSequenceText(audioIds, cfgObj = state.alarmsConfig, speechTexts = [], audioMode = 'audio_then_speech') {
  const ids = (Array.isArray(audioIds) ? audioIds : []).map((id) => String(id || '').trim()).filter(Boolean);
  const modeRaw = String(audioMode || 'audio_then_speech').trim();
  const mode = ['audio_only', 'speech_only', 'audio_then_speech', 'speech_then_audio'].includes(modeRaw) ? modeRaw : 'audio_then_speech';
  const audioParts = ids.map((id) => alarmAudioFileText(id, cfgObj));
  const speechParts = (Array.isArray(speechTexts) ? speechTexts : []).map((s) => String(s || '').trim()).filter(Boolean).map((text) => `TTS: ${text.length > 40 ? `${text.slice(0, 40)}...` : text}`);
  let parts = [];
  if (mode === 'audio_only') parts = audioParts;
  else if (mode === 'speech_only') parts = speechParts;
  else if (mode === 'speech_then_audio') parts = speechParts.concat(audioParts);
  else parts = audioParts.concat(speechParts);
  return parts.length ? parts.join(' -> ') : 'none';
}

function parseOpcbridgeAlarmsConfig(resp) {
  // Expected: { ok, json: { alarms: [...] , groups?: [...] }, mtime_ms }
  const cfg = resp?.json;
  if (!cfg || typeof cfg !== 'object') return { alarms: [], groups: [] };
  const out = { ...(cfg || {}) };
  if (Array.isArray(out.rules) && out.rules.length > 0) {
    const legacyById = new Map();
    if (Array.isArray(out.alarms)) {
      out.alarms.forEach((a) => {
        const id = String(a?.id || '').trim();
        if (id) legacyById.set(id, a);
      });
    }
    out.alarms = out.rules.map((rule) => {
      const a = alarmRuleToUiAlarm(rule);
      if (!a) return null;
      const legacy = legacyById.get(String(a.id || '').trim()) || {};
      if (!String(a.notification_policy || '').trim() && String(legacy?.notification_policy || '').trim()) {
        a.notification_policy = String(legacy.notification_policy || '').trim();
      }
      if (!String(a.speech_text || '').trim() && String(legacy?.speech_text || '').trim()) {
        a.speech_text = String(legacy.speech_text || '').trim();
      }
      if (!String(a.audio_mode || '').trim() && String(legacy?.audio_mode || '').trim()) {
        a.audio_mode = String(legacy.audio_mode || '').trim();
      }
      if (!Number.isFinite(Number(a.audio_gap_ms)) && Number.isFinite(Number(legacy?.audio_gap_ms))) {
        a.audio_gap_ms = Math.max(0, Math.trunc(Number(legacy.audio_gap_ms)));
      }
      if ((!Array.isArray(a.audio_files) || !a.audio_files.length) && Array.isArray(legacy?.audio_files) && legacy.audio_files.length) {
        a.audio_files = legacy.audio_files.map((v) => String(v || '').trim()).filter(Boolean);
      }
      if (!String(a.audio_file || '').trim() && String(legacy?.audio_file || '').trim()) {
        a.audio_file = String(legacy.audio_file || '').trim();
      }
      return a;
    }).filter(Boolean);
  } else if (!Array.isArray(out.alarms)) {
    out.alarms = [];
  }
  ensureAlarmGroupsTree(out);
  normalizeAlarmCompareValuesInConfig(out);
  return out;
}

function alarmRuleToUiAlarm(rule) {
  if (!rule || typeof rule !== 'object' || Array.isArray(rule)) return null;
  const source = (rule.source && typeof rule.source === 'object' && !Array.isArray(rule.source)) ? rule.source : {};
  const condition = (rule.condition && typeof rule.condition === 'object' && !Array.isArray(rule.condition)) ? rule.condition : {};
  const type = String(condition.type || rule.type || '').trim();
  const out = {
    id: String(rule.id || '').trim(),
    name: String(rule.name || rule.id || '').trim(),
    group: String(rule.group || '').trim(),
    site: String(rule.site || '').trim(),
    connection_id: String(source.connection_id || rule.connection_id || '').trim(),
    tag_name: String(source.tag || rule.tag_name || rule.tag || '').trim(),
    type,
    enabled: rule.enabled !== false,
    severity: Number.isFinite(Number(rule.severity)) ? Math.trunc(Number(rule.severity)) : 500,
    message_on_active: String(rule.message_on_active || '').trim(),
    message_on_return: String(rule.message_on_return || '').trim()
  };
  if (Number.isFinite(Number(rule.delay_ms))) out.delay_ms = Math.max(0, Math.trunc(Number(rule.delay_ms)));
  if (String(rule.audio_mode || '').trim()) out.audio_mode = String(rule.audio_mode || '').trim();
  if (Number.isFinite(Number(rule.audio_gap_ms))) out.audio_gap_ms = Math.max(0, Math.trunc(Number(rule.audio_gap_ms)));
  if (String(rule.audio_file || '').trim()) out.audio_file = String(rule.audio_file || '').trim();
  if (Array.isArray(rule.audio_files)) out.audio_files = rule.audio_files.map((v) => String(v || '').trim()).filter(Boolean);
  if (String(rule.speech_text || '').trim()) out.speech_text = String(rule.speech_text || '').trim();
  if (String(rule.notification_policy || '').trim()) out.notification_policy = String(rule.notification_policy || '').trim();
  if (type === 'high' || type === 'low') {
    if (condition.threshold != null) out.threshold = condition.threshold;
    if (condition.hysteresis != null) out.hysteresis = condition.hysteresis;
  } else if (type === 'equals' || type === 'not_equals') {
    if (Object.prototype.hasOwnProperty.call(condition, 'value')) out.value = unwrapAlarmCompareValue(condition.value);
  }
  return out.id ? out : null;
}

function uiAlarmToRule(alarm) {
  const a = (alarm && typeof alarm === 'object' && !Array.isArray(alarm)) ? alarm : {};
  const type = String(a.type || '').trim();
  const rule = {
    id: String(a.id || '').trim(),
    name: String(a.name || a.id || '').trim(),
    group: String(a.group || '').trim(),
    site: String(a.site || '').trim(),
    enabled: a.enabled !== false,
    severity: Number.isFinite(Number(a.severity)) ? Math.trunc(Number(a.severity)) : 500,
    source: {
      connection_id: String(a.connection_id || '').trim(),
      tag: String(a.tag_name || a.tag || '').trim()
    },
    condition: { type },
    message_on_active: String(a.message_on_active || '').trim(),
    message_on_return: String(a.message_on_return || '').trim()
  };
  if (Number.isFinite(Number(a.delay_ms))) rule.delay_ms = Math.max(0, Math.trunc(Number(a.delay_ms)));
  if (String(a.audio_mode || '').trim()) rule.audio_mode = String(a.audio_mode || '').trim();
  if (Number.isFinite(Number(a.audio_gap_ms))) rule.audio_gap_ms = Math.max(0, Math.trunc(Number(a.audio_gap_ms)));
  if (String(a.audio_file || '').trim()) rule.audio_file = String(a.audio_file || '').trim();
  if (Array.isArray(a.audio_files)) {
    const ids = a.audio_files.map((v) => String(v || '').trim()).filter(Boolean);
    if (ids.length) rule.audio_files = ids;
  }
  if (String(a.speech_text || '').trim()) rule.speech_text = String(a.speech_text || '').trim();
  if (String(a.notification_policy || '').trim()) rule.notification_policy = String(a.notification_policy || '').trim();
  if (type === 'high' || type === 'low') {
    rule.condition.threshold = Number(a.threshold);
    if (a.hysteresis != null && String(a.hysteresis).trim() !== '') rule.condition.hysteresis = Number(a.hysteresis);
  } else if (type === 'equals' || type === 'not_equals') {
    rule.condition.value = unwrapAlarmCompareValue(Object.prototype.hasOwnProperty.call(a, 'value') ? a.value : a.equals_value);
  }
  return rule;
}

function normalizeAlarmCompareValuesInConfig(cfg) {
  if (!cfg || typeof cfg !== 'object' || !Array.isArray(cfg.alarms)) return cfg;
  cfg.alarms.forEach((alarm) => {
    const type = String(alarm?.type || '').trim();
    if (type === 'equals' || type === 'not_equals') {
      if (Object.prototype.hasOwnProperty.call(alarm, 'value')) alarm.value = unwrapAlarmCompareValue(alarm.value);
      if (Object.prototype.hasOwnProperty.call(alarm, 'equals_value')) alarm.equals_value = unwrapAlarmCompareValue(alarm.equals_value);
    }
  });
  return cfg;
}

function syncAlarmRulesFromAlarms(cfg) {
  if (!cfg || typeof cfg !== 'object' || Array.isArray(cfg)) return cfg;
  if (!Array.isArray(cfg.alarms)) cfg.alarms = [];
  normalizeAlarmCompareValuesInConfig(cfg);
  const rules = cfg.alarms.map(uiAlarmToRule);
  const invalid = [];
  rules.forEach((r, idx) => {
    const ok = Boolean(r?.id && r?.source?.connection_id && r?.source?.tag && r?.condition?.type);
    if (ok) return;
    const alarm = cfg.alarms[idx] || {};
    invalid.push(String(alarm?.id || `#${idx + 1}`));
  });
  if (invalid.length) {
    throw new Error(`Cannot save alarms config. Invalid trigger fields for: ${invalid.join(', ')}`);
  }
	  cfg.rules = rules;
	  return cfg;
	}

function buildEmptySchema2Config() {
  return {
    schema_version: 2,
    timezone: 'America/Chicago',
    // Schedules are user-defined. The special schedule_id "always" is virtual/implicit
    // and should not be persisted as a schedule row.
    schedules: [],
    groups: [],
    alarms: [],
    rules: [],
    // Current notification model:
    targets: [],
    routes: [],
    policies: [],
    assignments: [],
    alarm_groups: [],
    // Other top-level sections:
    audio: { files: [] },
    sip: {},
    scada: {}
  };
}

function alarmTreeSafeKey(value) {
  const k = String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return k || 'none';
}

function alarmEventsSiteNodeId(group, site) {
  const groupLabel = String(group || '').trim() || 'Unassigned';
  const siteLabel = String(site || '').trim() || 'Unassigned';
  const groupNodeId = `alarm_group:${alarmTreeSafeKey(groupLabel)}`;
  return `${groupNodeId}:site:${alarmTreeSafeKey(siteLabel)}`;
}

function expandAlarmEventsAlarmPath(group, site) {
  if (!state.alarmsEventsExpanded) state.alarmsEventsExpanded = new Set();
  const groupLabel = String(group || '').trim() || 'Unassigned';
  state.alarmsEventsExpanded.add('folder:alarms_events');
  state.alarmsEventsExpanded.add('folder:alarms');
  state.alarmsEventsExpanded.add(`alarm_group:${alarmTreeSafeKey(groupLabel)}`);
  state.alarmsEventsExpanded.add(alarmEventsSiteNodeId(group, site));
}

function selectAlarmEventsAlarm(alarmId, group, site) {
  expandAlarmEventsAlarmPath(group, site);
  state.alarmsEventsSelectedNodeId = alarmEventsSiteNodeId(group, site);
  state.alarmsEventsSelectedChildId = alarmId ? `alarm:${alarmId}` : '';
}

function cleanupLeakedRouteGroupAssignments(cfg) {
  const alarms = Array.isArray(cfg?.alarms) ? cfg.alarms : [];
  const groupNames = new Set((Array.isArray(cfg?.groups) ? cfg.groups : []).map((g) => String(g?.name || '').trim().toLowerCase()).filter(Boolean));
  const routeNames = new Set(getRoutingAlarmGroups(cfg).flatMap((route) => {
    const id = String(route?.id || '').trim().toLowerCase();
    const name = String(route?.name || '').trim().toLowerCase();
    return [id, name].filter(Boolean);
  }));
  let changed = false;
  alarms.forEach((alarm) => {
    const group = String(alarm?.group || '').trim();
    if (!group) return;
    const key = group.toLowerCase();
    if (groupNames.has(key)) return;
    if (!routeNames.has(key)) return;
    alarm.group = '';
    alarm.site = '';
    changed = true;
  });
  return changed;
}

function normalizeAlarmsConfigInvariants(cfg) {
  const out = (cfg && typeof cfg === 'object' && !Array.isArray(cfg)) ? cfg : {};
  const fixes = [];

  // v2 is the current editing model, but do not delete legacy/unknown subtrees
  // during normalization. Older installs may still carry notification/audio
  // settings there; dropping them during a load or unrelated save is data loss.
  out.schema_version = 2;
  if (!Array.isArray(out.targets)) out.targets = [];
  if (!Array.isArray(out.routes)) out.routes = [];
  if (!Array.isArray(out.policies)) out.policies = [];
  if (!Array.isArray(out.alarm_groups)) out.alarm_groups = [];
  if (!Array.isArray(out.schedules)) out.schedules = [];
  if (!out.audio || typeof out.audio !== 'object' || Array.isArray(out.audio)) out.audio = {};
  if (!Array.isArray(out.audio.files)) out.audio.files = [];

  // Option A: schedule_id="always" is virtual/implicit and should not be persisted.
  // If an 'always' schedule row exists (legacy), prune it.
  {
    const schedules = getSchedules(out);
    const before = schedules.length;
    out.schedules = schedules.filter((s) => String(s?.id || '').trim() !== 'always');
    if (out.schedules.length !== before) fixes.push("removed persisted 'always' schedule (virtual)");
  }

  const configuredOutput = getConfiguredAudioOutput(out);
  const route = findDefaultAudioRoute(out);
  if (route && route.type === 'audio_command') {
    const wantArgs = buildAudioRouteArgsForOutput(configuredOutput);
    const curArgs = Array.isArray(route.args) ? route.args.map((v) => String(v || '')) : [];
    if (JSON.stringify(curArgs) !== JSON.stringify(wantArgs)) {
      route.args = wantArgs;
      fixes.push(`aligned default_audio route args to configured output '${configuredOutput}'`);
    }
  }

  return fixes;
}

async function loadOpcbridgeAlarmsConfig() {
  const resp = await apiGet('/api/opcbridge/config/alarms');
  state.alarmsConfigLast = resp || null;
  state.alarmsConfigMtimeMs = Number(resp?.mtime_ms || 0) || 0;
  state.alarmsConfig = parseOpcbridgeAlarmsConfig(resp);
  const leakedChanged = cleanupLeakedRouteGroupAssignments(state.alarmsConfig);
  const fixes = normalizeAlarmsConfigInvariants(state.alarmsConfig);
  // Loading config must be read-only. Previously this auto-saved normalization
  // fixes, which could erase legacy notification/audio settings after install
  // or reload. Report the cleanup, but persist only on an explicit user save.
  if (leakedChanged || fixes.length) {
    const notes = leakedChanged ? fixes.concat(['route/alarm group cleanup available']) : fixes;
    if (els.alarmsEventsPropsStatus && notes.length) {
      els.alarmsEventsPropsStatus.textContent = `Config cleanup available; save explicitly to apply: ${notes.join('; ')}`;
    }
  }
  return state.alarmsConfig;
}

async function saveOpcbridgeAlarmsConfig(nextCfg) {
  const obj = (nextCfg && typeof nextCfg === 'object' && !Array.isArray(nextCfg)) ? nextCfg : {};
  const allowAlarmDrop = obj.__allow_alarm_drop === true;
  if (Object.prototype.hasOwnProperty.call(obj, '__allow_alarm_drop')) delete obj.__allow_alarm_drop;
  if (!Array.isArray(obj.alarms)) obj.alarms = [];

  // Option A: schedule_id="always" is virtual/implicit. Ensure we never persist an 'always' schedule row.
  if (Array.isArray(obj.schedules)) {
    const before = obj.schedules.length;
    obj.schedules = obj.schedules.filter((s) => String(s?.id || '').trim() !== 'always');
    // Keep normalization side-effect silent here; normalizeAlarmsConfigInvariants() may add a fix note elsewhere.
    void before;
  }

  // Guardrail: this editor writes the full alarms.json document.
  // If our in-memory view is stale/partial, a normal save can accidentally wipe alarms/rules.
  // Block unexpected drops unless the caller explicitly allows deletion.
  try {
    const liveResp = await apiGet('/api/opcbridge/config/alarms');
    const liveCfg = parseOpcbridgeAlarmsConfig(liveResp);
    const liveAlarms = Array.isArray(liveCfg?.alarms) ? liveCfg.alarms.length : 0;
    const liveRules = Array.isArray(liveCfg?.rules) ? liveCfg.rules.length : 0;
    const nextAlarms = Array.isArray(obj?.alarms) ? obj.alarms.length : 0;
    const nextRules = Array.isArray(obj?.rules) ? obj.rules.length : 0;
    if (!allowAlarmDrop && liveAlarms > 0 && nextAlarms < liveAlarms) {
      throw new Error(`Refusing save: alarm count would drop from ${liveAlarms} to ${nextAlarms}. Reload and retry.`);
    }
    if (!allowAlarmDrop && liveRules > 0 && nextRules < liveRules) {
      throw new Error(`Refusing save: rule count would drop from ${liveRules} to ${nextRules}. Reload and retry.`);
    }
  } catch (err) {
    if (String(err?.message || '').startsWith('Refusing save:')) throw err;
  }

  normalizeAlarmsConfigInvariants(obj);
  ensureAlarmGroupsTree(obj);
  syncAlarmRulesFromAlarms(obj);

  const content = JSON.stringify(obj, null, 2) + '\n';
  await apiPostJson('/api/opcbridge/config/file', { path: 'alarms.json', content });
}

function upsertAlarmGroup(cfg, groupName) {
  const name = normalizeAlarmGroupName(groupName);
  if (!name) throw new Error('Group name is required.');
  ensureAlarmGroupsTree(cfg);
  const want = name.toLowerCase();
  if (cfg.groups.some((g) => String(g?.name || '').toLowerCase() === want)) return;
  cfg.groups.push({ name, sites: [] });
}

function upsertAlarmSite(cfg, groupName, siteName) {
  const gname = normalizeAlarmGroupName(groupName);
  const sname = normalizeAlarmSiteName(siteName);
  if (!gname) throw new Error('Group name is required.');
  if (!sname) throw new Error('Site name is required.');
  ensureAlarmGroupsTree(cfg);
  const group = cfg.groups.find((g) => String(g?.name || '').toLowerCase() === gname.toLowerCase()) || null;
  if (!group) throw new Error(`Group not found: ${gname}`);
  const want = sname.toLowerCase();
  if (Array.isArray(group.sites) && group.sites.some((s) => String(s?.name || '').toLowerCase() === want)) return;
  group.sites = Array.isArray(group.sites) ? group.sites : [];
  group.sites.push({ name: sname });
}

function ensureGroupSiteInConfig(cfg, groupName, siteName) {
  const g = normalizeAlarmGroupName(groupName);
  const s = normalizeAlarmSiteName(siteName);
  if (g) upsertAlarmGroup(cfg, g);
  if (g && s) upsertAlarmSite(cfg, g, s);
}

function parseAlarmCompareValue(raw) {
  const text = String(raw ?? '').trim();
  if (text === '') return { ok: false, error: 'Compare value is required for this alarm type.' };
  if (/^(true|false)$/i.test(text)) return { ok: true, value: text.toLowerCase() === 'true' };
  if (/^null$/i.test(text)) return { ok: true, value: null };
  if (/^-?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?$/i.test(text)) return { ok: true, value: Number(text) };
  if ((text.startsWith('"') && text.endsWith('"')) || text.startsWith('{') || text.startsWith('[')) {
    try { return { ok: true, value: JSON.parse(text) }; } catch { /* treat as plain text below */ }
  }
  return { ok: true, value: text };
}

function alarmCompareValueToText(alarm) {
  if (!alarm || typeof alarm !== 'object') return '';
  if (Object.prototype.hasOwnProperty.call(alarm, 'value')) {
    const v = unwrapAlarmCompareValue(alarm.value);
    if (typeof v === 'string') return v;
    try { return JSON.stringify(v); } catch { return String(v ?? ''); }
  }
  if (Object.prototype.hasOwnProperty.call(alarm, 'equals_value')) {
    const v = unwrapAlarmCompareValue(alarm.equals_value);
    if (typeof v === 'string') return v;
    try { return JSON.stringify(v); } catch { return String(v ?? ''); }
  }
  if (Object.prototype.hasOwnProperty.call(alarm, 'threshold')) return String(alarm.threshold);
  return '';
}

function applyAlarmTypeUi() {
  const type = String(els.editAlarmType?.value || '').trim();
  const isEquals = type === 'equals' || type === 'not_equals' || type === 'contains' || type === 'not_contains';
  const isLimit = type === 'high' || type === 'low';
  if (els.editAlarmValueRow) els.editAlarmValueRow.style.display = isEquals ? '' : 'none';
  if (els.editAlarmThresholdRow) els.editAlarmThresholdRow.style.display = isLimit ? '' : 'none';
  if (els.editAlarmHysteresisRow) els.editAlarmHysteresisRow.style.display = isLimit ? '' : 'none';
  updateAlarmPreview();
}

function severityLabel(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 'Unknown';
  if (n >= 900) return 'Critical';
  if (n >= 700) return 'High';
  if (n >= 500) return 'Medium';
  if (n >= 300) return 'Low';
  return 'Info';
}

function severityClass(value) {
  const label = severityLabel(value).toLowerCase();
  return `sev-${label}`;
}

function syncSeverityPresetFromValue() {
  if (!els.editAlarmSeverityPreset || !els.editAlarmSeverity) return;
  const val = String(Math.trunc(Number(els.editAlarmSeverity.value || '')));
  const matches = Array.from(els.editAlarmSeverityPreset.options || []).some((opt) => opt.value === val);
  els.editAlarmSeverityPreset.value = matches ? val : '';
}

function updateAlarmPreview() {
  if (!els.editAlarmPreview) return;
  const name = String(els.editAlarmName?.value || '').trim() || 'Alarm';
  const conn = String(els.editAlarmConn?.value || '').trim() || '<connection>';
  const tag = String(els.editAlarmTag?.value || '').trim() || '<tag>';
  const type = String(els.editAlarmType?.value || '').trim() || '<type>';
  const sevText = String(els.editAlarmSeverity?.value ?? '').trim();
  const sev = Math.max(0, Math.min(1000, Math.trunc(Number(sevText || '500') || 500)));
  const threshold = String(els.editAlarmThreshold?.value ?? '').trim();
  const hysteresis = String(els.editAlarmHysteresis?.value ?? '').trim();
  const compareValue = String(els.editAlarmValue?.value ?? '').trim();
  const alarmDelaySec = Math.max(0, Number(els.editAlarmDelaySec?.value || 0) || 0);
  const globalDelaySec = Math.max(0, Number(state.alarmsConfig?.alarm_delay_ms || 0) || 0) / 1000;
  const effectiveDelaySec = Math.max(alarmDelaySec, globalDelaySec);
  const enabled = Boolean(els.editAlarmEnabled?.checked);

  let condition = '';
  if (type === 'high') condition = `is greater than or equal to ${threshold || '<threshold>'}`;
  else if (type === 'low') condition = `is less than or equal to ${threshold || '<threshold>'}`;
  else if (type === 'equals') condition = `equals ${compareValue || '<value>'}`;
  else if (type === 'not_equals') condition = `does not equal ${compareValue || '<value>'}`;
  else if (type === 'contains') condition = `contains ${compareValue || '<text>'}`;
  else if (type === 'not_contains') condition = `does not contain ${compareValue || '<text>'}`;
  else if (type === 'empty') condition = 'is empty';
  else if (type === 'not_empty') condition = 'is not empty';
  else if (type === 'change') condition = 'changes value';
  else condition = `matches ${type}`;

  const h = (type === 'high' || type === 'low') && hysteresis ? ` with ${hysteresis} hysteresis` : '';
  const disabled = enabled ? '' : ' Disabled rules do not evaluate.';
  const delay = effectiveDelaySec > 0 ? ` Activation delay: ${effectiveDelaySec} sec.` : '';
  els.editAlarmPreview.textContent = `${name} triggers when ${conn}:${tag} ${condition}${h}. Severity: ${severityLabel(sev)} (${sev}).${delay}${disabled}`;
}

function alarmTypeLabel(type) {
  const t = String(type || '').trim();
  if (t === 'not_equals') return 'not equals';
  return t.replace(/_/g, ' ');
}

function generatedAlarmId(alarms = state.alarmsConfig?.alarms) {
  const used = new Set((Array.isArray(alarms) ? alarms : []).map((alarm) => String(alarm?.id || '').trim()).filter(Boolean));
  return opaqueObjectId('alarm', used);
}

function syncNewAlarmDefaults() {
  if (String(state.pendingWorkspaceItem?.mode || '') !== 'new') return;
  // Intentionally do not auto-fill text fields for new objects.
  // Keep this function around to update preview as the user selects fields.
  updateAlarmPreview();
}

function fillAlarmConnectionSelect(want = '') {
  if (!els.editAlarmConn) return;
  const conns = getAlarmConnectionIds();
  conns.sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' }));
  if (want) els.editAlarmConn.value = want;
  else if (!String(els.editAlarmConn.value || '').trim() && conns.length) els.editAlarmConn.value = String(conns[0] || '');
}

function getAlarmConnectionIds() {
  const seen = new Set();
  const out = [];
  const add = (value) => {
    const cid = String(value || '').trim();
    if (!cid || seen.has(cid)) return;
    seen.add(cid);
    out.push(cid);
  };
  (state.connFiles || []).forEach((f) => add(connectionIdForConnFilePath(String(f?.path || ''))));
  getEffectiveTagsAll().forEach((t) => add(t?.connection_id));
  add('_system');
  return out;
}

function maybeRefreshAlarmSourceLists(wantConnectionId = '') {
  const normalCount = getAlarmConnectionIds().filter((cid) => cid !== '_system').length;
  if (normalCount > 0 || state.alarmSourceListsLoading) return;
  state.alarmSourceListsLoading = true;
  Promise.all([
    loadConnectionsList().catch(() => null),
    loadTagsConfig().catch(() => null)
  ]).then(() => {
    fillAlarmConnectionSelect(wantConnectionId);
    refreshAlarmTagSelect();
  }).finally(() => {
    state.alarmSourceListsLoading = false;
  });
}

async function loadSystemTagsForSelection() {
  try {
    const resp = await apiGet('/api/opcbridge/tags?connection_id=_system&limit=1000', { timeoutMs: 10000 });
    state.systemTagsForSelection = Array.isArray(resp?.tags) ? resp.tags : [];
  } catch {
    state.systemTagsForSelection = Array.isArray(state.systemTagsForSelection) ? state.systemTagsForSelection : [];
  }
  return state.systemTagsForSelection;
}

async function refreshReporterSystemTagsForScada() {
  state.systemTagsForSelection = [];
  if (state.workspaceSystemChildrenCache instanceof Map) {
    state.workspaceSystemChildrenCache.clear();
  }
  try {
    await loadSystemTagsForSelection();
  } catch {
        // Non-fatal; the logger save/delete already completed.
  }
  if (isPanelActive('tab-workspace')) {
    await refreshVisible().catch(() => {});
    renderWorkspaceTree();
  }
  if (String(els.editAlarmConn?.value || '').trim() === '_system') {
    refreshAlarmTagSelect(String(els.editAlarmTag?.value || ''));
  }
}

function getAlarmCandidateTagsForConnection(connectionId) {
  const cid = String(connectionId || '').trim();
  if (cid === '_system') {
    const fromCache = Array.isArray(state.systemTagsForSelection) ? state.systemTagsForSelection : [];
    const fromLive = Array.isArray(state.liveTagsLast?.tags)
      ? state.liveTagsLast.tags.filter((t) => String(t?.connection_id || '') === '_system')
      : [];
    const byName = new Map();
    fromCache.concat(fromLive).forEach((t) => {
      const name = String(t?.name || '').trim();
      if (name) byName.set(name, { ...t, connection_id: '_system', name, system: true, writable: false });
    });
    return Array.from(byName.values());
  }
  return getEffectiveTagsAll().filter((t) => String(t?.connection_id || '') === cid);
}

function alarmSourceTagExists(connectionId, tagName) {
  const cid = String(connectionId || '').trim();
  const name = String(tagName || '').trim();
  if (!cid || !name) return false;
  return getAlarmCandidateTagsForConnection(cid).some((t) => String(t?.connection_id || '') === cid && String(t?.name || '') === name);
}

function getAlarmSourceTag(connectionId, tagName) {
  const cid = String(connectionId || '').trim();
  const name = String(tagName || '').trim();
  if (!cid || !name) return null;
  return getAlarmCandidateTagsForConnection(cid).find((t) => String(t?.connection_id || '') === cid && String(t?.name || '') === name) || null;
}

function alarmDatatypeClass(datatype) {
  const dt = String(datatype || '').trim().toLowerCase();
  if (dt === 'string') return 'string';
  if (dt === 'bool' || dt === 'boolean') return 'bool';
  if (['int16', 'uint16', 'int32', 'uint32', 'float32', 'float64', 'int64', 'uint64'].includes(dt)) return 'numeric';
  return 'unknown';
}

function alarmTypeOptionsForDatatype(datatype) {
  const labels = {
    high: 'High',
    low: 'Low',
    equals: 'Equals',
    not_equals: 'Not equals',
    contains: 'Contains',
    not_contains: 'Not contains',
    empty: 'Empty',
    not_empty: 'Not empty',
    change: 'Changed'
  };
  const cls = alarmDatatypeClass(datatype);
  const keys = cls === 'string'
    ? ['equals', 'not_equals', 'contains', 'not_contains', 'empty', 'not_empty', 'change']
    : cls === 'bool'
      ? ['equals', 'not_equals', 'change']
      : ['high', 'low', 'equals', 'not_equals', 'change'];
  return keys.map((value) => ({ value, label: labels[value] || value }));
}

function selectedAlarmSourceDatatype() {
  const tag = getAlarmSourceTag(els.editAlarmConn?.value, els.editAlarmTag?.value);
  return String(tag?.datatype || '').trim();
}

function refreshAlarmTypeOptions(preferred = '') {
  if (!els.editAlarmType) return;
  const current = String(preferred || els.editAlarmType.value || '').trim();
  const opts = alarmTypeOptionsForDatatype(selectedAlarmSourceDatatype());
  els.editAlarmType.textContent = '';
  opts.forEach((row) => {
    const opt = document.createElement('option');
    opt.value = row.value;
    opt.textContent = row.label;
    els.editAlarmType.appendChild(opt);
  });
  els.editAlarmType.value = opts.some((row) => row.value === current) ? current : String(opts[0]?.value || 'high');
  applyAlarmTypeUi();
}

function alarmGroupsSorted(cfgObj = state.alarmsConfig) {
  const cfg = ensureAlarmGroupsTree(cfgObj || {});
  return (Array.isArray(cfg.groups) ? cfg.groups : [])
    .slice()
    .filter((g) => String(g?.name || '').trim())
    .sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { numeric: true, sensitivity: 'base' }));
}

function fillAlarmGroupSelect(want = '') {
  if (!els.editAlarmGroup) return;
  const wantNorm = normalizeAlarmGroupName(want);
  const groups = alarmGroupsSorted(state.alarmsConfig);

  els.editAlarmGroup.textContent = '';
  const noneOpt = document.createElement('option');
  noneOpt.value = '';
  noneOpt.textContent = 'Unassigned';
  els.editAlarmGroup.appendChild(noneOpt);

  groups.forEach((g) => {
    const name = normalizeAlarmGroupName(g?.name || '');
    if (!name) return;
    const opt = document.createElement('option');
    opt.value = name;
    opt.textContent = name;
    els.editAlarmGroup.appendChild(opt);
  });

  if (wantNorm && !groups.some((g) => String(g?.name || '').trim().toLowerCase() === wantNorm.toLowerCase())) {
    const opt = document.createElement('option');
    opt.value = wantNorm;
    opt.textContent = `${wantNorm} (missing)`;
    els.editAlarmGroup.appendChild(opt);
  }

  els.editAlarmGroup.value = wantNorm || '';
  els.editAlarmGroup.disabled = !canEditConfig();
}

function fillAlarmSiteSelect(groupName, wantSite = '') {
  if (!els.editAlarmSite) return;
  const groupNorm = normalizeAlarmGroupName(groupName);
  const siteNorm = normalizeAlarmSiteName(wantSite);
  const group = groupNorm ? findAlarmGroupConfig(state.alarmsConfig || {}, groupNorm) : null;
  const sites = Array.isArray(group?.sites) ? group.sites : [];
  const siteNames = sites.map((s) => normalizeAlarmSiteName(s?.name || '')).filter(Boolean)
    .sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' }));

  els.editAlarmSite.textContent = '';
  const noneOpt = document.createElement('option');
  noneOpt.value = '';
  noneOpt.textContent = 'Unassigned';
  els.editAlarmSite.appendChild(noneOpt);

  siteNames.forEach((name) => {
    const opt = document.createElement('option');
    opt.value = name;
    opt.textContent = name;
    els.editAlarmSite.appendChild(opt);
  });

  if (siteNorm && !siteNames.some((s) => s.toLowerCase() === siteNorm.toLowerCase())) {
    const opt = document.createElement('option');
    opt.value = siteNorm;
    opt.textContent = `${siteNorm} (missing)`;
    els.editAlarmSite.appendChild(opt);
  }

  els.editAlarmSite.value = siteNorm || '';
  els.editAlarmSite.disabled = !canEditConfig() || !groupNorm;
}

function refreshAlarmTagSelect(want = '') {
  const cid = String(els.editAlarmConn?.value || '').trim();
  if (!els.editAlarmTag) return;
  if (cid === '_system' && !(state.systemTagsForSelection || []).length) {
    loadSystemTagsForSelection().then(() => refreshAlarmTagSelect(want)).catch(() => {});
  }
  if (want) els.editAlarmTag.value = want;
  refreshAlarmTypeOptions();
  setEditAlarmStatus('');
}

function readAlarmAudioFromUi() {
  const seq = state.alarmModalAudioSequenceInput?.getValues?.() || [];
  const audioFile = seq.length ? String(seq[0] || '').trim() : '';
  const gapRaw = String(els.editAlarmAudioGap?.value ?? '').trim();
  const out = {
    group: String(els.editAlarmGroup?.value || '').trim(),
    site: String(els.editAlarmSite?.value || '').trim(),
    audio_file: audioFile,
    audio_files: seq,
    speech_text: String(els.editAlarmSpeechText?.value || '').trim()
  };
  const audioMode = String(els.editAlarmAudioMode?.value || 'inherit').trim();
  if (audioMode && audioMode !== 'inherit') out.audio_mode = audioMode;
  if (gapRaw !== '') out.audio_gap_ms = Math.trunc(Number(gapRaw) || 0);
  return out;
}

function renderAlarmModalAudioSequence(cfgObj, values = []) {
  if (!els.editAlarmAudioSequenceMount) return;
  els.editAlarmAudioSequenceMount.textContent = '';
  state.alarmModalAudioSequenceInput = createAlarmAudioSequenceInput(cfgObj, values, {
    disabled: !canEditConfig(),
    onDirty: () => {
      refreshAlarmAudioUi(readAlarmAudioFromUi());
      updateAlarmPreview();
    }
  });
  if (state.alarmModalAudioSequenceInput?.wrap) {
    els.editAlarmAudioSequenceMount.appendChild(state.alarmModalAudioSequenceInput.wrap);
  }
}

function audioFileIdFromFilename(filename) {
  return String(filename || '')
    .trim()
    .replace(/\.[^.]+$/, '')
    .replace(/[^A-Za-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase() || 'audio';
}

function audioFilenameFromConfigFile(file) {
  const raw = String(file?.path || file?.id || '').trim();
  const parts = raw.split(/[\\/]/).filter(Boolean);
  return parts.length ? parts[parts.length - 1] : raw;
}

function audioFolderFromPath(pathValue) {
  let p = String(pathValue || '').trim().replace(/\\/g, '/');
  if (p.startsWith('audio/')) p = p.slice(6);
  const parts = p.split('/').filter(Boolean);
  parts.pop();
  return parts.join('/');
}

function normalizeAudioFolderName(value) {
  return String(value || '')
    .trim()
    .replace(/\\/g, '/')
    .split('/')
    .map((p) => p.trim())
    .filter(Boolean)
    .join('/');
}

function getConfiguredAudioFolders(cfgObj = state.alarmsConfig) {
  const folders = new Set();
  const explicit = Array.isArray(cfgObj?.audio?.folders) ? cfgObj.audio.folders : [];
  explicit.forEach((f) => {
    const folder = normalizeAudioFolderName(typeof f === 'string' ? f : f?.path);
    if (folder) folders.add(folder);
  });
  getAlarmAudioFiles(cfgObj || {}).forEach((f) => {
    const folder = normalizeAudioFolderName(audioFolderFromPath(f?.path));
    if (folder) folders.add(folder);
  });
  return Array.from(folders).sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
}

function expandAudioFolderPath(folder) {
  const clean = normalizeAudioFolderName(folder);
  state.alarmsEventsExpanded?.add?.('folder:alarms_events');
  state.alarmsEventsExpanded?.add?.('folder:audio_files');
  if (!clean) return;
  let cur = '';
  clean.split('/').filter(Boolean).forEach((part) => {
    cur = cur ? `${cur}/${part}` : part;
    state.alarmsEventsExpanded?.add?.(`audio_folder:${cur}`);
  });
}

function audioPathIsInFolder(pathValue, folder) {
  const cleanFolder = normalizeAudioFolderName(folder);
  if (!cleanFolder) return false;
  let p = String(pathValue || '').trim().replace(/\\/g, '/');
  if (p.startsWith('audio/')) p = p.slice(6);
  return p === cleanFolder || p.startsWith(`${cleanFolder}/`);
}

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, i + chunkSize);
    binary += String.fromCharCode(...chunk);
  }
  return btoa(binary);
}

async function uploadAlarmAudioFile(file, folder = '') {
  const filename = String(file.name || '').trim();
  if (!/\.(wav|mp3|ogg|flac)$/i.test(filename)) {
    throw new Error('Audio upload supports .wav, .mp3, .ogg, and .flac files.');
  }

  const cleanFolder = normalizeAudioFolderName(folder);
  const content_b64 = arrayBufferToBase64(await file.arrayBuffer());
  const resp = await apiPostJson('/api/opcbridge/config/audio/upload', { filename, folder: cleanFolder, content_b64 });
  if (!resp?.ok) throw new Error(resp?.error || 'Audio upload failed.');

  const cfg = state.alarmsConfig || { alarms: [], groups: [], audio: { files: [] } };
  if (!cfg.audio || typeof cfg.audio !== 'object' || Array.isArray(cfg.audio)) cfg.audio = {};
  if (!Array.isArray(cfg.audio.files)) cfg.audio.files = [];
  const idBase = audioFileIdFromFilename(filename);
  let id = idBase;
  let suffix = 2;
  const existing = new Set(cfg.audio.files.map((f) => String(f?.id || '').trim()).filter(Boolean));
  const existingForPath = cfg.audio.files.find((f) => String(f?.path || '').trim() === String(resp.path || `audio/${filename}`));
  if (existingForPath?.id) id = String(existingForPath.id);
  else {
    while (existing.has(id)) id = `${idBase}_${suffix++}`;
    cfg.audio.files.push({
      id,
      name: filename.replace(/\.[^.]+$/, ''),
      path: String(resp.path || `audio/${filename}`)
    });
  }

  await saveOpcbridgeAlarmsConfig(cfg);
  await loadOpcbridgeAlarmsConfig();
  return { id, filename };
}

async function uploadAlarmAudioFiles(files, folder = '') {
  const list = Array.from(files || []).filter(Boolean);
  if (!list.length) return [];

  const cleanFolder = normalizeAudioFolderName(folder);
  const cfg = await loadOpcbridgeAlarmsConfig();
  if (!cfg.audio || typeof cfg.audio !== 'object' || Array.isArray(cfg.audio)) cfg.audio = {};
  if (!Array.isArray(cfg.audio.files)) cfg.audio.files = [];
  if (cleanFolder) {
    if (!Array.isArray(cfg.audio.folders)) cfg.audio.folders = [];
    if (!cfg.audio.folders.includes(cleanFolder)) cfg.audio.folders.push(cleanFolder);
  }

  const existingIds = new Set(cfg.audio.files.map((f) => String(f?.id || '').trim()).filter(Boolean));
  const results = [];
  const failures = [];

  for (const file of list) {
    const filename = String(file?.name || '').trim();
    try {
      if (!/\.(wav|mp3|ogg|flac)$/i.test(filename)) {
        throw new Error('unsupported file type');
      }

      const content_b64 = arrayBufferToBase64(await file.arrayBuffer());
      const resp = await apiPostJson('/api/opcbridge/config/audio/upload', { filename, folder: cleanFolder, content_b64 });
      if (!resp?.ok) throw new Error(resp?.error || 'Audio upload failed.');

      const pathValue = String(resp.path || (cleanFolder ? `audio/${cleanFolder}/${filename}` : `audio/${filename}`));
      const existingForPath = cfg.audio.files.find((f) => String(f?.path || '').trim() === pathValue);
      let id = existingForPath ? String(existingForPath.id || '').trim() : '';
      if (!id) {
        const idBase = audioFileIdFromFilename(filename);
        id = idBase;
        let suffix = 2;
        while (existingIds.has(id)) id = `${idBase}_${suffix++}`;
        existingIds.add(id);
        cfg.audio.files.push({
          id,
          name: filename.replace(/\.[^.]+$/, ''),
          path: pathValue
        });
      } else {
        existingForPath.name = existingForPath.name || filename.replace(/\.[^.]+$/, '');
        existingForPath.path = pathValue;
      }
      results.push({ id, filename, path: pathValue });
    } catch (err) {
      failures.push({ filename: filename || '(unnamed)', error: String(err?.message || err) });
    }
  }

  if (results.length) {
    await saveOpcbridgeAlarmsConfig(cfg);
    await loadOpcbridgeAlarmsConfig();
  }
  if (failures.length) {
    const msg = failures.map((f) => `${f.filename}: ${f.error}`).join('\n');
    throw new Error(`${failures.length} upload(s) failed:\n${msg}`);
  }
  return results;
}

async function createAlarmAudioFolderInteractive(parentFolder = '') {
  if (!canEditConfig()) { window.alert('Login required to edit audio folders.'); return; }
  const base = normalizeAudioFolderName(parentFolder);
  const name = normalizeAudioFolderName(window.prompt('New audio folder name:', '') || '');
  if (!name) return;
  const folder = base ? `${base}/${name}` : name;
  const resp = await apiPostJson('/api/opcbridge/config/audio/folder', { folder });
  if (!resp?.ok) throw new Error(resp?.error || 'Audio folder create failed.');
  const cfg = await loadOpcbridgeAlarmsConfig();
  if (!cfg.audio || typeof cfg.audio !== 'object' || Array.isArray(cfg.audio)) cfg.audio = {};
  if (!Array.isArray(cfg.audio.folders)) cfg.audio.folders = [];
  if (!cfg.audio.folders.includes(folder)) cfg.audio.folders.push(folder);
  await saveOpcbridgeAlarmsConfig(cfg);
  await loadOpcbridgeAlarmsConfig();
  expandAudioFolderPath(folder);
  state.alarmsEventsSelectedNodeId = `audio_folder:${folder}`;
  renderAlarmsEventsTree();
}

async function moveAlarmAudioFileInteractive(id) {
  const cfg = await loadOpcbridgeAlarmsConfig();
  const file = getAlarmAudioFiles(cfg).find((f) => f.id === id) || null;
  if (!file) throw new Error(`Audio file '${id}' is not in the audio files list.`);
  const current = audioFolderFromPath(file.path);
  const folders = getConfiguredAudioFolders(cfg);
  const hint = folders.length ? `\nExisting folders:\n${folders.join('\n')}` : '';
  const folder = normalizeAudioFolderName(window.prompt(`Move '${file.name || id}' to folder. Leave blank for audio root.${hint}`, current) || '');
  const resp = await apiPostJson('/api/opcbridge/config/audio/move', { path: String(file.path || ''), folder });
  if (!resp?.ok) throw new Error(resp?.error || 'Audio move failed.');
  const entry = (Array.isArray(cfg.audio?.files) ? cfg.audio.files : []).find((f) => String(f?.id || '') === id);
  if (entry) entry.path = String(resp.path || entry.path || '');
  await saveOpcbridgeAlarmsConfig(cfg);
  await loadOpcbridgeAlarmsConfig();
  state.alarmsEventsSelectedNodeId = folder ? `audio_folder:${folder}` : 'folder:audio_files';
  state.alarmsEventsSelectedChildId = `audio_file:${id}`;
  renderAlarmsEventsTree();
}

async function deleteAlarmAudioFolderInteractive(folder) {
  const cleanFolder = normalizeAudioFolderName(folder);
  if (!cleanFolder) throw new Error('Audio folder is required.');
  if (!canEditConfig()) { window.alert('Login required to delete audio folders.'); return false; }
  const cfg = await loadOpcbridgeAlarmsConfig();
  const filesInFolder = getAlarmAudioFiles(cfg).filter((file) => audioPathIsInFolder(file?.path, cleanFolder));
  if (filesInFolder.length) {
    throw new Error(`Folder contains ${filesInFolder.length} audio file(s). Move or delete those files first.`);
  }
  const childFolders = getConfiguredAudioFolders(cfg).filter((f) => {
    const child = normalizeAudioFolderName(f);
    return child && child !== cleanFolder && child.startsWith(`${cleanFolder}/`);
  });
  if (childFolders.length) {
    throw new Error(`Folder contains ${childFolders.length} subfolder(s). Delete subfolders first.`);
  }
  if (!window.confirm(`Delete empty audio folder 'audio/${cleanFolder}'?`)) return false;
  const resp = await apiPostJson('/api/opcbridge/config/audio/folder/delete', { folder: cleanFolder });
  if (!resp?.ok) throw new Error(resp?.error || 'Audio folder delete failed.');
  if (!cfg.audio || typeof cfg.audio !== 'object' || Array.isArray(cfg.audio)) cfg.audio = {};
  if (Array.isArray(cfg.audio.folders)) {
    cfg.audio.folders = cfg.audio.folders.filter((f) => normalizeAudioFolderName(f) !== cleanFolder);
  }
  await saveOpcbridgeAlarmsConfig(cfg);
  await loadOpcbridgeAlarmsConfig();
  const parent = cleanFolder.split('/').slice(0, -1).join('/');
  expandAudioFolderPath(parent);
  state.alarmsEventsSelectedNodeId = parent ? `audio_folder:${parent}` : 'folder:audio_files';
  renderAlarmsEventsTree();
  return true;
}

async function uploadAlarmAudioFileFromUi() {
  const files = Array.from(els.editAlarmAudioUpload?.files || []);
  if (!files.length) { setEditAlarmStatus('Choose one or more audio files to upload.'); return; }

  setEditAlarmStatus(`Uploading ${files.length} audio file(s)…`);
  const results = await uploadAlarmAudioFiles(files);
  if (els.editAlarmAudioUpload) els.editAlarmAudioUpload.value = '';
  const last = results[results.length - 1] || null;
  if (last?.id) {
    const current = state.alarmModalAudioSequenceInput?.getValues?.() || [];
    renderAlarmModalAudioSequence(state.alarmsConfig || { alarms: [], groups: [], audio: { files: [] } }, current.concat([last.id]));
  }
  refreshAlarmAudioUi(readAlarmAudioFromUi());
  setEditAlarmStatus(`Uploaded ${results.length} audio file(s).`);
}

async function deleteAlarmAudioFileById(id) {
  const cfg = state.alarmsConfig || { alarms: [], groups: [], audio: { files: [] } };
  const file = getAlarmAudioFiles(cfg).find((f) => f.id === id) || null;
  if (!file) throw new Error(`Audio file '${id}' is not in the audio files list.`);

  const usedByAlarm = (Array.isArray(cfg.alarms) ? cfg.alarms : []).some((a) => String(a?.audio_file || '') === id || (Array.isArray(a?.audio_files) && a.audio_files.some((v) => String(v || '') === id)));
  const usedByGroup = (Array.isArray(cfg.groups) ? cfg.groups : []).some((g) => {
    if (String(g?.audio_file || '') === id) return true;
    if (Array.isArray(g?.audio_files) && g.audio_files.some((v) => String(v || '') === id)) return true;
    return (Array.isArray(g?.sites) ? g.sites : []).some((s) => String(s?.audio_file || '') === id || (Array.isArray(s?.audio_files) && s.audio_files.some((v) => String(v || '') === id)));
  });
  const usedByDefault = String(cfg.audio?.default_file || '') === id;
  const usage = [usedByDefault ? 'global default' : '', usedByGroup ? 'group/site' : '', usedByAlarm ? 'alarm' : ''].filter(Boolean).join(', ');
  const prompt = usage
    ? `Delete audio file '${file.name || id}'? It is referenced by ${usage}; references will be cleared.`
    : `Delete audio file '${file.name || id}'?`;
  if (!window.confirm(prompt)) return null;

  const filename = audioFilenameFromConfigFile(file);
  const resp = await apiPostJson('/api/opcbridge/config/audio/delete', { path: String(file.path || ''), filename });
  if (!resp?.ok) throw new Error(resp?.error || 'Audio delete failed.');

  cfg.audio.files = (Array.isArray(cfg.audio?.files) ? cfg.audio.files : []).filter((f) => String(f?.id || '') !== id);
  if (String(cfg.audio?.default_file || '') === id) delete cfg.audio.default_file;
  (Array.isArray(cfg.groups) ? cfg.groups : []).forEach((g) => {
    if (String(g?.audio_file || '') === id) delete g.audio_file;
    if (Array.isArray(g?.audio_files)) g.audio_files = g.audio_files.map((v) => String(v || '')).filter((v) => v !== id);
    (Array.isArray(g?.sites) ? g.sites : []).forEach((s) => {
      if (String(s?.audio_file || '') === id) delete s.audio_file;
      if (Array.isArray(s?.audio_files)) s.audio_files = s.audio_files.map((v) => String(v || '')).filter((v) => v !== id);
    });
  });
  (Array.isArray(cfg.alarms) ? cfg.alarms : []).forEach((a) => {
    if (String(a?.audio_file || '') === id) delete a.audio_file;
    if (Array.isArray(a?.audio_files)) a.audio_files = a.audio_files.map((v) => String(v || '')).filter((v) => v !== id);
  });

  await saveOpcbridgeAlarmsConfig(cfg);
  await loadOpcbridgeAlarmsConfig();
  return { id, filename };
}

async function deleteAlarmAudioFilesByIds(ids) {
  const unique = Array.from(new Set((Array.isArray(ids) ? ids : []).map((x) => String(x || '').trim()).filter(Boolean)));
  if (!unique.length) return [];

  const cfg = await loadOpcbridgeAlarmsConfig();
  const files = getAlarmAudioFiles(cfg).filter((f) => unique.includes(String(f?.id || '').trim()));
  if (!files.length) throw new Error('No matching audio files found to delete.');

  const names = files.map((f) => String(f?.name || f?.id || '').trim()).filter(Boolean);
  const prompt = `Delete ${files.length} audio file(s)? This cannot be undone.`;
  if (!window.confirm(prompt + (names.length ? `\n\n${names.slice(0, 15).join('\n')}${names.length > 15 ? '\n…' : ''}` : ''))) return [];

  const results = [];
  const failures = [];
  for (const file of files) {
    const id = String(file?.id || '').trim();
    if (!id) continue;
    const filename = audioFilenameFromConfigFile(file);
    try {
      const resp = await apiPostJson('/api/opcbridge/config/audio/delete', { path: String(file.path || ''), filename });
      if (!resp?.ok) throw new Error(resp?.error || `Audio delete failed for '${id}'.`);
      results.push({ id, filename });
    } catch (err) {
      failures.push({ id, error: String(err?.message || err) });
      continue;
    }

    // Remove from list and clear references.
    cfg.audio.files = (Array.isArray(cfg.audio?.files) ? cfg.audio.files : []).filter((f) => String(f?.id || '') !== id);
    if (String(cfg.audio?.default_file || '') === id) delete cfg.audio.default_file;
    (Array.isArray(cfg.groups) ? cfg.groups : []).forEach((g) => {
      if (String(g?.audio_file || '') === id) delete g.audio_file;
      if (Array.isArray(g?.audio_files)) g.audio_files = g.audio_files.map((v) => String(v || '')).filter((v) => v !== id);
      (Array.isArray(g?.sites) ? g.sites : []).forEach((s) => {
        if (String(s?.audio_file || '') === id) delete s.audio_file;
        if (Array.isArray(s?.audio_files)) s.audio_files = s.audio_files.map((v) => String(v || '')).filter((v) => v !== id);
      });
    });
    (Array.isArray(cfg.alarms) ? cfg.alarms : []).forEach((a) => {
      if (String(a?.audio_file || '') === id) delete a.audio_file;
      if (Array.isArray(a?.audio_files)) a.audio_files = a.audio_files.map((v) => String(v || '')).filter((v) => v !== id);
    });
  }

  await saveOpcbridgeAlarmsConfig(cfg);
  await loadOpcbridgeAlarmsConfig();
  if (failures.length) {
    const head = `Deleted ${results.length}/${files.length} audio file(s).`;
    const body = failures.slice(0, 15).map((f) => `${f.id}: ${f.error}`).join('\n');
    window.alert(`${head}\n\nFailures:\n${body}${failures.length > 15 ? '\n…' : ''}`);
  }
  return results;
}

async function deleteSelectedAlarmAudioFileFromUi() {
  const id = String(state.alarmModalAudioSequenceInput?.getSelectedValue?.() || '').trim();
  if (!id) { setEditAlarmStatus('Select a configured audio file to delete.'); return; }

  setEditAlarmStatus('Deleting audio file…');
  const result = await deleteAlarmAudioFileById(id);
  if (!result) return;
  refreshAlarmAudioUi(readAlarmAudioFromUi());
  setEditAlarmStatus(`Deleted audio file '${result.filename}'.`);
}

function chooseAndUploadAlarmAudioFile(folder = '') {
  const input = document.createElement('input');
  input.type = 'file';
  input.multiple = true;
  input.accept = '.wav,.mp3,.ogg,.flac,audio/*';
  input.addEventListener('change', () => {
    const files = Array.from(input.files || []);
    if (!files.length) return;
    uploadAlarmAudioFiles(files, folder)
      .then((results) => {
        const result = results[results.length - 1] || null;
        const cleanFolder = normalizeAudioFolderName(folder);
        state.alarmsEventsSelectedNodeId = cleanFolder ? `audio_folder:${cleanFolder}` : 'folder:audio_files';
        if (result?.id) state.alarmsEventsSelectedChildId = `audio_file:${result.id}`;
        expandAudioFolderPath(cleanFolder);
        renderAlarmsEventsTree();
      })
      .catch((err) => window.alert(`Audio upload failed: ${err.message}`));
  }, { once: true });
  input.click();
}

function refreshAlarmAudioUi(existingAlarm = null) {
  const cfg = state.alarmsConfig || { alarms: [], groups: [], audio: { files: [] } };
  const group = String(els.editAlarmGroup?.value || existingAlarm?.group || '').trim();
  const site = String(els.editAlarmSite?.value || existingAlarm?.site || '').trim();
  const alarm = existingAlarm || {};
  const inherited = resolveInheritedAlarmAudio(cfg, group, site);
  const effectiveAlarm = { ...alarm, group, site, audio_file: String(alarm.audio_file || '').trim(), speech_text: String(alarm.speech_text || '').trim() };
  const effective = resolveAlarmAudio(cfg, effectiveAlarm);

  if (els.editAlarmAudioMode && document.activeElement !== els.editAlarmAudioMode) {
    const mode = String(alarm.audio_mode || '').trim();
    els.editAlarmAudioMode.value = mode || 'inherit';
  }
  if (els.editAlarmAudioGap && document.activeElement !== els.editAlarmAudioGap) {
    const gap = Number(alarm.audio_gap_ms);
    els.editAlarmAudioGap.value = Number.isFinite(gap) && gap >= 0 ? String(Math.trunc(gap)) : '';
  }
  if (els.editAlarmSpeechText && document.activeElement !== els.editAlarmSpeechText) {
    els.editAlarmSpeechText.value = String(alarm.speech_text || '');
  }

  if (els.editAlarmAudioHint) {
    const sequenceText = alarmAudioSequenceText(effective.audio_files, cfg, effective.speech_texts, effective.audio_mode);
    els.editAlarmAudioHint.textContent = `Effective audio sequence: ${sequenceText}; source: ${effective.source}. Routing policies control whether and when this audio plays.`;
  }
}

function getAudioScopeConfig(cfg, scope, groupName, siteName) {
  if (!cfg.audio || typeof cfg.audio !== 'object' || Array.isArray(cfg.audio)) cfg.audio = {};
  if (scope === 'global') return cfg.audio;
  if (scope === 'group') return findAlarmGroupConfig(cfg, groupName);
  if (scope === 'site') return findAlarmSiteConfig(cfg, groupName, siteName);
  return null;
}

function getInheritedAudioForScope(cfg, scope, groupName, siteName) {
  if (scope === 'site') return resolveInheritedAlarmAudio(cfg, groupName, '');
  if (scope === 'group') {
    return {
      audio_file: String(cfg.audio?.default_file || '').trim(),
      speech_text: String(cfg.audio?.speech_text || '').trim(),
      speech_texts: String(cfg.audio?.speech_text || '').trim() ? [String(cfg.audio?.speech_text || '').trim()] : [],
      source: 'global'
    };
  }
  return { audio_file: '', speech_text: '', speech_texts: [], source: 'system' };
}

	function notificationDefaultRepeatMs(cfg) {
	  const routes = getAlarmNotificationRoutes(cfg);
	  const best = routes.find((r) => r && typeof r === 'object' && r.enabled !== false && String(r.type || '') === 'audio_command')
	    || routes.find((r) => r && typeof r === 'object' && r.enabled !== false);
	  const ms = Math.trunc(Number(best?.repeat_ms ?? best?.config?.repeat_ms ?? 0) || 0);
	  return (ms > 0) ? ms : 0;
	}

function getInheritedRepeatForScope(cfg, scope, groupName, siteName) {
  const global = notificationDefaultRepeatMs(cfg);
  if (scope === 'site') {
    const g = groupName ? findAlarmGroupConfig(cfg, groupName) : null;
    if (g && Object.prototype.hasOwnProperty.call(g, 'repeat_ms')) {
      const ms = Math.trunc(Number(g.repeat_ms ?? 0) || 0);
      return { repeat_ms: ms < 0 ? 0 : ms, source: 'group' };
    }
    return { repeat_ms: global, source: 'global' };
  }
  if (scope === 'group') {
    return { repeat_ms: global, source: 'global' };
  }
  return { repeat_ms: 0, source: 'system' };
}

function refreshAudioScopeUi() {
  const pending = state.pendingWorkspaceItem || {};
  const scope = String(pending.scope || '').trim();
  const group = String(pending.group || '').trim();
  const site = String(pending.site || '').trim();
  const cfg = state.alarmsConfig || { alarms: [], groups: [], audio: { files: [] } };
  ensureAlarmGroupsTree(cfg);
  const target = getAudioScopeConfig(cfg, scope, group, site) || {};
  const inherited = getInheritedAudioForScope(cfg, scope, group, site);
  const selected = scope === 'global'
    ? String(cfg.audio?.default_file || '').trim()
    : String(target?.audio_file || '').trim();
  const speechText = String(target?.speech_text || '').trim();

  if (els.editAudioScopeName) {
    els.editAudioScopeName.value = scope === 'global' ? 'Global alarm audio defaults' : (scope === 'site' ? `${group} / ${site}` : group);
  }
  if (els.editAudioScopeAudioFile) {
    els.editAudioScopeAudioFile.textContent = '';
    const base = document.createElement('option');
    base.value = '';
    base.textContent = scope === 'global'
      ? 'No default audio file'
      : (inherited.audio_file ? `Use inherited: ${alarmAudioFileText(inherited.audio_file, cfg)}` : 'Use inherited: none');
    els.editAudioScopeAudioFile.appendChild(base);
    getAlarmAudioFiles(cfg).forEach((f) => {
      const opt = document.createElement('option');
      opt.value = f.id;
      opt.textContent = f.path ? `${f.name || f.id} (${f.path})` : `${f.name || f.id} (${f.id})`;
      els.editAudioScopeAudioFile.appendChild(opt);
    });
    els.editAudioScopeAudioFile.value = selected;
    els.editAudioScopeAudioFile.disabled = !canEditConfig();
  }
  if (els.editAudioScopeSpeechText && document.activeElement !== els.editAudioScopeSpeechText) {
    els.editAudioScopeSpeechText.value = speechText;
    els.editAudioScopeSpeechText.disabled = !canEditConfig();
  }
  if (els.editAudioScopeHint) {
    const effectiveFile = selected || (scope === 'global' ? '' : inherited.audio_file);
    const effectiveSpeech = speechText || (scope === 'global' ? '' : inherited.speech_text);
    const source = scope === 'global' ? 'global' : (!selected ? inherited.source : scope);
    const sequence = alarmAudioSequenceText(effectiveFile ? [effectiveFile] : [], cfg, effectiveSpeech ? [effectiveSpeech] : []);
    els.editAudioScopeHint.textContent = `Effective audio sequence: ${sequence}; source: ${source}. Routing policies control whether and when this audio plays.`;
  }
  if (els.editAudioScopeSaveBtn) els.editAudioScopeSaveBtn.disabled = !canEditConfig();
}

function openAudioScopeModal({ scope, group = '', site = '' }) {
  if (!els.workspaceItemModal) return;
  const normalizedScope = String(scope || '').trim();
  state.pendingWorkspaceItem = { id: `audio_scope:${normalizedScope}:${group}:${site}`, type: 'audio_scope', scope: normalizedScope, group, site };
  if (els.workspaceItemModal) els.workspaceItemModal.style.display = 'flex';
  if (els.workspaceItemHint) {
    els.workspaceItemHint.textContent = normalizedScope === 'global'
      ? 'Default alarm audio settings.'
      : 'Alarm audio settings for this hierarchy level.';
  }
  if (els.workspaceItemDeviceEdit) els.workspaceItemDeviceEdit.style.display = 'none';
  if (els.workspaceItemTagEdit) els.workspaceItemTagEdit.style.display = 'none';
  if (els.workspaceItemAlarmEdit) els.workspaceItemAlarmEdit.style.display = 'none';
  if (els.workspaceItemEventEdit) els.workspaceItemEventEdit.style.display = 'none';
  if (els.workspaceItemAudioScopeEdit) els.workspaceItemAudioScopeEdit.style.display = 'none';
  if (els.workspaceItemGeneric) els.workspaceItemGeneric.style.display = 'none';
  if (els.workspaceItemAudioScopeEdit) els.workspaceItemAudioScopeEdit.style.display = 'block';
  const titleEl = document.getElementById('workspaceItemModalTitle');
  if (titleEl) titleEl.textContent = normalizedScope === 'global' ? 'Audio Defaults' : 'Alarm Audio Properties';
  setWorkspaceItemStatus('');
  setEditAudioScopeStatus('');
  refreshAudioScopeUi();
  els.editAudioScopeAudioFile?.focus?.();
}

async function saveAudioScopeFromModal() {
  if (!canEditConfig()) { setEditAudioScopeStatus('Login required to edit audio settings.'); return; }
  const pending = state.pendingWorkspaceItem || {};
  const scope = String(pending.scope || '').trim();
  const group = String(pending.group || '').trim();
  const site = String(pending.site || '').trim();
  const audioFile = String(els.editAudioScopeAudioFile?.value || '').trim();
  const speechText = String(els.editAudioScopeSpeechText?.value || '').trim();
  const cfg = state.alarmsConfig || { alarms: [], groups: [], audio: { files: [] } };
  ensureAlarmGroupsTree(cfg);
  if (!['global', 'group', 'site'].includes(scope)) { setEditAudioScopeStatus('Audio scope is invalid.'); return; }
  if (audioFile && !getAlarmAudioFiles(cfg).some((f) => f.id === audioFile)) { setEditAudioScopeStatus(`Audio file '${audioFile}' is not in the audio files list.`); return; }

  if (scope === 'global') {
    if (!cfg.audio || typeof cfg.audio !== 'object' || Array.isArray(cfg.audio)) cfg.audio = {};
    delete cfg.audio.audible_enabled;
    if (audioFile) cfg.audio.default_file = audioFile;
    else delete cfg.audio.default_file;
    if (speechText) cfg.audio.speech_text = speechText;
    else delete cfg.audio.speech_text;
  } else if (scope === 'group') {
    upsertAlarmGroup(cfg, group);
    const target = findAlarmGroupConfig(cfg, group);
    if (!target) { setEditAudioScopeStatus('Group was not found.'); return; }
    delete target.audible_enabled;
    if (audioFile) target.audio_file = audioFile;
    else delete target.audio_file;
    if (speechText) target.speech_text = speechText;
    else delete target.speech_text;
  } else if (scope === 'site') {
    ensureGroupSiteInConfig(cfg, group, site);
    const target = findAlarmSiteConfig(cfg, group, site);
    if (!target) { setEditAudioScopeStatus('Site was not found.'); return; }
    delete target.audible_enabled;
    if (audioFile) target.audio_file = audioFile;
    else delete target.audio_file;
    if (speechText) target.speech_text = speechText;
    else delete target.speech_text;
  }

  setEditAudioScopeStatus('Saving…');
  await saveOpcbridgeAlarmsConfig(cfg);
  await loadOpcbridgeAlarmsConfig();
  closeWorkspaceItemModal();
  renderWorkspaceTree();
}

function wireAlarmPreviewInputs() {
  const inputs = [
    els.editAlarmName,
    els.editAlarmGroup,
    els.editAlarmSite,
    els.editAlarmConn,
    els.editAlarmTag,
    els.editAlarmType,
    els.editAlarmEnabled,
    els.editAlarmAudioMode,
    els.editAlarmAudioGap,
    els.editAlarmSpeechText,
    els.editAlarmSeverity,
    els.editAlarmThreshold,
    els.editAlarmHysteresis,
    els.editAlarmDelaySec,
    els.editAlarmValue
  ].filter(Boolean);

  inputs.forEach((el) => {
    if (el.dataset.alarmPreviewWired === '1') return;
    el.dataset.alarmPreviewWired = '1';
    el.addEventListener('input', () => {
      if (el === els.editAlarmSeverity) syncSeverityPresetFromValue();
      if ([els.editAlarmConn, els.editAlarmTag, els.editAlarmType].includes(el)) syncNewAlarmDefaults();
      if ([els.editAlarmConn, els.editAlarmTag].includes(el)) refreshAlarmTypeOptions();
      if (el === els.editAlarmGroup) {
        const g = String(els.editAlarmGroup?.value || '').trim();
        fillAlarmSiteSelect(g, g ? String(els.editAlarmSite?.value || '') : '');
      }
      if ([els.editAlarmGroup, els.editAlarmSite, els.editAlarmAudioMode, els.editAlarmAudioGap, els.editAlarmSpeechText].includes(el)) refreshAlarmAudioUi(readAlarmAudioFromUi());
      updateAlarmPreview();
    });
    el.addEventListener('change', () => {
      if (el === els.editAlarmSeverity) syncSeverityPresetFromValue();
      if (el === els.editAlarmConn) {
        maybeRefreshAlarmSourceLists(String(els.editAlarmConn?.value || '').trim());
        refreshAlarmTypeOptions();
        syncNewAlarmDefaults();
      }
      if (el === els.editAlarmTag) refreshAlarmTypeOptions();
      if ([els.editAlarmTag, els.editAlarmType].includes(el)) syncNewAlarmDefaults();
      if (el === els.editAlarmGroup) {
        const g = String(els.editAlarmGroup?.value || '').trim();
        fillAlarmSiteSelect(g, g ? String(els.editAlarmSite?.value || '') : '');
      }
      if ([els.editAlarmGroup, els.editAlarmSite, els.editAlarmAudioMode, els.editAlarmAudioGap, els.editAlarmSpeechText].includes(el)) refreshAlarmAudioUi(readAlarmAudioFromUi());
      updateAlarmPreview();
    });
  });

  if (els.editAlarmTagPickBtn && els.editAlarmTagPickBtn.dataset.alarmSourcePickerWired !== '1') {
    els.editAlarmTagPickBtn.dataset.alarmSourcePickerWired = '1';
    els.editAlarmTagPickBtn.addEventListener('click', () => {
      openLoggerTagPickerModal({ mode: 'alarm_source' }).catch((err) => setEditAlarmStatus(`Tag picker failed: ${err.message || err}`));
    });
  }

  if (els.editAlarmSeverityPreset && els.editAlarmSeverityPreset.dataset.alarmPreviewWired !== '1') {
    els.editAlarmSeverityPreset.dataset.alarmPreviewWired = '1';
    els.editAlarmSeverityPreset.addEventListener('change', () => {
      const val = String(els.editAlarmSeverityPreset.value || '');
      if (val && els.editAlarmSeverity) els.editAlarmSeverity.value = val;
      updateAlarmPreview();
    });
  }

  updateAlarmPreview();
}

